INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Alexander','亚历山大（摇和）','难忘经典',ARRAY['30毫升 干邑白兰地','30毫升 棕可可奶油','30毫升鲜奶油'],'{"legacy":{"body":"亚历山大开创了\"奶油鸡尾酒\"（Cream Cocktail）这一整个品类。后来的金色梦想（Golden Dream——加利亚诺利口酒+橙汁+奶油，1960年代的迪斯科时代经典）、蚱蜢（Grasshopper——薄荷利口酒+可可利口酒+奶油，绿色奶油的视觉冲击）、白俄罗斯（Big Lebowski的标志）和Orgasm（爱尔兰奶油+咖啡利口酒+杏仁利口酒——1970年代油腻的调酒文化产物）都源于这个简单的三角公式：烈酒+利口酒+鲜奶油。\n\n在现代精品鸡尾酒吧中，亚历山大经历了革命性的复兴。调酒师们不再满足于用超市的盒装奶油——他们用椰子奶油（热带版）、燕麦奶（纯素版）、开心果奶（意大利版）甚至自制墨西哥辣椒浸泡奶油（辣味版）来替代传统鲜奶油。可可利口酒也不再是统一的工业产品——手工品牌如Tempus Fugit的Creme de Cacao使用真正的可可豆冷浸泡——让巧克力风味从\"糖浆味\"变成\"真正的好巧克力味\"。\n\n亚历山大这个配方——一百年后——仍然是调酒师测试他们的奶油摇和技巧的经典作品。一杯好的亚历山大：表面应该有一层微细的泡沫——白兰地的香气首先到达鼻腔——然后是可可的微苦在舌尖上展开——最后是奶油的丝滑在喉咙后延伸——这三者在口腔中不是叠加的，而是层层递进的。一杯糟糕的亚历山大：是一杯甜到发腻的白兰地糖奶油。","title":"延伸：奶油鸡尾酒的鼻祖与一百年的变奏"},"origin":{"body":"亚历山大（Alexander）的诞生笼罩在二十世纪初伦敦社交圈的迷雾中。最广为流传的版本指向1902年——伦敦Ciro''s Club的调酒师Troy Alexander为庆祝英国国王爱德华七世的加冕典礼而创作了这款酒。爱德华七世是维多利亚女王的继承人，他的加冕典礼是二十世纪初英国最重要的社交事件——亚历山大这款鸡尾酒以其名字（Alexander）向新国王致敬。\n\n这个版本的可信度在于时间线：1902年确实有一场对英国社交界至关重要的加冕典礼，而Ciro''s Club确实是当时伦敦上流社会精英聚集的场所——丘吉尔、王尔德、卡萨诺瓦都是常客。在那样一个场合创作一款鸡尾酒来纪念一位国王——这在1900年代的调酒文化中是标准做法：曼哈顿、马天尼和无数经典鸡尾酒都是在类似场合诞生的。\n\n另一个版本指向纽约——一家名为Rector''s的餐厅。1905年左右，一位名叫Alexander的铁路官员经常来这家餐厅用餐。他要求在鸡尾酒中加入鲜奶油——这在当时是极为大胆的要求。调酒师Troy Alexander（同一人？）为他调制了这款酒：白兰地（当时美国调酒的基础烈酒）、可可利口酒（一种新进口的欧洲利口酒）和鲜奶油（大胆的添加）——摇和至丝滑。这款鸡尾酒以这位铁路官员的名字命名。\n\n无论哪个版本是真的——亚历山大是历史上最早使用鲜奶油作为主要配料的鸡尾酒之一。白兰地的温暖、可可利口酒的微苦和鲜奶油的丝滑——三者形成了二十世纪初最不寻常的鸡尾酒三角结构。","title":"诞生：二十世纪初的伦敦社交圈"},"funFact":{"body":"鲜奶油在亚历山大中的使用——在今天看来似乎很普通——但在1900年代的调酒界是一个非常大胆的创新。当时的鸡尾酒几乎全部以烈酒、柑橘和糖为基础——加入乳制品完全打破了调酒界的常规，因为乳制品在室温下不稳定，容易变质。\n\n这杯鸡尾酒需要被充分摇和——不是仅仅混合，而是让鲜奶油完全乳化成一种丝绒般的悬浮液。摇和的时间比普通鸡尾酒长——至少15秒——以确保奶油不打碎（如果奶油在摇和中被打碎，它会释放黄油颗粒，让鸡尾酒变得油腻而不是丝滑）。这是调酒师需要专门练习的技巧：奶油摇和的力度、时间和温度——三者缺一不可。\n\n禁酒令时期（1920-1933），亚历山大经历了一次重要的配方变动。由于白兰地在地下酒吧中稀缺且昂贵（当时大部分白兰地来自欧洲进口，走私成本高昂），很多纽约的地下酒吧开始用金酒代替白兰地——创造出了\"Alexander #2\"。金酒版本比亚历山大更加锐利——金酒的杜松子为这杯原本甜腻的鸡尾酒增加了一层药草和松树的复杂苦味。到了1970年代，随着伏特加的流行——甚至出现了用伏特加的\"Alexander #3\"。但在大多数经典酒吧中，白兰地版本才是正统的\"亚历山大\"。\n\n在电影《谋杀绿脚趾》（The Big Lebowski，科恩兄弟，1998年）中，主角Jeff Lebowski（\"The Dude\"）的标志性饮品——\"白俄罗斯\"（伏特加+咖啡利口酒+奶油）——正是亚历山大的现代变奏。The Dude喝的每一杯白俄罗斯都在向一个世纪前的那杯亚历山大致敬。","title":"趣味事实：奶油的魔术和禁酒令时期的变身"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Americano','美国佬（直调）','难忘经典',ARRAY['30毫升 金巴利','30毫升 甜味美思','苏打水'],'{"legacy":{"body":"American是意大利开胃酒文化中最具代表性的作品之一。它与Aperol Spritz（阿佩罗橙光+普罗塞克+苏打水——更甜、更果香、更\"大众化\"）和Negroni（更深邃、更强壮、更\"内行化\"）共同构成了意大利\"餐前饮用\"的三大支柱。\n\n在意大利的日常生活中，Americano不是\"一杯鸡尾酒\"——它是下午5点到7点之间的仪式：坐在咖啡馆的露天座位上、点一杯Americano、一小碗橄榄或薯片、看着街上的行人和Vespa摩托车——这是意大利人日常的\"休息窗口\"。Americano的低酒精度（约8-10%ABV，因为大部分体积是苏打水）让你可以喝完一杯后还能正常开车回家——这与它的开胃酒身份是一致的——它不是\"让你醉\"的酒，是\"让晚餐更愉快\"的酒。\n\n今天在全球的精品酒吧中，Americano被新一代的调酒师重新发现。他们实验不同品牌的甜味美思（Cocchi Storico、Cinzano 1757、Martini Riserva）和金巴利的替代品（Braulio、Cynar、Averna）——但美国佬的核心公式不变：苦味利口酒+甜味美思+苏打水+橙片。这是意大利最简洁的平衡饮品之一——苦、甜、气泡——一个午后。","title":"延伸：意大利开胃酒文化的守护者"},"origin":{"body":"美国佬（Americano）的历史远比许多人意识到的更为古老——它诞生于1860年代的米兰，比大多数经典鸡尾酒早了半个世纪。在那个意大利统一运动高潮的年代，米兰正处于文化和商业的爆炸式发展期，而咖啡馆文化是这场社会运动的核心。\n\nGaspare Campari——金巴利苦酒（Campari）的创始人——是这场米兰咖啡馆革命的核心人物之一。Campari在14岁时就开始了在酒吧和咖啡馆的学徒生涯。1860年，他在米兰的诺瓦拉街（Via Novara）开设了自己的第一家咖啡馆。Campari注意到他的顾客喜欢在用餐前喝一杯能刺激食欲的饮品——意大利的\"开胃酒\"（aperitivo）传统正在形成。\n\n他将自己配制的苦酒（金巴利——用多达60种药草和水果在酒精中浸泡后过滤而成）与甜味美思混合——金巴利的苦和甜味美思的甜恰好形成一种令人上瘾的张力。加入苏打水让酒体更轻盈、更适合在温暖的下午饮用。他最初称这款酒为\"Milano-Torino\"（米兰-都灵）——因为金巴利产自米兰、甜味美思大多来自都灵。这个名字缺乏魅力——但它在米兰的咖啡馆中传播得很快。\n\n到了禁酒令时期（1920-1933），大量美国游客涌入意大利——因为在整个北美被禁酒令笼罩的13年里，意大利是少数几个可以合法饮酒的国家之一。美国游客爱上了这款清爽的开胃酒——金巴利的苦对他们来说是新鲜的、异国情调的体验。意大利的调酒师开始称这款酒为\"Americano\"——\"美国佬\"——因为点这款酒最多的就是这些在禁酒令时期涌来的美国人。\n\n一个历史的反讽：1920年代被禁酒令赶出美国的美国人——来到了意大利，发现了这杯叫Americano的鸡尾酒——然后回到美国，在地下酒吧里继续点这杯以他们自己民族命名的酒。禁酒令没有阻止美国人喝酒——它只是把美国的饮酒文化推到了全球。","title":"诞生：1860年代的米兰咖啡馆"},"funFact":{"body":"在伊恩·弗莱明（Ian Fleming）的第一部詹姆斯·邦德小说《皇家赌场》（Casino Royale，1953年）中，邦德在赌场酒吧点的第一杯鸡尾酒不是马天尼——而是一杯Americano。在书中的描写：邦德点了\"一杯Americano\"——然后自己加了一片柠檬皮。\n\n这个细节不是弗莱明随意写的——他本人是Americano的爱好者。在弗莱明常去的伦敦酒吧中，Americano是他的\"default order\"（默认点单）。在邦德的马天尼成为电影史上最著名的鸡尾酒台词之前——在文学邦德的世界里，Americano是他的第一杯鸡尾酒。\n\nAmericano也是内格罗尼（Negroni）的直接前身。1919年，佛罗伦萨的卡米洛·内格罗尼伯爵要求在Americano中用金酒代替苏打水——他刚从伦敦回来，在那里爱上了金酒。Americano的苏打水被金酒替换后——金巴利+甜味美思+金酒——内格罗尼从此诞生。可以说，没有Americano就没有内格罗尼——没有这两款酒——今天的全球鸡尾酒文化会完全不同。\n\n美国佬今天仍然是意大利最受欢迎的开胃酒之一。在米兰的任意一家咖啡馆的下午——你会看到一大片Americano的橙色杯影——金巴利和苏打水在冰块上形成微气泡——意大利人在喝他们的不朽的开胃酒。","title":"趣味事实：詹姆斯·邦德的第一杯酒与内格罗尼的前身"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Angel face','天使的面孔（摇和）','难忘经典',ARRAY['30毫升 杜松子酒','30毫升 杏子白兰地','30毫升 卡尔瓦多斯'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。天使的面孔诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在天使的面孔的基础上创造新的变奏：用不同的基酒代替30毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n天使的面孔的持久遗产在于：它证明了一个简单的配方——30毫升 杜松子酒、30毫升 杏子白兰地、30毫升 卡尔瓦多斯——可以被永恒地重新演绎而不失去其经典地位。一杯好的天使的面孔——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对天使的面孔有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"天使的面孔的传承——经典配方的现代演绎"},"origin":{"body":"天使的面孔是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n天使的面孔的核心配料包括30毫升 杜松子酒、30毫升 杏子白兰地、30毫升 卡尔瓦多斯。每一种配料都有其特定的角色：30毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于天使的面孔的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，天使的面孔通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解天使的面孔的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于天使的面孔——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"天使的面孔的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n天使的面孔的主要烈酒是30毫升 杜松子酒。选择优质品牌的30毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的天使的面孔通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制天使的面孔——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于天使的面孔的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Aviation','飞行（摇和）','难忘经典',ARRAY['45毫升 杜松子酒','15毫升 黑樱桃利口酒','15毫升 新鲜柠檬汁','1茶匙 紫罗兰利口酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。飞行诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在飞行的基础上创造新的变奏：用不同的基酒代替45毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n飞行的持久遗产在于：它证明了一个简单的配方——45毫升 杜松子酒、15毫升 黑樱桃利口酒、15毫升 新鲜柠檬汁、1茶匙 紫罗兰利口酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的飞行——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对飞行有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"飞行的传承——经典配方的现代演绎"},"origin":{"body":"飞行是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n飞行的核心配料包括45毫升 杜松子酒、15毫升 黑樱桃利口酒、15毫升 新鲜柠檬汁、1茶匙 紫罗兰利口酒。每一种配料都有其特定的角色：45毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于飞行的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，飞行通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解飞行的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于飞行——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"飞行的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n飞行的主要烈酒是45毫升 杜松子酒。选择优质品牌的45毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的飞行通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制飞行——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于飞行的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Between the Sheets','床笫之间（摇和）','难忘经典',ARRAY['30毫升白朗姆酒','30毫升 干邑白兰地','30毫升 橙皮利口酒','20毫升 新鲜柠檬汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。床笫之间诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在床笫之间的基础上创造新的变奏：用不同的基酒代替30毫升白朗姆酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n床笫之间的持久遗产在于：它证明了一个简单的配方——30毫升白朗姆酒、30毫升 干邑白兰地、30毫升 橙皮利口酒、20毫升 新鲜柠檬汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的床笫之间——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对床笫之间有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"床笫之间的传承——经典配方的现代演绎"},"origin":{"body":"床笫之间是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n床笫之间的核心配料包括30毫升白朗姆酒、30毫升 干邑白兰地、30毫升 橙皮利口酒、20毫升 新鲜柠檬汁。每一种配料都有其特定的角色：30毫升白朗姆酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升白朗姆酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于床笫之间的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，床笫之间通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解床笫之间的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于床笫之间——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"床笫之间的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n床笫之间的主要烈酒是30毫升白朗姆酒。选择优质品牌的30毫升白朗姆酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升白朗姆酒的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升白朗姆酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的床笫之间通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制床笫之间——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于床笫之间的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Boulevardier','花花公子（搅拌）','难忘经典',ARRAY['45毫升 波旁威士忌或黑麦威士忌','30 毫升 金巴利','30毫升 甜味美思'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。花花公子诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在花花公子的基础上创造新的变奏：用不同的基酒代替45毫升 波旁威士忌或黑麦威士忌来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n花花公子的持久遗产在于：它证明了一个简单的配方——45毫升 波旁威士忌或黑麦威士忌、30 毫升 金巴利、30毫升 甜味美思——可以被永恒地重新演绎而不失去其经典地位。一杯好的花花公子——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对花花公子有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"花花公子的传承——经典配方的现代演绎"},"origin":{"body":"花花公子是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n花花公子的核心配料包括45毫升 波旁威士忌或黑麦威士忌、30 毫升 金巴利、30毫升 甜味美思。每一种配料都有其特定的角色：45毫升 波旁威士忌或黑麦威士忌是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 波旁威士忌或黑麦威士忌展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于花花公子的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，花花公子通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解花花公子的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于花花公子——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"花花公子的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n花花公子的主要烈酒是45毫升 波旁威士忌或黑麦威士忌。选择优质品牌的45毫升 波旁威士忌或黑麦威士忌对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 波旁威士忌或黑麦威士忌的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 波旁威士忌或黑麦威士忌会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的花花公子通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制花花公子——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于花花公子的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Brandy Crusta','白兰地库斯塔（摇和）','难忘经典',ARRAY['52.5毫升 白兰地','7.5 毫升 黑樱桃利口酒','1茶勺 橙皮利口酒','15毫升 新鲜柠檬汁','一茶匙 单糖浆','1滴 安哥斯图拉苦精'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。白兰地库斯塔诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在白兰地库斯塔的基础上创造新的变奏：用不同的基酒代替52.5毫升 白兰地来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n白兰地库斯塔的持久遗产在于：它证明了一个简单的配方——52.5毫升 白兰地、7.5 毫升 黑樱桃利口酒、1茶勺 橙皮利口酒、15毫升 新鲜柠檬汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的白兰地库斯塔——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对白兰地库斯塔有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"白兰地库斯塔的传承——经典配方的现代演绎"},"origin":{"body":"白兰地库斯塔是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n白兰地库斯塔的核心配料包括52.5毫升 白兰地、7.5 毫升 黑樱桃利口酒、1茶勺 橙皮利口酒、15毫升 新鲜柠檬汁。每一种配料都有其特定的角色：52.5毫升 白兰地是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕52.5毫升 白兰地展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于白兰地库斯塔的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，白兰地库斯塔通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解白兰地库斯塔的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于白兰地库斯塔——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"白兰地库斯塔的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n白兰地库斯塔的主要烈酒是52.5毫升 白兰地。选择优质品牌的52.5毫升 白兰地对最终的结果至关重要——因为在这款鸡尾酒的配方中，52.5毫升 白兰地的个性无法被其他成分完全遮盖或稀释。一瓶好的52.5毫升 白兰地会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的白兰地库斯塔通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制白兰地库斯塔——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于白兰地库斯塔的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Casino','赌场（摇和）','难忘经典',ARRAY['40毫升 老汤姆杜松子酒','10毫升 黑樱桃利口酒','10 毫升 新鲜柠檬汁','2滴 橙子苦精'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。赌场诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在赌场的基础上创造新的变奏：用不同的基酒代替40毫升 老汤姆杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n赌场的持久遗产在于：它证明了一个简单的配方——40毫升 老汤姆杜松子酒、10毫升 黑樱桃利口酒、10 毫升 新鲜柠檬汁、2滴 橙子苦精——可以被永恒地重新演绎而不失去其经典地位。一杯好的赌场——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对赌场有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"赌场的传承——经典配方的现代演绎"},"origin":{"body":"赌场是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n赌场的核心配料包括40毫升 老汤姆杜松子酒、10毫升 黑樱桃利口酒、10 毫升 新鲜柠檬汁、2滴 橙子苦精。每一种配料都有其特定的角色：40毫升 老汤姆杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕40毫升 老汤姆杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于赌场的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，赌场通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解赌场的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于赌场——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"赌场的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n赌场的主要烈酒是40毫升 老汤姆杜松子酒。选择优质品牌的40毫升 老汤姆杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，40毫升 老汤姆杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的40毫升 老汤姆杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的赌场通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制赌场——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于赌场的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Clover Club','三叶草俱乐部（摇和）','难忘经典',ARRAY['45毫升 杜松子酒','15毫升 覆盆子糖浆','15 毫升 新鲜柠檬汁','蛋清'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。三叶草俱乐部诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在三叶草俱乐部的基础上创造新的变奏：用不同的基酒代替45毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n三叶草俱乐部的持久遗产在于：它证明了一个简单的配方——45毫升 杜松子酒、15毫升 覆盆子糖浆、15 毫升 新鲜柠檬汁、蛋清——可以被永恒地重新演绎而不失去其经典地位。一杯好的三叶草俱乐部——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对三叶草俱乐部有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"三叶草俱乐部的传承——经典配方的现代演绎"},"origin":{"body":"三叶草俱乐部是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n三叶草俱乐部的核心配料包括45毫升 杜松子酒、15毫升 覆盆子糖浆、15 毫升 新鲜柠檬汁、蛋清。每一种配料都有其特定的角色：45毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于三叶草俱乐部的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，三叶草俱乐部通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解三叶草俱乐部的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于三叶草俱乐部——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"三叶草俱乐部的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n三叶草俱乐部的主要烈酒是45毫升 杜松子酒。选择优质品牌的45毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的三叶草俱乐部通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制三叶草俱乐部——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于三叶草俱乐部的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Rusty Nail','生锈钉（搅拌）','难忘经典',ARRAY['45毫升 苏格兰威士忌','25毫升 杜林标'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。生锈钉诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在生锈钉的基础上创造新的变奏：用不同的基酒代替45毫升 苏格兰威士忌来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n生锈钉的持久遗产在于：它证明了一个简单的配方——45毫升 苏格兰威士忌、25毫升 杜林标——可以被永恒地重新演绎而不失去其经典地位。一杯好的生锈钉——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对生锈钉有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"生锈钉的传承——经典配方的现代演绎"},"origin":{"body":"生锈钉是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n生锈钉的核心配料包括45毫升 苏格兰威士忌、25毫升 杜林标。每一种配料都有其特定的角色：45毫升 苏格兰威士忌是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 苏格兰威士忌展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于生锈钉的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，生锈钉通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解生锈钉的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于生锈钉——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"生锈钉的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n生锈钉的主要烈酒是45毫升 苏格兰威士忌。选择优质品牌的45毫升 苏格兰威士忌对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 苏格兰威士忌的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 苏格兰威士忌会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的生锈钉通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制生锈钉——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于生锈钉的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Gin Fizz','金菲士（摇和）','难忘经典',ARRAY['45毫升 杜松子酒','30毫升 新鲜柠檬汁','10毫升 单糖浆','苏打水'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。金菲士诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在金菲士的基础上创造新的变奏：用不同的基酒代替45毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n金菲士的持久遗产在于：它证明了一个简单的配方——45毫升 杜松子酒、30毫升 新鲜柠檬汁、10毫升 单糖浆、苏打水——可以被永恒地重新演绎而不失去其经典地位。一杯好的金菲士——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对金菲士有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"金菲士的传承——经典配方的现代演绎"},"origin":{"body":"金菲士是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n金菲士的核心配料包括45毫升 杜松子酒、30毫升 新鲜柠檬汁、10毫升 单糖浆、苏打水。每一种配料都有其特定的角色：45毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于金菲士的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，金菲士通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解金菲士的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于金菲士——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"金菲士的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n金菲士的主要烈酒是45毫升 杜松子酒。选择优质品牌的45毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的金菲士通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制金菲士——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于金菲士的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Dry Martini','干马天尼（搅拌）','难忘经典',ARRAY['60毫升 杜松子酒','10毫升 干味美思'],'{"legacy":{"body":"马天尼可能是世界上最多变奏的鸡尾酒。脏马天尼（加橄榄盐水）在1980年代的华尔街交易员中流行——咸味和金酒的结合像是一种可以喝的交易策略。吉布森用腌洋葱代替橄榄——据说是一位旧金山的股票经纪人在交易大厅里要求调制一杯能让他集中注意力的马天尼。\n\n浓缩咖啡马天尼虽然名字里有马天尼，但不含金酒也不含味美思。它是1980年代伦敦的产物，反映了精品咖啡文化对调酒界的渗透。今天，单一产地浓缩咖啡和精品金酒的搭配已经成为高级酒吧的流行趋势。\n\n在21世纪的手工鸡尾酒运动中，马天尼再次成为焦点。调酒师们开始实验：柚子马天尼、椰子油洗金酒马天尼、甚至使用雪莉酒或日本清酒代替味美思的创新型马天尼。马天尼的故事没有终点——每一代人都在这个统一的公式上留下自己的印记。核心不变：冰镇的金酒、一丁点味美思、冷到可以在玻璃杯上写字的温度。","title":"延伸：一杯永远进化的酒，一百年来的每个变奏都在讲述自己的故事"},"origin":{"body":"干马天尼的确切起源存在争议，但这正是它魅力的一部分。最可信的说法指向1880年代旧金山的Martinez镇——一位调酒师为一位前往Martinez的旅客调制了这杯酒，用老汤姆金酒（当时的甜金酒）和甜味美思。\n\n后来金酒变干了。伦敦干金在19世纪末普及——这是工业革命的产物：连续蒸馏器的发明让金酒可以更高效、更纯净地生产。法国的Noilly Prat在1813年发明了干味美思——用白葡萄酒基酒，不加糖，药草味更脆更尖锐。当伦敦干金遇到法国干味美思——干马天尼诞生了。\n\n1911年，纽约Knickerbocker酒店的调酒师Martini di Arma di Taggia——一位意大利移民——为约翰·洛克菲勒调制了今天的版本：伦敦干金、干味美思、橙味苦精、柠檬皮。洛克菲勒喝了三杯，马天尼的纽约传奇从此开始。\n\n但真正让马天尼成为全球偶像的是禁酒令。1920年代，美国的地下酒吧里，在浴缸金酒和走私味美思的恶劣条件下，调酒师们被迫更加注重比例和冰镇技术——因为劣质原料需要用精确的技术来弥补。\n\n二战后的1950年代，伏特加马天尼开始流行——部分原因是James Bond的影响，部分原因是伏特加中性的味道让它比金酒更容易被大众接受。但纯化论者坚持：一杯真正的马天尼必须用金酒。伏特加马天尼只是一杯加了橄榄的伏特加。","title":"诞生：1880年代的美国，一杯永远进化的酒的起点"},"funFact":{"body":"詹姆斯·邦德的\"摇晃，不要搅拌\"是电影史上最著名的饮酒台词之一。但这句话从调酒学角度来说——是错误的。搅拌保持酒液丝滑透明，让烈酒的锋利不受气泡影响。摇晃则让金酒充气和稀释过度——邦德其实在喝一杯浑浊的、冰水稀释的马天尼。\n\n但007可能有他的理由。伊恩·弗莱明在1953年的《皇家赌场》中首次让邦德点马天尼。二战期间的伏特加马天尼用的是马铃薯伏特加——马铃薯伏特加油性重，摇晃有助于乳化。这是从那场战争中存活下来的间谍的饮酒习惯。\n\n关于比例——这也是一场战争。邱吉尔的马天尼是\"看一眼味美思瓶子就够了\"——他实际上只往杯子里加金酒和冰块，用眼神代替味美思。海明威的蒙哥马利马天尼是15:1的金酒与味美思比例——以蒙哥马利元帅命名，因为这位将军在战场上要15:1的兵力优势才肯进攻。\n\n橄榄是马天尼的经典装饰——它不仅是装饰，还改变了鸡尾酒的口感。橄榄在装瓶时浸泡在盐水中，携带的微量盐分进入金酒——盐抑制了舌头上的苦味感受器，让金酒的杜松子更圆润。这就是脏马天尼（加橄榄盐水）如此受欢迎的科学原因。\n\n一杯好的马天尼应该冷到可以在玻璃杯上写字的程度。搅拌时间通常在30-45秒——足够让酒液降温到零下2至零下3度，融化掉约占总体积20-25%的冰水。太短不够冷，太长过度稀释。完美的马天尼是一场与温度赛跑的游戏。","title":"趣味事实：摇晃vs搅拌的物理学、橄榄的化学和温度的极限"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Hanky Panky','翻云覆雨（搅拌）','难忘经典',ARRAY['45毫升 杜松子酒','45毫升 红味美思','7.5毫升 非奈特布兰卡苦酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。翻云覆雨诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在翻云覆雨的基础上创造新的变奏：用不同的基酒代替45毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n翻云覆雨的持久遗产在于：它证明了一个简单的配方——45毫升 杜松子酒、45毫升 红味美思、7.5毫升 非奈特布兰卡苦酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的翻云覆雨——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对翻云覆雨有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"翻云覆雨的传承——经典配方的现代演绎"},"origin":{"body":"翻云覆雨是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n翻云覆雨的核心配料包括45毫升 杜松子酒、45毫升 红味美思、7.5毫升 非奈特布兰卡苦酒。每一种配料都有其特定的角色：45毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于翻云覆雨的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，翻云覆雨通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解翻云覆雨的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于翻云覆雨——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"翻云覆雨的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n翻云覆雨的主要烈酒是45毫升 杜松子酒。选择优质品牌的45毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的翻云覆雨通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制翻云覆雨——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于翻云覆雨的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('John Collins','约翰科林斯（摇和）','难忘经典',ARRAY['45毫升 杜松子酒','30毫升 新鲜柠檬汁','15毫升 单糖浆','60毫升 苏打水'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。约翰科林斯诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在约翰科林斯的基础上创造新的变奏：用不同的基酒代替45毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n约翰科林斯的持久遗产在于：它证明了一个简单的配方——45毫升 杜松子酒、30毫升 新鲜柠檬汁、15毫升 单糖浆、60毫升 苏打水——可以被永恒地重新演绎而不失去其经典地位。一杯好的约翰科林斯——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对约翰科林斯有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"约翰科林斯的传承——经典配方的现代演绎"},"origin":{"body":"约翰科林斯是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n约翰科林斯的核心配料包括45毫升 杜松子酒、30毫升 新鲜柠檬汁、15毫升 单糖浆、60毫升 苏打水。每一种配料都有其特定的角色：45毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于约翰科林斯的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，约翰科林斯通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解约翰科林斯的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于约翰科林斯——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"约翰科林斯的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n约翰科林斯的主要烈酒是45毫升 杜松子酒。选择优质品牌的45毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的约翰科林斯通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制约翰科林斯——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于约翰科林斯的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Last word','临别一语（摇和）','难忘经典',ARRAY['22.5毫升 杜松子酒','22.5毫升 绿查特酒','22.5毫升 黑樱桃利口酒','22.5毫升 新鲜青柠汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。临别一语诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在临别一语的基础上创造新的变奏：用不同的基酒代替22.5毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n临别一语的持久遗产在于：它证明了一个简单的配方——22.5毫升 杜松子酒、22.5毫升 绿查特酒、22.5毫升 黑樱桃利口酒、22.5毫升 新鲜青柠汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的临别一语——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对临别一语有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"临别一语的传承——经典配方的现代演绎"},"origin":{"body":"临别一语是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n临别一语的核心配料包括22.5毫升 杜松子酒、22.5毫升 绿查特酒、22.5毫升 黑樱桃利口酒、22.5毫升 新鲜青柠汁。每一种配料都有其特定的角色：22.5毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕22.5毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于临别一语的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，临别一语通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解临别一语的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于临别一语——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"临别一语的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n临别一语的主要烈酒是22.5毫升 杜松子酒。选择优质品牌的22.5毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，22.5毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的22.5毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的临别一语通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制临别一语——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于临别一语的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Negroni','尼克罗尼（搅拌）','难忘经典',ARRAY['30毫升 杜松子酒','30毫升 金巴利','30毫升 甜味美思'],'{"legacy":{"body":"内格罗尼的等比例公式使其成为全世界调酒师最喜欢的实验平台。替代金酒——梅斯卡尔内格罗尼（烟熏版）、椰子油洗金酒内格罗尼、甚至用日本烧酎替代金酒的日式版本。替代金巴利——用各种阿玛罗和苦味利口酒：Cynar（洋蓟味）、Fernet-Branca（薄荷苦味）、Averna（焦糖甜苦）。替代甜味美思——用雪莉酒（Oloroso或PX）、波特酒、甚至日本梅酒。\n\n白色内格罗尼（Negroni Bianco）是2010年代的发明——用干味美思代替甜味美思、用Suze（法国龙胆利口酒）或Lillet Blanc代替金巴利。它是内格罗尼的另一个维度——更尖锐、更清脆、更白。\n\n错误内格罗尼（Negroni Sbagliato）是米兰的调酒师Mirko Stocchetto在1972年犯的一个错误——他用起泡酒代替了金酒。\"Sbagliato\"在意大利语中就是\"弄错了\"的意思。结果出人意料地好——更轻快、更有泡泡的庆祝感。\n\n内格罗尼对现代调酒的影响无法量化。它证明了苦味可以是优雅的，鸡尾酒不需要甜才能好喝。每一代调酒师都在这个1:1:1的公式上写下自己的名字。","title":"延伸：全世界调酒师最喜欢的实验平台，1:1:1的无限可能"},"origin":{"body":"1919年，意大利佛罗伦萨。卡米洛·内格罗尼伯爵走进Cafe Casoni酒吧。他刚从伦敦回来——在伦敦他爱上了金酒，一种在当时的意大利几乎不为人知的烈酒。\n\n伯爵对美国佬（Americano）很熟悉——金巴利+甜味美思+苏打水，这是当时米兰最流行的开胃酒。但他想要一杯更有劲的东西。他对调酒师Fosco Scarselli说：\"把苏打水换成金酒。\"Scarselli照做了，用橙片装饰代替了Americano的柠檬片——为了与金酒的风味匹配。橙皮油脂在金酒表面形成微光，苦、甜、药草在冰球上缓慢融合。内格罗尼就此诞生。\n\n伯爵的家族来自佛罗伦萨的贵族——一位内格罗尼伯爵曾经是非洲探险家，另一位是骑兵军官。卡米洛本人据描述是一位高大、英俊、有着浓密白色胡须的绅士，他每天下午都在Cafe Casoni的同一个角落喝他的同名酒。\n\n内格罗尼的配方简单到了极致：1:1:1——30ml金酒+30ml金巴利+30ml甜味美思。三个等量成分，没有任何一种占主导。金酒的杜松子+金巴利的苦+味美思的甜——三者不是加法，是乘法。这是鸡尾酒中最简洁、最优雅的公式之一。","title":"诞生：1919年的佛罗伦萨，一位伯爵改变了鸡尾酒的历史"},"funFact":{"body":"1947年，演员兼导演Orson Welles在罗马第一次喝到内格罗尼。他在给朋友的信中写道：\"苦味对肝脏有益，金酒对大脑有害。两者在一起，恰好平衡。\"这句不严谨的医学建议后来成为了内格罗尼最著名的非正式广告。\n\n1:1:1的比例是内格罗尼的数学魔法。没有任何其他经典鸡尾酒使用如此简单的等比例公式。大多数鸡尾酒是2:1:1或3:2:1——主烈酒占主导。但内格罗尼中，三种成分平起平坐。改变其中任何一种的比例都会让整杯酒坍缩成一个不同的存在。\n\n内格罗尼的橙片不是装饰——它是第三个嗅觉维度。橙皮油脂浮在金酒表面，在你端起杯子之前就进入你的鼻腔——苦味在舌头上、杜松子在舌根、橙油在鼻子里。内格罗尼是全感官的体验。\n\n2013年，Imbibe杂志和Campari集团发起了第一个内格罗尼周——全球各地的酒吧在卖出的每杯内格罗尼中捐出一部分给慈善机构。到今天，内格罗尼周已经在全球超过80个国家举办，筹集了数百万美元的善款。一杯意大利人的午后饮品，变成了全球调酒界的团结符号。","title":"趣味事实：Orson Welles的赞美、1:1:1的数学美和全球的内格罗尼周"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Manhattan','曼哈顿（搅拌）','难忘经典',ARRAY['50毫升 黑麦威士忌','20毫升 红味美思','1滴 安哥斯图拉苦精'],'{"legacy":{"body":"曼哈顿是鸡尾酒家族威士忌+味美思的创始人。罗伯·罗伊（Rob Roy）用苏格兰威士忌代替黑麦——诞生于1894年纽约华尔道夫酒店的一场苏格兰题材歌剧首演。黑色曼哈顿用Averna阿玛罗代替甜味美思——这个2005年诞生于旧金山的变奏是21世纪手工鸡尾酒运动中最成功的发明之一。\n\n曼哈顿也是电视和电影中最常出现的鸡尾酒之一——它是坐在皮椅上喝着深色烈酒的硬汉的视觉符号。电影《热情似火》中的百万富翁Osgood Fielding III说：\"我喝曼哈顿。\"他不必解释更多。\n\n今天曼哈顿仍然在高级酒吧中享有盛名。它不像马天尼那样遍布各种变体和颜色——曼哈顿是一杯深棕色的、安静的、自我的鸡尾酒。它不需要在意你是否理解它的美。","title":"延伸：罗伯·罗伊、黑色曼哈顿和威士忌复兴"},"origin":{"body":"曼哈顿的确切诞生日期是调酒史上最大的谜团之一。最广为人知的版本指向纽约曼哈顿俱乐部——1870年代，丘吉尔的母亲珍妮·杰罗姆在那里举办了一场宴会。据说调酒师为这个场合调制了这款酒——用黑麦威士忌（当时美国最主要的威士忌类型）、甜味美思（刚从意大利进口的新型开胃酒）和安格斯特拉苦精——曼哈顿从此诞生。\n\n但这个名字本身可能更早。1846年纽约就有报纸提到一种叫做曼哈顿的混合饮料。有些历史学家认为它是由一位名叫布莱克的调酒师在1860年代纽约百老汇的一家酒吧中创造的。\n\n无论哪种版本——曼哈顿是纽约的官方符号。它不像马天尼那样是清澈锋利的——曼哈顿是温暖的、饱满的、像一杯液体丝绒。黑麦威士忌的辛辣骨架穿透甜味美思的厚重，苦精在两者之间建立起一座芳香桥梁——苦甜辛辣的三角平衡。如果马天尼是鸡尾酒之王——曼哈顿就是王后。","title":"诞生：1870年代的纽约，一座城市的一杯酒"},"funFact":{"body":"曼哈顿的传统主义者坚持必须用黑麦威士忌——黑麦的辛辣骨架才能穿透甜味美思的厚重。波本派则偏爱它的甜美柔软。两者的争论激烈程度不亚于马天尼的摇晃vs搅拌。\n\n在19世纪的纽约，黑麦是默认的——因为当时黑麦是美国本土最主要的威士忌类型。波本几乎不为人知（波本产自肯塔基，在内战后的南方经济中尚未恢复）。所以如果你想要一杯历史准确的曼哈顿——用黑麦。\n\n完美曼哈顿用干味美思和甜味美思各半——Perfect在调酒术语中指的是干味美思和甜味美思的比例各占一半，不是完美无瑕的意思。\n\n关于樱桃：传统曼哈顿用黑樱桃做装饰——但工业化的糖渍樱桃在20世纪中后期取代了真正的黑樱桃利口酒浸泡樱桃。现代手工酒吧正在纠正这个错误——用Luxardo黑樱桃或自制白兰地浸泡樱桃代替工业版本。樱桃不应该是一颗红色的糖球——它应该是深色的、有酒味的、有樱桃的尊严。","title":"趣味事实：黑麦vs波本的百年战争、完美曼哈顿和樱桃的问题"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Martinez','马丁内斯（搅拌）','难忘经典',ARRAY['45毫升 伦敦干杜松子酒','45毫升 甜味美思','1茶勺 黑樱桃利口酒','2滴 橙子苦精'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。马丁内斯诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在马丁内斯的基础上创造新的变奏：用不同的基酒代替45毫升 伦敦干杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n马丁内斯的持久遗产在于：它证明了一个简单的配方——45毫升 伦敦干杜松子酒、45毫升 甜味美思、1茶勺 黑樱桃利口酒、2滴 橙子苦精——可以被永恒地重新演绎而不失去其经典地位。一杯好的马丁内斯——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对马丁内斯有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"马丁内斯的传承——经典配方的现代演绎"},"origin":{"body":"马丁内斯是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n马丁内斯的核心配料包括45毫升 伦敦干杜松子酒、45毫升 甜味美思、1茶勺 黑樱桃利口酒、2滴 橙子苦精。每一种配料都有其特定的角色：45毫升 伦敦干杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 伦敦干杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于马丁内斯的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，马丁内斯通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解马丁内斯的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于马丁内斯——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"马丁内斯的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n马丁内斯的主要烈酒是45毫升 伦敦干杜松子酒。选择优质品牌的45毫升 伦敦干杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 伦敦干杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 伦敦干杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的马丁内斯通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制马丁内斯——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于马丁内斯的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Mary Pickford','玛丽·毕克馥（摇和）','难忘经典',ARRAY['45毫升 白朗姆酒','45毫升 新鲜菠萝汁','7.5毫升 黑樱桃利口酒','5毫升 石榴糖浆'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。玛丽·毕克馥诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在玛丽·毕克馥的基础上创造新的变奏：用不同的基酒代替45毫升 白朗姆酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n玛丽·毕克馥的持久遗产在于：它证明了一个简单的配方——45毫升 白朗姆酒、45毫升 新鲜菠萝汁、7.5毫升 黑樱桃利口酒、5毫升 石榴糖浆——可以被永恒地重新演绎而不失去其经典地位。一杯好的玛丽·毕克馥——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对玛丽·毕克馥有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"玛丽·毕克馥的传承——经典配方的现代演绎"},"origin":{"body":"玛丽·毕克馥是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n玛丽·毕克馥的核心配料包括45毫升 白朗姆酒、45毫升 新鲜菠萝汁、7.5毫升 黑樱桃利口酒、5毫升 石榴糖浆。每一种配料都有其特定的角色：45毫升 白朗姆酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 白朗姆酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于玛丽·毕克馥的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，玛丽·毕克馥通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解玛丽·毕克馥的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于玛丽·毕克馥——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"玛丽·毕克馥的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n玛丽·毕克馥的主要烈酒是45毫升 白朗姆酒。选择优质品牌的45毫升 白朗姆酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 白朗姆酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 白朗姆酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的玛丽·毕克馥通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制玛丽·毕克馥——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于玛丽·毕克馥的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Monkey Gland','猴腺（摇和）','难忘经典',ARRAY['45毫升 干杜松子酒','45毫升 新鲜橙汁','1茶勺 石榴糖浆','1茶勺 苦艾酒（涮杯）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。猴腺诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在猴腺的基础上创造新的变奏：用不同的基酒代替45毫升 干杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n猴腺的持久遗产在于：它证明了一个简单的配方——45毫升 干杜松子酒、45毫升 新鲜橙汁、1茶勺 石榴糖浆、1茶勺 苦艾酒（涮杯）——可以被永恒地重新演绎而不失去其经典地位。一杯好的猴腺——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对猴腺有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"猴腺的传承——经典配方的现代演绎"},"origin":{"body":"猴腺是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n猴腺的核心配料包括45毫升 干杜松子酒、45毫升 新鲜橙汁、1茶勺 石榴糖浆、1茶勺 苦艾酒（涮杯）。每一种配料都有其特定的角色：45毫升 干杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 干杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于猴腺的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，猴腺通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解猴腺的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于猴腺——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"猴腺的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n猴腺的主要烈酒是45毫升 干杜松子酒。选择优质品牌的45毫升 干杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 干杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 干杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的猴腺通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制猴腺——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于猴腺的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Old Fashioned','古典鸡尾酒（搅拌）','难忘经典',ARRAY['45毫升 波旁威士忌或黑麦威士忌','1 个 方糖','几滴 安哥斯图拉苦精','几滴 水'],'{"legacy":{"body":"21世纪初的鸡尾酒复兴运动中，Old Fashioned成为了反甜腻鸡尾酒的旗帜。经过1980-1990年代的混合饮料时代——预调糖浆、果汁鸡尾酒、以甜味为主导的饮品——新一代调酒师开始回归简洁。Old Fashioned是他们的宣言：不甜、不果汁、不花哨。只有威士忌、一点糖、苦精、冰块和橙皮。\n\n电视剧《Mad Men》中的Don Draper在每一集都喝Old Fashioned——他把这杯酒重新带入流行文化。但讽刺的是，剧中的Old Fashioned用的是黑麦威士忌——这是20世纪初美国中产阶级的日常饮品。\n\n今天几乎所有好的威士忌酒吧都以它们的Old Fashioned为招牌。每个调酒师都有自己的配方：用什么威士忌、多少糖、哪种苦精、大冰还是碎冰。但核心不变——烈酒、糖、苦精。这是鸡尾酒的DNA。","title":"延伸：反甜腻鸡尾酒的旗帜，威士忌复兴的推手"},"origin":{"body":"古典鸡尾酒被称为鸡尾酒的鼻祖——不是因为它最老（虽然它确实很老），而是因为它实际上就是历史上第一款被定义为鸡尾酒的饮品。\n\n1806年5月13日，纽约《平衡与哥伦比亚知识库》周报刊登了一封读者来信。读者问：什么是鸡尾酒？编辑回复了历史上第一个书面定义：\"Cocktail is a stimulating liquor, composed of spirits of any kind, sugar, water, and bitters——鸡尾酒是一种由任意烈酒、糖、水和苦精组成的刺激性饮品。\"烈酒、糖、水、苦精。这四样东西放在一起——就是一杯Old Fashioned。\n\n但这个配方本身更古老。18世纪末的美国，苦精是从英国进口的专利药品——人们用小瓶装的苦精来治疗消化不良。在边远地区的酒馆里，人们发现往劣质威士忌里加一点苦精和糖可以让它好喝得多。这不是烹饪，是实用主义。\n\nOld Fashioned这个名字要到1880年代才出现。当时调酒师们开始在鸡尾酒里加苦艾酒、樱桃利口酒、菠萝汁和各种花哨的配料。一些坚持传统的饮酒者开始要求老式的做法——只要烈酒、糖、苦精和水。这个名字成为了光荣的徽章——它不接受时代的潮流。","title":"诞生：1806年之前，鸡尾酒本身的原型"},"funFact":{"body":"早期调酒师用方糖而不是糖浆。这不是为了方便——方糖可以被苦精浸透。正确的做法是将苦精滴在方糖上，让糖吸收苦精的每一滴，然后用捣棒将糖-苦精混合物捣碎，再加水融化。这个过程本身就是一种仪式——与你从瓶子里挤糖浆相比，它更慢、更专注、更古老。\n\n大冰块是Old Fashioned不可妥协的要素。小冰块融化快——你的威士忌会在几分钟内变成威士忌味的水。大冰块或冰球的表面积与体积比更小——融化慢、稀释慢——让威士忌的每一口都保持浓郁。一杯好的Old Fashioned，冰块应该是专门切割的大方块冰或冰球——用冰模提前制作。\n\n关于橙皮——它不是装饰，是调味品。将橙皮拧在杯口——这个动作为酒液表面注入了橙皮油脂。在Old Fashioned中，橙皮油脂在威士忌的甜苦之间架起一座桥梁：苦精的苦、糖的甜、橙油的清香。味道不是在嘴里结合的——在酒杯表面，在你举起杯子之前。","title":"趣味事实：方糖的仪式、大冰块的物理学和威士忌的尊严"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Paradise','天堂（摇和）','难忘经典',ARRAY['30毫升 杜松子酒','20毫升 杏子白兰地','15毫升 新鲜橙汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。天堂诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在天堂的基础上创造新的变奏：用不同的基酒代替30毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n天堂的持久遗产在于：它证明了一个简单的配方——30毫升 杜松子酒、20毫升 杏子白兰地、15毫升 新鲜橙汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的天堂——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对天堂有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"天堂的传承——经典配方的现代演绎"},"origin":{"body":"天堂是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n天堂的核心配料包括30毫升 杜松子酒、20毫升 杏子白兰地、15毫升 新鲜橙汁。每一种配料都有其特定的角色：30毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于天堂的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，天堂通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解天堂的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于天堂——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"天堂的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n天堂的主要烈酒是30毫升 杜松子酒。选择优质品牌的30毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的天堂通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制天堂——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于天堂的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Planters Punch','’种植者宾治（直调）','难忘经典',ARRAY['45毫升 牙买加朗姆酒','15毫升 青柠汁','30毫升甘蔗汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。’种植者宾治诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在’种植者宾治的基础上创造新的变奏：用不同的基酒代替45毫升 牙买加朗姆酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n’种植者宾治的持久遗产在于：它证明了一个简单的配方——45毫升 牙买加朗姆酒、15毫升 青柠汁、30毫升甘蔗汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的’种植者宾治——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对’种植者宾治有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"’种植者宾治的传承——经典配方的现代演绎"},"origin":{"body":"’种植者宾治是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n’种植者宾治的核心配料包括45毫升 牙买加朗姆酒、15毫升 青柠汁、30毫升甘蔗汁。每一种配料都有其特定的角色：45毫升 牙买加朗姆酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 牙买加朗姆酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于’种植者宾治的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，’种植者宾治通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解’种植者宾治的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于’种植者宾治——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"’种植者宾治的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n’种植者宾治的主要烈酒是45毫升 牙买加朗姆酒。选择优质品牌的45毫升 牙买加朗姆酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 牙买加朗姆酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 牙买加朗姆酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的’种植者宾治通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制’种植者宾治——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于’种植者宾治的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Porto Flip','波尔图菲利普（摇和）','难忘经典',ARRAY['15毫升 白兰地','45毫升 茶色波特酒','10毫升 蛋黄'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。波尔图菲利普诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在波尔图菲利普的基础上创造新的变奏：用不同的基酒代替15毫升 白兰地来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n波尔图菲利普的持久遗产在于：它证明了一个简单的配方——15毫升 白兰地、45毫升 茶色波特酒、10毫升 蛋黄——可以被永恒地重新演绎而不失去其经典地位。一杯好的波尔图菲利普——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对波尔图菲利普有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"波尔图菲利普的传承——经典配方的现代演绎"},"origin":{"body":"波尔图菲利普是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n波尔图菲利普的核心配料包括15毫升 白兰地、45毫升 茶色波特酒、10毫升 蛋黄。每一种配料都有其特定的角色：15毫升 白兰地是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕15毫升 白兰地展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于波尔图菲利普的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，波尔图菲利普通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解波尔图菲利普的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于波尔图菲利普——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"波尔图菲利普的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n波尔图菲利普的主要烈酒是15毫升 白兰地。选择优质品牌的15毫升 白兰地对最终的结果至关重要——因为在这款鸡尾酒的配方中，15毫升 白兰地的个性无法被其他成分完全遮盖或稀释。一瓶好的15毫升 白兰地会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的波尔图菲利普通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制波尔图菲利普——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于波尔图菲利普的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Ramos Fizz','拉莫斯菲士（摇和）','难忘经典',ARRAY['45毫升 杜松子酒','15毫升 新鲜青柠汁','15毫升 新鲜柠檬汁','30毫升 糖浆','60毫升 奶油','30毫升蛋清','3滴 橙花水','2 滴香草精','苏打水'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。拉莫斯菲士诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在拉莫斯菲士的基础上创造新的变奏：用不同的基酒代替45毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n拉莫斯菲士的持久遗产在于：它证明了一个简单的配方——45毫升 杜松子酒、15毫升 新鲜青柠汁、15毫升 新鲜柠檬汁、30毫升 糖浆——可以被永恒地重新演绎而不失去其经典地位。一杯好的拉莫斯菲士——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对拉莫斯菲士有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"拉莫斯菲士的传承——经典配方的现代演绎"},"origin":{"body":"拉莫斯菲士是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n拉莫斯菲士的核心配料包括45毫升 杜松子酒、15毫升 新鲜青柠汁、15毫升 新鲜柠檬汁、30毫升 糖浆。每一种配料都有其特定的角色：45毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于拉莫斯菲士的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，拉莫斯菲士通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解拉莫斯菲士的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于拉莫斯菲士——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"拉莫斯菲士的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n拉莫斯菲士的主要烈酒是45毫升 杜松子酒。选择优质品牌的45毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的拉莫斯菲士通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制拉莫斯菲士——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于拉莫斯菲士的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Sazerac','萨泽拉克（搅拌）','难忘经典',ARRAY['50毫升 干邑白兰地','1个 方糖','2滴 裴乔氏苦精','10毫升 苦艾酒（涮杯）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。萨泽拉克诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在萨泽拉克的基础上创造新的变奏：用不同的基酒代替50毫升 干邑白兰地来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n萨泽拉克的持久遗产在于：它证明了一个简单的配方——50毫升 干邑白兰地、1个 方糖、2滴 裴乔氏苦精、10毫升 苦艾酒（涮杯）——可以被永恒地重新演绎而不失去其经典地位。一杯好的萨泽拉克——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对萨泽拉克有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"萨泽拉克的传承——经典配方的现代演绎"},"origin":{"body":"萨泽拉克是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n萨泽拉克的核心配料包括50毫升 干邑白兰地、1个 方糖、2滴 裴乔氏苦精、10毫升 苦艾酒（涮杯）。每一种配料都有其特定的角色：50毫升 干邑白兰地是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕50毫升 干邑白兰地展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于萨泽拉克的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，萨泽拉克通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解萨泽拉克的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于萨泽拉克——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"萨泽拉克的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n萨泽拉克的主要烈酒是50毫升 干邑白兰地。选择优质品牌的50毫升 干邑白兰地对最终的结果至关重要——因为在这款鸡尾酒的配方中，50毫升 干邑白兰地的个性无法被其他成分完全遮盖或稀释。一瓶好的50毫升 干邑白兰地会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的萨泽拉克通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制萨泽拉克——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于萨泽拉克的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Stinger','史汀格（搅拌）','难忘经典',ARRAY['50毫升干邑白兰地','20毫升 白薄荷利口酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。史汀格诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在史汀格的基础上创造新的变奏：用不同的基酒代替50毫升干邑白兰地来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n史汀格的持久遗产在于：它证明了一个简单的配方——50毫升干邑白兰地、20毫升 白薄荷利口酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的史汀格——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对史汀格有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"史汀格的传承——经典配方的现代演绎"},"origin":{"body":"史汀格是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n史汀格的核心配料包括50毫升干邑白兰地、20毫升 白薄荷利口酒。每一种配料都有其特定的角色：50毫升干邑白兰地是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕50毫升干邑白兰地展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于史汀格的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，史汀格通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解史汀格的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于史汀格——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"史汀格的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n史汀格的主要烈酒是50毫升干邑白兰地。选择优质品牌的50毫升干邑白兰地对最终的结果至关重要——因为在这款鸡尾酒的配方中，50毫升干邑白兰地的个性无法被其他成分完全遮盖或稀释。一瓶好的50毫升干邑白兰地会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的史汀格通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制史汀格——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于史汀格的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Tuxedo','燕尾服（搅拌）','难忘经典',ARRAY['30毫升 老汤姆杜松子酒','30毫升 干味美思','1/2 茶匙 黑樱桃利口酒','1/4 茶匙 苦艾酒','3滴 橙子苦精'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。燕尾服诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在燕尾服的基础上创造新的变奏：用不同的基酒代替30毫升 老汤姆杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n燕尾服的持久遗产在于：它证明了一个简单的配方——30毫升 老汤姆杜松子酒、30毫升 干味美思、1/2 茶匙 黑樱桃利口酒、1/4 茶匙 苦艾酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的燕尾服——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对燕尾服有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"燕尾服的传承——经典配方的现代演绎"},"origin":{"body":"燕尾服是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n燕尾服的核心配料包括30毫升 老汤姆杜松子酒、30毫升 干味美思、1/2 茶匙 黑樱桃利口酒、1/4 茶匙 苦艾酒。每一种配料都有其特定的角色：30毫升 老汤姆杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 老汤姆杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于燕尾服的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，燕尾服通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解燕尾服的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于燕尾服——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"燕尾服的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n燕尾服的主要烈酒是30毫升 老汤姆杜松子酒。选择优质品牌的30毫升 老汤姆杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 老汤姆杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 老汤姆杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的燕尾服通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制燕尾服——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于燕尾服的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Mimosa','含羞草（直调）','当代经典',ARRAY['75毫升 鲜橙汁','75毫升 普罗赛克起泡酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。含羞草诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在含羞草的基础上创造新的变奏：用不同的基酒代替75毫升 鲜橙汁来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n含羞草的持久遗产在于：它证明了一个简单的配方——75毫升 鲜橙汁、75毫升 普罗赛克起泡酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的含羞草——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对含羞草有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"含羞草的传承——经典配方的现代演绎"},"origin":{"body":"含羞草是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n含羞草的核心配料包括75毫升 鲜橙汁、75毫升 普罗赛克起泡酒。每一种配料都有其特定的角色：75毫升 鲜橙汁是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕75毫升 鲜橙汁展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于含羞草的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，含羞草通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解含羞草的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于含羞草——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"含羞草的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n含羞草的主要烈酒是75毫升 鲜橙汁。选择优质品牌的75毫升 鲜橙汁对最终的结果至关重要——因为在这款鸡尾酒的配方中，75毫升 鲜橙汁的个性无法被其他成分完全遮盖或稀释。一瓶好的75毫升 鲜橙汁会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的含羞草通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制含羞草——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于含羞草的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Vieux Carre','老广场（搅拌）','难忘经典',ARRAY['30毫升 黑麦威士忌','30毫升 干邑白兰地','30毫升 甜味美思','1茶匙 法国廊酒','2滴 裴乔氏苦精'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。è老广场诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在è老广场的基础上创造新的变奏：用不同的基酒代替30毫升 黑麦威士忌来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\nè老广场的持久遗产在于：它证明了一个简单的配方——30毫升 黑麦威士忌、30毫升 干邑白兰地、30毫升 甜味美思、1茶匙 法国廊酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的è老广场——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对è老广场有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"è老广场的传承——经典配方的现代演绎"},"origin":{"body":"è老广场是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\nè老广场的核心配料包括30毫升 黑麦威士忌、30毫升 干邑白兰地、30毫升 甜味美思、1茶匙 法国廊酒。每一种配料都有其特定的角色：30毫升 黑麦威士忌是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 黑麦威士忌展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于è老广场的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，è老广场通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解è老广场的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于è老广场——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"è老广场的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\nè老广场的主要烈酒是30毫升 黑麦威士忌。选择优质品牌的30毫升 黑麦威士忌对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 黑麦威士忌的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 黑麦威士忌会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的è老广场通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制è老广场——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于è老广场的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Whiskey Sour','威士忌酸（摇和）','难忘经典',ARRAY['45毫升 波本威士忌','25毫升 新鲜柠檬汁','20毫升 单糖浆','20毫升蛋清（可选）'],'{"legacy":{"body":"威士忌酸是调酒界最基础的配方之一。它证明了烈酒+柠檬汁+糖这个简单的公式不需要被改进——它只需要被做好。今天几乎所有好的鸡尾酒吧都有一杯好的威士忌酸或它的变奏。\n\n21世纪的手工鸡尾酒运动中，威士忌酸也成为了实验平台。用不同种类的威士忌——黑麦、苏格兰混合麦芽、甚至日本威士忌——来创造不同风格的酸。加一点红酒漂浮在泡沫上——纽约酸（New York Sour）。加一点枫糖浆取代部分糖浆——秋天的威士忌酸。\n\n威士忌酸的核心不变量是：烈酒+柠檬汁+糖——所有变化都在这个黄金三角上建立。这是鸡尾酒界最持久的配方之一——因为它不可能被简化得比这三样东西更少了。","title":"延伸：酸的家族，调酒界最基础的公式"},"origin":{"body":"威士忌酸是鸡尾酒世界中最古老的公式之一——\"酸\"（Sour）本身就是一种鸡尾酒类型。它的原型可以追溯到19世纪中叶的美国海军——当时水手每天配给威士忌作为防坏血病的药，他们发现往威士忌里加柠檬汁和糖不仅更健康，而且更好喝。\n\n1862年，Jerry Thomas的《调酒师指南》——世界上第一本鸡尾酒书——正式收录了\"Whiskey Sour\"的配方：波本威士忌、柠檬汁、糖浆——用摇酒壶摇和。这个配方到现在几乎完全未变——160年前的配方和你今天在酒吧里点的威士忌酸是一样的。\n\n威士忌酸是\"酸\"鸡尾酒家族中最著名的一员。这个家族的公式是统一的：烈酒+柠檬汁+糖——可以套用在任何烈酒上。皮斯科酸（皮斯科+柠檬汁+糖+蛋清+苦精）、白兰地酸、朗姆酸、金酒酸——所有酸类鸡尾酒都共享这个DNA。","title":"诞生：1860年代，酸的家族和威士忌的结合"},"funFact":{"body":"蛋清在威士忌酸中是一个可选的但有争议的成分。加入蛋清可以让鸡尾酒产生一层丝滑的白色泡沫——\"波士顿酸\"（Boston Sour）就是加了蛋清的威士忌酸。蛋清不加任何味道，但它改变了一切：质地从爽脆变成丝绒。\n\n干摇（dry shake）是加入蛋清的关键步骤。没有冰的时候先摇一次——这被称为\"干摇\"——目的是让蛋清在没有稀释的情况下充分发泡。然后加冰再摇一次——\"湿摇\"——用来冷却和稀释。干摇+湿摇的组合让蛋清泡沫更密、更持久、更丝滑。\n\n有些人讨厌蛋清的\"蛋腥味\"——但一杯正确摇和的威士忌酸，蛋清应该完全融入，只留下泡沫和丝滑——没有任何异味。如果不加蛋清——这仍然是一杯好鸡尾酒，但它缺少了那种丝绸般的第一口。","title":"趣味事实：蛋清的争议、波士顿酸的丝绒革命和干摇的科学"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Bloody Mary','血腥玛丽（搅拌）','当代经典',ARRAY['45毫升 伏特加','90毫升 番茄汁','15毫升 新鲜柠檬汁','2滴 伍斯特酱油','塔巴斯科辣椒酱（可选）','芹菜盐（可选）'],'{"legacy":{"body":"血腥玛丽可能是世界上最具个人风格的鸡尾酒——每个调酒师都有自己的秘密配方。有人用伏特加，有人用龙舌兰（Bloody Maria），有人用金酒（Red Snapper）。有人加辣根，有人加蚝油，有人加培根伏特加（培根浸泡过的伏特加）。\n\n不同地区有不同的变体：加拿大的\"Caesar\"用番茄蛤蜊汁代替番茄汁；澳大利亚的\"Bloody Sunday\"用威士忌代替伏特加；南非的\"Bloody Dickens\"加了南非的chakalaka辣蔬菜调味酱。\n\n血腥玛丽的核心是：它是世界上唯一一种可以被合理称为\"饭\"的鸡尾酒。","title":"延伸：早午餐的王者，每个调酒师都有自己的秘密配方"},"origin":{"body":"血腥玛丽诞生在巴黎的Harry''s New York Bar——正是同一间酒吧发明了French 75和Sidecar。1921年，调酒师Fernand Petiot将等量的伏特加和番茄汁混合在一起。最初他称之为\"Bucket of Blood\"（一桶血）——这个名字不太有营销价值。\n\n一位顾客说它让他想起了芝加哥的Bucket of Blood俱乐部里的一位叫Mary的舞者。后来为了更优雅，改名为\"Bloody Mary\"——可能指向英国女王玛丽一世（她在位期间烧死了数百名新教徒，因此被称为\"血腥玛丽\"），也可能只是听起来更顺耳。Petiot后来移民到纽约，在St. Regis酒店的King Cole酒吧继续发展这款酒——在那里他加入了柠檬汁、伍斯特酱、辣椒酱和盐。\n\n今天的血腥玛丽和Fernand Petiot在1921年调的那杯根本不同——它已经进化成一种复杂到诡异的饮品：番茄汁、伏特加、柠檬汁、伍斯特酱、塔巴斯科辣酱、黑胡椒、芹菜盐、甚至牛肉高汤和辣根。","title":"诞生：1920年代的巴黎，Harry''s Bar不只有边车"},"funFact":{"body":"血腥玛丽被称为\"世界上最好喝的宿醉治愈剂\"——虽然科学并不同意。但其中有道理：番茄汁含有维生素C和抗氧化物质（番茄红素）；辣椒素（辣椒中的活性成分）刺激新陈代谢和血液循环；伏特加让宿醉的人\"再喝一口\"以缓解戒断症状。\n\n血腥玛丽也因此成为了早午餐的官方饮品——它可以合理地在上午11点端上餐桌——因为它是\"蔬菜\"。\n\n但近年来最引人注目的是血腥玛丽的装饰战争。一开始是一根芹菜茎。然后加了一片柠檬。然后加了一条培根。然后是整只虾。然后是汉堡、炸鸡、整个龙虾、甚至一整块披萨。切达威斯康辛的一家酒吧用一整只烤鸡做装饰——血腥玛丽已经从一杯鸡尾酒变成了一顿饭。","title":"趣味事实：宿醉治愈剂的传说、装​饰战争和世界上最被装饰的鸡尾酒"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('White Lady','白色佳人（摇和）','难忘经典',ARRAY['40毫升 杜松子酒','30毫升 橙皮利口酒','20毫升 新鲜柠檬汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。白色佳人诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在白色佳人的基础上创造新的变奏：用不同的基酒代替40毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n白色佳人的持久遗产在于：它证明了一个简单的配方——40毫升 杜松子酒、30毫升 橙皮利口酒、20毫升 新鲜柠檬汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的白色佳人——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对白色佳人有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"白色佳人的传承——经典配方的现代演绎"},"origin":{"body":"白色佳人是一款难忘经典鸡尾酒。IBA 官方将其列为「难忘经典」（The Unforgettables）——这意味着它不仅仅是\"经典\"，而是鸡尾酒历史上不可磨灭的里程碑。每一款难忘经典都代表了一个时代的品味、一位调酒师的才华或一个地方的文化。\n\n白色佳人的核心配料包括40毫升 杜松子酒、30毫升 橙皮利口酒、20毫升 新鲜柠檬汁。每一种配料都有其特定的角色：40毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕40毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于白色佳人的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，白色佳人通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解白色佳人的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于白色佳人——一杯难忘经典鸡尾酒的诞生"},"funFact":{"body":"白色佳人的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n白色佳人的主要烈酒是40毫升 杜松子酒。选择优质品牌的40毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，40毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的40毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的白色佳人通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制白色佳人——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于白色佳人的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Bellini','贝里尼（直调）','当代经典',ARRAY['100毫升 普罗赛克起泡酒','50毫升 白桃泥'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。贝里尼诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在贝里尼的基础上创造新的变奏：用不同的基酒代替100毫升 普罗赛克起泡酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n贝里尼的持久遗产在于：它证明了一个简单的配方——100毫升 普罗赛克起泡酒、50毫升 白桃泥——可以被永恒地重新演绎而不失去其经典地位。一杯好的贝里尼——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对贝里尼有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"贝里尼的传承——经典配方的现代演绎"},"origin":{"body":"贝里尼是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n贝里尼的核心配料包括100毫升 普罗赛克起泡酒、50毫升 白桃泥。每一种配料都有其特定的角色：100毫升 普罗赛克起泡酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕100毫升 普罗赛克起泡酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于贝里尼的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，贝里尼通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解贝里尼的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于贝里尼——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"贝里尼的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n贝里尼的主要烈酒是100毫升 普罗赛克起泡酒。选择优质品牌的100毫升 普罗赛克起泡酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，100毫升 普罗赛克起泡酒的个性无法被其他成分完全遮盖或稀释。一瓶好的100毫升 普罗赛克起泡酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的贝里尼通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制贝里尼——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于贝里尼的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Black Russian','黑俄罗斯人（搅拌）','当代经典',ARRAY['50毫升 伏特加','20毫升 咖啡利口酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。黑俄罗斯人诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在黑俄罗斯人的基础上创造新的变奏：用不同的基酒代替50毫升 伏特加来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n黑俄罗斯人的持久遗产在于：它证明了一个简单的配方——50毫升 伏特加、20毫升 咖啡利口酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的黑俄罗斯人——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对黑俄罗斯人有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"黑俄罗斯人的传承——经典配方的现代演绎"},"origin":{"body":"黑俄罗斯人是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n黑俄罗斯人的核心配料包括50毫升 伏特加、20毫升 咖啡利口酒。每一种配料都有其特定的角色：50毫升 伏特加是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕50毫升 伏特加展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于黑俄罗斯人的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，黑俄罗斯人通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解黑俄罗斯人的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于黑俄罗斯人——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"黑俄罗斯人的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n黑俄罗斯人的主要烈酒是50毫升 伏特加。选择优质品牌的50毫升 伏特加对最终的结果至关重要——因为在这款鸡尾酒的配方中，50毫升 伏特加的个性无法被其他成分完全遮盖或稀释。一瓶好的50毫升 伏特加会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的黑俄罗斯人通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制黑俄罗斯人——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于黑俄罗斯人的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Cosmopolitan','大都会（摇和）','当代经典',ARRAY['40毫升 柑橘伏特加','15毫升 君度利口酒','15毫升 新鲜青柠汁','30毫升 蔓越莓汁'],'{"legacy":{"body":"大都会是一个独特的文化现象：它是世界上第一款由电视剧传播到全球的鸡尾酒。在1998年之前——鸡尾酒是通过酒吧和调酒师口口相传而传播的。大都会改变了规则：它证明了电视可以比任何调酒师更快地将一杯鸡尾酒送到全球视野。\n\n这个现象在《欲望都市》之后被反复重现：《广告狂人》（Mad Men）让Old Fashioned和曼哈顿在2000年代末重新流行——Don Draper在每一集都喝Old Fashioned。《南方公园》让白俄罗斯（The Dude饮品）在大学宿舍中流行。但大都会是第一杯——它为后来所有\"电视鸡尾酒\"铺平了道路。\n\n大都会的持久遗产不是它的配方——而是它证明了流行文化和鸡尾酒可以互相塑造。在Instagram时代——一杯鸡尾酒的视觉吸引力在某些场景中比它的味道更重要——大都会在Instagram诞生前二十多年就已经理解了这一点。它是第一杯\"为被拍照而调制的鸡尾酒\"——粉红色永远不会让你失望。","title":"延伸：全球第一杯由电视创造的鸡尾酒、《欲望都市》后的二十年与粉红色的不朽"},"origin":{"body":"大都会（Cosmopolitan）的起源复杂到了让人困惑的程度——至少有三位调酒师声称自己是这款酒的发明者，每一位都有不同程度的可信度。\n\n版本一：迈阿密版本。1980年代中期，迈阿密南海滩的The Strand餐厅的调酒师Cheryl Cook声称她创造了第一款大都会。Cook注意到马天尼在顾客中极其流行——但很多人不喜欢金酒或味美思的味道。她用伏特加（无味烈酒）替代金酒、用蔓越莓汁替代味美思（提供酸度和颜色）、再加一点橙皮利口酒和青柠汁。Cook的版本使用了Absolut Citron——一种柠檬味的伏特加——这是1988年才上市的产品。\n\n版本二：纽约版本。1987年，曼哈顿的The Odeon酒吧的调酒师Toby Cecchini声称他独立地研制了同样的配方——而且他是第一个将这款酒称为\"Cosmopolitan\"的人。Cecchini的版本也是用Absolut Citron、橙皮利口酒（Cointreau）、蔓越莓汁和青柠汁。他在纽约Soho区的高级酒吧中供应这款酒——这里是曼哈顿社交名流和艺术家的聚集地。\n\n版本三：旧金山版本。1987年的旧金山——Cocktail Bill的酒吧声称他们的\"Cosmopolitan\"比上述两个版本都要早。\n\n无论谁最先调制了它——有一件事是没有任何争议的：1998年HBO电视剧《欲望都市》使大都会成为全球现象。Carrie、Miranda、Samantha和Charlotte在剧集中持续六季十一年不间断地点大都会——粉红色的大都会和曼哈顿四个女人的生活完美匹配。到电视剧完结的2004年，大都会已经成为了全世界最受欢迎的鸡尾酒之一。\n\n大都会不是手工鸡尾酒运动的经典——它是\"现代流行文化如何创造一款全球鸡尾酒\"的最经典案例。电视上的四个女人改变了全球的饮酒习惯。","title":"诞生：1970-1990年代，多重声称者的粉红色传奇"},"funFact":{"body":"大都会中的蔓越莓汁量很小——只有约15毫升。它的主要功能不是调味——蔓越莓汁本身的酸度太尖锐直白——而是染色。那标志性的粉红色是大都会的视觉签名：淡粉色的酒液在浅碗马天尼杯中，像一杯液体玫瑰——在酒吧的暗光下，这种颜色让它在Instagram出现之前的三十多年里就具有了\"可拍性\"。\n\n如果用白蔓越莓汁代替红色蔓越莓汁——你会得到一杯白色透明的大都会——味道几乎一样，但没有人认得出它。粉色就是大都会——没有粉色就没有\"Cosmo\"。这和《欲望都市》的海报颜色一致——这是那个时代最狡猾的跨界营销之一：电视剧中的女人们喝着一杯和她们海报颜色一致的鸡尾酒——没有人策划，但它刚好对了。\n\n大都会是\"Pink Drink\"（粉色饮品）现象的终极表达。\"Pink Drink\"是对这类以蔓越莓汁染粉色的伏特加鸡尾酒的非正式称呼——它们在整个1990年代和2000年代初在主流酒吧中占据主导地位。大都会是其中唯一获得全球认可并进入IBA官方分类的成员。\n\n尽管近年手工鸡尾酒吧对大都会多有冷落——认为它\"太甜\"、\"太粉\"、\"太90年代\"——但它仍然在酒店酒吧和派对场合中无处不在。不是每杯鸡尾酒都需要成为调酒哲学论文——有些鸡尾酒就是用来喝和聊天的——大都会就是这样的鸡尾酒。","title":"趣味事实：蔓越莓汁的密码、Pink Drink现象和《欲望都市》之后的宇宙"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Caipirinha','凯匹琳娜（直调）','当代经典',ARRAY['60毫升 卡萨沙','1颗青柠 切成小块','4茶匙 蔗糖'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。凯匹琳娜诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在凯匹琳娜的基础上创造新的变奏：用不同的基酒代替60毫升 卡萨沙来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n凯匹琳娜的持久遗产在于：它证明了一个简单的配方——60毫升 卡萨沙、1颗青柠 切成小块、4茶匙 蔗糖——可以被永恒地重新演绎而不失去其经典地位。一杯好的凯匹琳娜——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对凯匹琳娜有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"凯匹琳娜的传承——经典配方的现代演绎"},"origin":{"body":"凯匹琳娜是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n凯匹琳娜的核心配料包括60毫升 卡萨沙、1颗青柠 切成小块、4茶匙 蔗糖。每一种配料都有其特定的角色：60毫升 卡萨沙是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕60毫升 卡萨沙展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于凯匹琳娜的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，凯匹琳娜通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解凯匹琳娜的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于凯匹琳娜——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"凯匹琳娜的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n凯匹琳娜的主要烈酒是60毫升 卡萨沙。选择优质品牌的60毫升 卡萨沙对最终的结果至关重要——因为在这款鸡尾酒的配方中，60毫升 卡萨沙的个性无法被其他成分完全遮盖或稀释。一瓶好的60毫升 卡萨沙会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的凯匹琳娜通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制凯匹琳娜——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于凯匹琳娜的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Champagne Cocktail','香槟鸡尾酒（直调）','当代经典',ARRAY['90毫升 冰镇香槟','10毫升 干邑白兰地','2滴 安哥斯图拉苦酒','1个 方糖','几滴 柑曼怡（可选）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。香槟鸡尾酒诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在香槟鸡尾酒的基础上创造新的变奏：用不同的基酒代替90毫升 冰镇香槟来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n香槟鸡尾酒的持久遗产在于：它证明了一个简单的配方——90毫升 冰镇香槟、10毫升 干邑白兰地、2滴 安哥斯图拉苦酒、1个 方糖——可以被永恒地重新演绎而不失去其经典地位。一杯好的香槟鸡尾酒——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对香槟鸡尾酒有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"香槟鸡尾酒的传承——经典配方的现代演绎"},"origin":{"body":"香槟鸡尾酒是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n香槟鸡尾酒的核心配料包括90毫升 冰镇香槟、10毫升 干邑白兰地、2滴 安哥斯图拉苦酒、1个 方糖。每一种配料都有其特定的角色：90毫升 冰镇香槟是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕90毫升 冰镇香槟展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于香槟鸡尾酒的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，香槟鸡尾酒通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解香槟鸡尾酒的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于香槟鸡尾酒——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"香槟鸡尾酒的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n香槟鸡尾酒的主要烈酒是90毫升 冰镇香槟。选择优质品牌的90毫升 冰镇香槟对最终的结果至关重要——因为在这款鸡尾酒的配方中，90毫升 冰镇香槟的个性无法被其他成分完全遮盖或稀释。一瓶好的90毫升 冰镇香槟会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的香槟鸡尾酒通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制香槟鸡尾酒——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于香槟鸡尾酒的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Corpse Reviver 2 2','亡灵复活号（摇和）','当代经典',ARRAY['30毫升 杜松子酒','30毫升 君度利口酒','30毫升 白利莱利口酒','30毫升 新鲜柠檬汁','1滴 苦艾酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。亡灵复活号诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在亡灵复活号的基础上创造新的变奏：用不同的基酒代替30毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n亡灵复活号的持久遗产在于：它证明了一个简单的配方——30毫升 杜松子酒、30毫升 君度利口酒、30毫升 白利莱利口酒、30毫升 新鲜柠檬汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的亡灵复活号——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对亡灵复活号有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"亡灵复活号的传承——经典配方的现代演绎"},"origin":{"body":"亡灵复活号是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n亡灵复活号的核心配料包括30毫升 杜松子酒、30毫升 君度利口酒、30毫升 白利莱利口酒、30毫升 新鲜柠檬汁。每一种配料都有其特定的角色：30毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于亡灵复活号的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，亡灵复活号通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解亡灵复活号的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于亡灵复活号——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"亡灵复活号的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n亡灵复活号的主要烈酒是30毫升 杜松子酒。选择优质品牌的30毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的亡灵复活号通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制亡灵复活号——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于亡灵复活号的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Cuba Libre','自由古巴（直调）','当代经典',ARRAY['50毫升 白朗姆酒','120毫升 可口可乐','10毫升 新鲜青柠汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。自由古巴诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在自由古巴的基础上创造新的变奏：用不同的基酒代替50毫升 白朗姆酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n自由古巴的持久遗产在于：它证明了一个简单的配方——50毫升 白朗姆酒、120毫升 可口可乐、10毫升 新鲜青柠汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的自由古巴——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对自由古巴有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"自由古巴的传承——经典配方的现代演绎"},"origin":{"body":"自由古巴是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n自由古巴的核心配料包括50毫升 白朗姆酒、120毫升 可口可乐、10毫升 新鲜青柠汁。每一种配料都有其特定的角色：50毫升 白朗姆酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕50毫升 白朗姆酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于自由古巴的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，自由古巴通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解自由古巴的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于自由古巴——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"自由古巴的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n自由古巴的主要烈酒是50毫升 白朗姆酒。选择优质品牌的50毫升 白朗姆酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，50毫升 白朗姆酒的个性无法被其他成分完全遮盖或稀释。一瓶好的50毫升 白朗姆酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的自由古巴通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制自由古巴——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于自由古巴的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('French Connection','法国贩毒网（搅拌）','当代经典',ARRAY['35毫升 干邑白兰地','35毫升 杏仁利口酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。法国贩毒网诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在法国贩毒网的基础上创造新的变奏：用不同的基酒代替35毫升 干邑白兰地来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n法国贩毒网的持久遗产在于：它证明了一个简单的配方——35毫升 干邑白兰地、35毫升 杏仁利口酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的法国贩毒网——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对法国贩毒网有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"法国贩毒网的传承——经典配方的现代演绎"},"origin":{"body":"法国贩毒网是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n法国贩毒网的核心配料包括35毫升 干邑白兰地、35毫升 杏仁利口酒。每一种配料都有其特定的角色：35毫升 干邑白兰地是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕35毫升 干邑白兰地展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于法国贩毒网的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，法国贩毒网通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解法国贩毒网的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于法国贩毒网——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"法国贩毒网的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n法国贩毒网的主要烈酒是35毫升 干邑白兰地。选择优质品牌的35毫升 干邑白兰地对最终的结果至关重要——因为在这款鸡尾酒的配方中，35毫升 干邑白兰地的个性无法被其他成分完全遮盖或稀释。一瓶好的35毫升 干邑白兰地会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的法国贩毒网通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制法国贩毒网——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于法国贩毒网的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Golden Dream','金子梦（摇和）','当代经典',ARRAY['20毫升 加利安奴香草利口酒','20毫升 橙皮利口酒','20毫升 鲜橙汁','10毫升 鲜奶油'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。金子梦诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在金子梦的基础上创造新的变奏：用不同的基酒代替20毫升 加利安奴香草利口酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n金子梦的持久遗产在于：它证明了一个简单的配方——20毫升 加利安奴香草利口酒、20毫升 橙皮利口酒、20毫升 鲜橙汁、10毫升 鲜奶油——可以被永恒地重新演绎而不失去其经典地位。一杯好的金子梦——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对金子梦有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"金子梦的传承——经典配方的现代演绎"},"origin":{"body":"金子梦是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n金子梦的核心配料包括20毫升 加利安奴香草利口酒、20毫升 橙皮利口酒、20毫升 鲜橙汁、10毫升 鲜奶油。每一种配料都有其特定的角色：20毫升 加利安奴香草利口酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕20毫升 加利安奴香草利口酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于金子梦的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，金子梦通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解金子梦的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于金子梦——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"金子梦的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n金子梦的主要烈酒是20毫升 加利安奴香草利口酒。选择优质品牌的20毫升 加利安奴香草利口酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，20毫升 加利安奴香草利口酒的个性无法被其他成分完全遮盖或稀释。一瓶好的20毫升 加利安奴香草利口酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的金子梦通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制金子梦——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于金子梦的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Grasshopper','绿色蚱蜢（摇和）','当代经典',ARRAY['20毫升 白可可利口酒','20毫升 绿薄荷利口酒','20毫升 鲜奶油'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。绿色蚱蜢诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在绿色蚱蜢的基础上创造新的变奏：用不同的基酒代替20毫升 白可可利口酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n绿色蚱蜢的持久遗产在于：它证明了一个简单的配方——20毫升 白可可利口酒、20毫升 绿薄荷利口酒、20毫升 鲜奶油——可以被永恒地重新演绎而不失去其经典地位。一杯好的绿色蚱蜢——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对绿色蚱蜢有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"绿色蚱蜢的传承——经典配方的现代演绎"},"origin":{"body":"绿色蚱蜢是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n绿色蚱蜢的核心配料包括20毫升 白可可利口酒、20毫升 绿薄荷利口酒、20毫升 鲜奶油。每一种配料都有其特定的角色：20毫升 白可可利口酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕20毫升 白可可利口酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于绿色蚱蜢的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，绿色蚱蜢通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解绿色蚱蜢的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于绿色蚱蜢——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"绿色蚱蜢的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n绿色蚱蜢的主要烈酒是20毫升 白可可利口酒。选择优质品牌的20毫升 白可可利口酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，20毫升 白可可利口酒的个性无法被其他成分完全遮盖或稀释。一瓶好的20毫升 白可可利口酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的绿色蚱蜢通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制绿色蚱蜢——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于绿色蚱蜢的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Hemingway Special','海明威戴琦丽（摇和）','当代经典',ARRAY['60毫升 朗姆酒','40毫升 葡萄柚汁','15毫升 黑樱桃利口酒','15毫升 新鲜青柠汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。海明威戴琦丽诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在海明威戴琦丽的基础上创造新的变奏：用不同的基酒代替60毫升 朗姆酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n海明威戴琦丽的持久遗产在于：它证明了一个简单的配方——60毫升 朗姆酒、40毫升 葡萄柚汁、15毫升 黑樱桃利口酒、15毫升 新鲜青柠汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的海明威戴琦丽——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对海明威戴琦丽有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"海明威戴琦丽的传承——经典配方的现代演绎"},"origin":{"body":"海明威戴琦丽是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n海明威戴琦丽的核心配料包括60毫升 朗姆酒、40毫升 葡萄柚汁、15毫升 黑樱桃利口酒、15毫升 新鲜青柠汁。每一种配料都有其特定的角色：60毫升 朗姆酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕60毫升 朗姆酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于海明威戴琦丽的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，海明威戴琦丽通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解海明威戴琦丽的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于海明威戴琦丽——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"海明威戴琦丽的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n海明威戴琦丽的主要烈酒是60毫升 朗姆酒。选择优质品牌的60毫升 朗姆酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，60毫升 朗姆酒的个性无法被其他成分完全遮盖或稀释。一瓶好的60毫升 朗姆酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的海明威戴琦丽通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制海明威戴琦丽——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于海明威戴琦丽的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Horses Neck','’马颈（直调）','当代经典',ARRAY['40毫升 干邑白兰地','120毫升 干姜汽水','几滴 安哥斯图拉苦精（可选）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。’马颈诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在’马颈的基础上创造新的变奏：用不同的基酒代替40毫升 干邑白兰地来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n’马颈的持久遗产在于：它证明了一个简单的配方——40毫升 干邑白兰地、120毫升 干姜汽水、几滴 安哥斯图拉苦精（可选）——可以被永恒地重新演绎而不失去其经典地位。一杯好的’马颈——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对’马颈有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"’马颈的传承——经典配方的现代演绎"},"origin":{"body":"’马颈是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n’马颈的核心配料包括40毫升 干邑白兰地、120毫升 干姜汽水、几滴 安哥斯图拉苦精（可选）。每一种配料都有其特定的角色：40毫升 干邑白兰地是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕40毫升 干邑白兰地展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于’马颈的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，’马颈通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解’马颈的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于’马颈——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"’马颈的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n’马颈的主要烈酒是40毫升 干邑白兰地。选择优质品牌的40毫升 干邑白兰地对最终的结果至关重要——因为在这款鸡尾酒的配方中，40毫升 干邑白兰地的个性无法被其他成分完全遮盖或稀释。一瓶好的40毫升 干邑白兰地会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的’马颈通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制’马颈——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于’马颈的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('French 75','法国75（摇和）','当代经典',ARRAY['30毫升 杜松子酒','15毫升 新鲜柠檬汁','15毫升 单糖浆','60毫升 香槟'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。法国诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在法国的基础上创造新的变奏：用不同的基酒代替30毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n法国的持久遗产在于：它证明了一个简单的配方——30毫升 杜松子酒、15毫升 新鲜柠檬汁、15毫升 单糖浆、60毫升 香槟——可以被永恒地重新演绎而不失去其经典地位。一杯好的法国——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对法国有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"法国的传承——经典配方的现代演绎"},"origin":{"body":"法国是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n法国的核心配料包括30毫升 杜松子酒、15毫升 新鲜柠檬汁、15毫升 单糖浆、60毫升 香槟。每一种配料都有其特定的角色：30毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于法国的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，法国通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解法国的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于法国——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"法国的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n法国的主要烈酒是30毫升 杜松子酒。选择优质品牌的30毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的法国通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制法国——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于法国的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Margarita','玛格丽特（摇和）','当代经典',ARRAY['50毫升100%龙舌兰酒','20毫升 橙皮利口酒','15毫升 鲜榨青柠汁'],'{"legacy":{"body":"玛格丽特今天有无数变奏：冷冻玛格丽特（冰沙机版——1971年达拉斯餐厅老板Mariano Martinez用一台冰淇淋机改造了第一台玛格丽特冰沙机）、水果玛格丽特（草莓、芒果、西瓜、百香果——几乎所有热带水果都可以用来给玛格丽特上色和调味）、辣味玛格丽特（用jalapeno浸泡龙舌兰、加塔金辣椒粉——这是墨西哥街头风的升级版）、甚至梅斯卡尔玛格丽特（用烟熏梅斯卡尔代替龙舌兰——龙舌兰的烟熏远亲）。\n\n尽管大基数变体让纯化论者担忧——但玛格丽特的经典版本从未失去它的魅力。一杯正确调制的玛格丽特是世界上最清爽的饮品之一——咸、酸、甜、烈在同一个杯子里平衡。它既是一杯海滩饮品，也是一杯高级酒吧的正经鸡尾酒。","title":"延伸：全球最畅销的鸡尾酒之一，冰沙机没有毁掉它"},"origin":{"body":"玛格丽特的起源至少有四个互相竞争的版本。最有说服力的是：1938年，墨西哥蒂华纳的Carlos \"Danny\" Herrera为一位对除龙舌兰之外所有烈酒都过敏的舞者创造了这款酒——他将龙舌兰、橙皮利口酒和青柠汁摇在一起，加上盐边。这位舞者名叫Marjorie King——Herrera用她的名字Margarita（玛格丽特）命名了这杯酒。\n\n另一种版本指向达拉斯社交名流Margarita Sames。1948年，她在阿卡普尔科的派对中将这款酒介绍给了Tommy Hilton（希尔顿酒店家族的成员）。Hilton对这款酒印象深刻，把它放进了希尔顿酒店的全球酒单——从阿卡普尔科到巴黎——玛格丽特由此走向世界。\n\n还有第三种版本：1930年代蒂华纳的酒吧Agua Caliente的调酒师声称这款酒是他们发明的。第四种版本指向墨西哥城的Hussong''s Cantina——声称一位名叫Margarita Cansino的舞者是这款酒的灵感来源。没有人能确定哪个版本是真的——但所有版本都同意：它诞生在墨西哥。","title":"诞生：1930-1940年代的墨西哥，一个舞者与一杯传奇"},"funFact":{"body":"为什么玛格丽特有盐边？味觉科学给出了答案。盐抑制了舌头上的苦味感受器（TAS2R受体），同时增强了甜味和咸鲜味的感知。龙舌兰——尤其是100%的蓝色龙舌兰——带有一种独特的辛辣和植物性的苦味。盐边让龙舌兰的苦味边缘变得柔和，让青柠的酸更突出。\n\n杯子的处理也是一门科学。玛格丽特传统上装在被称为\"玛格丽特杯\"的特殊杯型中——这是一种阔口、浅碗、长脚的专门杯型。杯子必须在冰箱里预冷至少30分钟——或者用冰块快速预冷。冰镇杯壁可以让每一口玛格丽特保持低温更久——在墨西哥的烈日下，这决定了一杯玛格丽特能保持冰爽5分钟还是15分钟。\n\n每年2月22日是美国国家玛格丽特日。但一杯真正好的玛格丽特的秘诀一直没变：100%龙舌兰（不是混合酒mixto）、鲜榨青柠汁（不是瓶装酸汁）、以及一个好盐边。","title":"趣味事实：盐边的科学、冰镇杯的仪式和龙舌兰的尊严"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Irish Coffee','爱尔兰咖啡（直调）','当代经典',ARRAY['50毫升 爱尔兰威士忌','120毫升 热咖啡','50毫升 鲜奶油（冷藏）','1茶匙 糖'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。爱尔兰咖啡诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在爱尔兰咖啡的基础上创造新的变奏：用不同的基酒代替50毫升 爱尔兰威士忌来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n爱尔兰咖啡的持久遗产在于：它证明了一个简单的配方——50毫升 爱尔兰威士忌、120毫升 热咖啡、50毫升 鲜奶油（冷藏）、1茶匙 糖——可以被永恒地重新演绎而不失去其经典地位。一杯好的爱尔兰咖啡——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对爱尔兰咖啡有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"爱尔兰咖啡的传承——经典配方的现代演绎"},"origin":{"body":"爱尔兰咖啡是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n爱尔兰咖啡的核心配料包括50毫升 爱尔兰威士忌、120毫升 热咖啡、50毫升 鲜奶油（冷藏）、1茶匙 糖。每一种配料都有其特定的角色：50毫升 爱尔兰威士忌是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕50毫升 爱尔兰威士忌展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于爱尔兰咖啡的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，爱尔兰咖啡通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解爱尔兰咖啡的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于爱尔兰咖啡——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"爱尔兰咖啡的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n爱尔兰咖啡的主要烈酒是50毫升 爱尔兰威士忌。选择优质品牌的50毫升 爱尔兰威士忌对最终的结果至关重要——因为在这款鸡尾酒的配方中，50毫升 爱尔兰威士忌的个性无法被其他成分完全遮盖或稀释。一瓶好的50毫升 爱尔兰威士忌会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的爱尔兰咖啡通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制爱尔兰咖啡——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于爱尔兰咖啡的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('KIR','基尔（直调）','当代经典',ARRAY['90毫升 干白葡萄酒','10毫升 黑加仑利口酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。基尔诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在基尔的基础上创造新的变奏：用不同的基酒代替90毫升 干白葡萄酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n基尔的持久遗产在于：它证明了一个简单的配方——90毫升 干白葡萄酒、10毫升 黑加仑利口酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的基尔——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对基尔有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"基尔的传承——经典配方的现代演绎"},"origin":{"body":"基尔是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n基尔的核心配料包括90毫升 干白葡萄酒、10毫升 黑加仑利口酒。每一种配料都有其特定的角色：90毫升 干白葡萄酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕90毫升 干白葡萄酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于基尔的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，基尔通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解基尔的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于基尔——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"基尔的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n基尔的主要烈酒是90毫升 干白葡萄酒。选择优质品牌的90毫升 干白葡萄酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，90毫升 干白葡萄酒的个性无法被其他成分完全遮盖或稀释。一瓶好的90毫升 干白葡萄酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的基尔通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制基尔——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于基尔的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Long Island Ice Tea','长岛冰茶（摇和）','当代经典',ARRAY['15毫升 伏特加','15毫升 龙舌兰酒','15毫升 白朗姆酒','15毫升 杜松子酒','15毫升 君度','30毫升 柠檬汁','20毫升 单糖浆','可乐'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。长岛冰茶诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在长岛冰茶的基础上创造新的变奏：用不同的基酒代替15毫升 伏特加来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n长岛冰茶的持久遗产在于：它证明了一个简单的配方——15毫升 伏特加、15毫升 龙舌兰酒、15毫升 白朗姆酒、15毫升 杜松子酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的长岛冰茶——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对长岛冰茶有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"长岛冰茶的传承——经典配方的现代演绎"},"origin":{"body":"长岛冰茶是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n长岛冰茶的核心配料包括15毫升 伏特加、15毫升 龙舌兰酒、15毫升 白朗姆酒、15毫升 杜松子酒。每一种配料都有其特定的角色：15毫升 伏特加是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕15毫升 伏特加展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于长岛冰茶的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，长岛冰茶通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解长岛冰茶的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于长岛冰茶——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"长岛冰茶的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n长岛冰茶的主要烈酒是15毫升 伏特加。选择优质品牌的15毫升 伏特加对最终的结果至关重要——因为在这款鸡尾酒的配方中，15毫升 伏特加的个性无法被其他成分完全遮盖或稀释。一瓶好的15毫升 伏特加会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的长岛冰茶通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制长岛冰茶——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于长岛冰茶的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Mai-Tai','迈泰（摇和）','当代经典',ARRAY['30毫升 陈年牙买加朗姆酒','30毫升 马提尼克岛的朗姆酒（农业朗姆酒）','15毫升 橙皮利口酒','15毫升 杏仁利口酒','30毫升 新鲜柠檬汁','7.5毫升 单糖浆'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。迈泰诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在迈泰的基础上创造新的变奏：用不同的基酒代替30毫升 陈年牙买加朗姆酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n迈泰的持久遗产在于：它证明了一个简单的配方——30毫升 陈年牙买加朗姆酒、30毫升 马提尼克岛的朗姆酒（农业朗姆酒）、15毫升 橙皮利口酒、15毫升 杏仁利口酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的迈泰——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对迈泰有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"迈泰的传承——经典配方的现代演绎"},"origin":{"body":"迈泰是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n迈泰的核心配料包括30毫升 陈年牙买加朗姆酒、30毫升 马提尼克岛的朗姆酒（农业朗姆酒）、15毫升 橙皮利口酒、15毫升 杏仁利口酒。每一种配料都有其特定的角色：30毫升 陈年牙买加朗姆酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 陈年牙买加朗姆酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于迈泰的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，迈泰通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解迈泰的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于迈泰——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"迈泰的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n迈泰的主要烈酒是30毫升 陈年牙买加朗姆酒。选择优质品牌的30毫升 陈年牙买加朗姆酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 陈年牙买加朗姆酒的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 陈年牙买加朗姆酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的迈泰通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制迈泰——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于迈泰的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Mojito','莫吉托（直调）','当代经典',ARRAY['45毫升 古巴白朗姆酒','20毫升 新鲜青柠汁','6根 新鲜薄荷枝','2茶匙 白砂糖','苏打水'],'{"legacy":{"body":"莫吉托的成功让薄荷在鸡尾酒中成为了明星配料。后来的Southside（金酒+薄荷+柠檬汁）、Mint Julep（波本+薄荷+糖粉）和各式各样的水果莫吉托（草莓、芒果、百香果）都源于这个古巴配方。\n\n莫吉托也是全球最畅销的\"新鲜\"鸡尾酒——不同于那些可以使用预调糖浆和瓶装果汁的鸡尾酒，莫吉托要求新鲜的薄荷和鲜榨的青柠汁。这让它成为酒吧里最耗费时间制作的鸡尾酒之一——但它也是顾客最愿意等待的饮品之一。\n\n一杯好的莫吉托，薄荷的香气应该在端上来之前就飘到你的鼻子里——青柠的酸、朗姆的微甜、苏打水的气泡在舌头上跳舞——薄荷不抢戏，但把一切都串在一起。这就是古巴夏天装在杯子里的样子。","title":"延伸：全球最畅销的新鲜鸡尾酒，薄荷成为了明星配料"},"origin":{"body":"莫吉托的起源比大多数鸡尾酒都要古老。16世纪，英国海盗理查德·德雷克爵士（Sir Francis Drake）的手下在古巴海岸登陆时，当地原住民给他们喝了一种用未加工的朗姆酒（aguardiente——一种粗糙的甘蔗烈酒）、青柠汁、薄荷和糖兑成的药酒。\n\n这种混合物的初衷是预防疾病——青柠提供维生素C（防止坏血病）、薄荷助消化和退热、糖平衡苦味和提供能量、朗姆酒杀菌和麻痹疼痛。它从未打算好喝——但几个世纪后，它变成了全球最受欢迎的鸡尾酒之一。\n\n到了1940年代，莫吉托已经进化成今天的样子：使用白朗姆酒（而非粗糙的aguardiente）、鲜榨青柠汁、新鲜薄荷叶、细砂糖和苏打水。La Bodeguita del Medio酒吧——哈瓦那老城的一间小酒吧——声称拥有最正宗的莫吉托配方。","title":"诞生：16世纪的古巴，海盗的药品变成了全世界的饮品"},"funFact":{"body":"海明威在哈瓦那有两个常去的酒吧：El Floridita（大吉利）和La Bodeguita del Medio（莫吉托）。后者的墙上至今挂着一块海明威手写的牌子：\"我的莫吉托在La Bodeguita，我的大吉利在El Floridita\"。今天那间小酒吧每天卖出数百杯莫吉托，游客们排队在墙上签名——海明威开了一个好头。\n\n薄荷的处理是莫吉托中最容易出错的一步。薄荷不是被捣碎的——是被轻轻拍打释放精油的。过度捣碎薄荷叶会释放叶绿素——叶绿素是苦的——让莫吉托变苦。正确的做法是将薄荷叶放在手掌心轻轻拍打一下，然后放入杯中——或者用捣棒轻轻按压一两次，刚好让叶子释放精油但不碎裂。\n\n关于冰量：莫吉托必须是加满碎冰或小冰块的——这不仅仅是温度的问题。莫吉托是\"长饮\"（long drink）——你喝的时候冰在融化，苏打水在起泡，薄荷在释放更多精油——第一口和最后一口是不同的饮品。这是莫吉托的魅力——它是动态的、演变中的鸡尾酒。","title":"趣味事实：海明威的签名、薄荷的正确拍法和莫吉托的冰量"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Moscow Mule','莫斯科骡子（直调）','当代经典',ARRAY['45毫升 斯米诺伏特加','120毫升 姜汁啤酒','10毫升 新鲜青柠汁'],'{"legacy":{"body":"莫斯科骡子不仅仅是一杯鸡尾酒——它是伏特加在美国的成功故事。在1941年之前，伏特加在美国几乎不为人知。莫斯科骡子的爆发让伏特加成为了美国主流的烈酒种类之一——这个地位一直保持到今天：伏特加是美国最畅销的烈酒类型。\n\n但它也是一个警告。90%以上的莫斯科骡子是用廉价的工业伏特加和罐装的甜姜汁汽水调制的——而不是辛辣的Cock''n Bull姜汁啤酒。铜杯也经常被简化成廉价的铜色不锈钢杯。一杯真正好的莫斯科骡子需要好的伏特加、辛辣的姜汁啤酒、鲜榨的青柠汁和一个真正的铜杯。\n\n近年来姜汁啤酒经历了复兴——手工姜汁啤酒品牌大量涌现，让莫斯科骡子的品质有了质的飞跃。铜杯、辛辣姜汁和伏特加——这仍然是调酒界最简单的三人组。","title":"延伸：伏特加的美国之梦、铜杯的不可妥协和姜汁啤酒的复兴"},"origin":{"body":"莫斯科骡子的诞生故事充满了好莱坞的随意。1941年的洛杉矶，三个男人在一家酒吧里碰面：John Martin——Smirnoff伏特加的总裁（手里有一堆卖不出去的伏特加，美国人当时几乎不喝伏特加）；Jack Morgan——Cock''n Bull姜汁啤酒的老板（手里有一堆卖不出去的姜汁啤酒）；和一位不太记得名字的调酒师。\n\n他们发现伏特加+姜汁啤酒+青柠汁的组合意外地好喝——伏特加的中性不干扰姜汁啤酒的辛辣，青柠汁的酸平衡了姜的辣和伏特加的醇。莫斯科骡子就此诞生。\n\n为了让这款酒更酷炫，他们把它装在铜杯中——铜杯最初是俄罗斯的象征（伏特加来自俄罗斯）。铜杯冰镇后外壁凝结水珠，拿在手里有一种独特的冷感。John Martin走遍全美酒吧，为每家酒吧免费赠送铜杯和拍立得相机——这是一个营销史上最成功的游击战术。","title":"诞生：1941年的洛杉矶，三个人的一拍脑袋营销奇迹"},"funFact":{"body":"John Martin的营销天才在于：他知道人们不是通过理性选择饮品——而是通过看到别人在喝什么。每家合作的酒吧得到一个免费铜杯和一个拍立得相机。调酒师为顾客调莫斯科骡子，用拍立得拍下顾客举着铜杯的照片——一张留给顾客，一张留在酒吧。\n\n这个营销手法让莫斯科骡子在美国爆发式普及。它也让Smirnoff伏特加从一个\"卖不出去的俄罗斯酒\"变成了美国最畅销的伏特加品牌之一——到1940年代末，Smirnoff在美国的年销量增长了数十倍。\n\n铜杯不仅仅是为了营销——它改变饮用体验。铜壁比玻璃更快降温——金属的冷感透过杯壁传到手指。铜和姜汁啤酒的辛辣气泡形成对比——冰冷金属+辛辣姜汁——让每一口都清爽到骨子里。铜杯不能放进洗碗机——必须手洗——这是莫斯科骡子不可妥协的仪式。","title":"趣味事实：营销史上的经典案例、铜杯的科学和Smirnoff的崛起"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Mint Julep','薄荷朱丽普（直调）','当代经典',ARRAY['60毫升 波旁威士忌','4根 新鲜薄荷枝','1茶匙 糖粉','2茶匙 水'],'{"legacy":{"body":"薄荷茱莉普是肯塔基德比的一部分——但它也超越了肯塔基。在整个美国南方——从弗吉尼亚州的马场到路易斯安那州的钓鱼码头——薄荷茱莉普是夏日午后的\"非官方饮品\"。它不需要调酒师的专业技巧——它只需要：一把薄荷叶、一点糖、碎冰和威士忌。任何人——在任何有薄荷和威士忌的南方厨房里——都可以调一杯茱莉普。\n\n在手工艺鸡尾酒运动中，薄荷茱莉普被重新带到了高级酒吧。调酒师们开始选择单桶波本威士忌（single barrel bourbon）、使用不同种类的薄荷（留兰香、胡椒薄荷、巧克力薄荷）和不同种类的糖（德梅拉拉红糖、枫糖浆、蜂蜜）来创造不同风格的茱莉普。有些加入一点苦精（橙味苦精或芳香苦精），有些使用陈年朗姆取代威士忌——但核心不可妥协的规则依然不变：薄荷必须是新鲜的，碎冰必须堆满杯子。\n\n薄荷茱莉普可能是美国最古老的饮品传统之一。它不会消失——肯塔基的五月需要它，南方的夏日需要它，任何一个在烈日下需要一杯冰凉的、薄荷味的、威士忌的人——都需要它。","title":"延伸：肯塔基最古老的饮品传统——所有南方人的共同记忆"},"origin":{"body":"薄荷茱莉普（Mint Julep）的历史扎根于美国南方——比美利坚合众国的建国还要古老。它的原始版本可以追溯到18世纪的弗吉尼亚州和肯塔基州——当地人在漫长炎热的夏日早晨，将粗制的威士忌（或更早的白兰地版本）、新鲜薄荷叶和糖加水混合——作为一种温和的早晨提神饮品和防暑饮品。\n\n\"Julep\"（茱莉普）这个词源于阿拉伯语的\"julab\"（玫瑰水）——经过波斯语和法语传入英语世界——最初指任何用糖和水浸泡花瓣或药草制成的甜味饮品（和\"syrup\"糖浆是同源词）。在美国殖民时期，阳光暴晒的种植园工人们将薄荷加入甜水中，再加入烈酒——这种饮品在提供水分和糖分的同时给了一点令人愉悦的酒精刺激。\n\n到了19世纪，薄荷茱莉普已经成为了肯塔基州的社会支柱。肯塔基的议员们在议会辩论之前互相请喝薄荷茱莉普，在法院的走廊上、在教堂的社交聚会中——薄荷茱莉普无处不在。它不是\"一杯鸡尾酒\"——它是肯塔基州日常生活的一部分。\n\n1938年，肯塔基德比赛马场（Kentucky Derby）——美国最大的年度赛马活动——正式将薄荷茱莉普指定为官方饮品。每年5月的第一个周六，超过12万杯薄荷茱莉普在Churchill Downs赛马场的看台上被消费——其中很多被装进纪念性的银杯或玻璃杯中，配有当年肯塔基德比的专属图案。","title":"诞生：18世纪的美国南方种植园"},"funFact":{"body":"薄荷茱莉普传统上盛在银杯或铜杯中——这不是为了好看（虽然确实好看）。金属杯壁的热传导率远高于玻璃——当你在银杯里装满碎冰加入威士忌后，杯子的外壁会在几秒钟内结冰——在肯塔基五月的热浪中，一手握着外壁结冰的银杯是一种感官体验：手指上的冰冷、掌心的金属质感、嘴唇接触到冰冷的杯沿——这是三重感官的降温。\n\n正统的薄荷茱莉普使用大量的碎冰——满满一整杯——碎冰融化很快，但同时让饮料每一口都保持接近零度的温度。第一口是冰凉的威士忌加薄荷的芳香，最后一口是冰的融水冲淡了的威士忌糖水——许多茱莉普爱好者认为最后一口是最好的：冰水将威士忌稀释到了一个可以\"畅饮\"的浓度。\n\n薄荷不能是被捣碎的——这是一个不可妥协的规则。在杯底捣碎薄荷叶会释放叶绿素——叶绿素是苦的——让整杯茱莉普带上一种草腥的苦涩。正确的做法是——轻轻拍打薄荷叶在掌心上释放精油，然后放入杯中——或者用捣棒非常轻地按压一次——刚好让叶子释放薄荷油而不碎裂。如果你捣碎了叶子——你已经犯规了。","title":"趣味事实：银杯的科学、冰的统治和薄荷的不可妥协"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Pina Colada','椰林飘香（直调）','当代经典',ARRAY['50毫升 白朗姆酒','30毫升 椰奶','50毫升 新鲜菠萝汁'],'{"legacy":{"body":"在手工鸡尾酒复兴运动中——椰林飘香一度是被遗忘的。调酒师们对它的态度是矛盾的：它太\"甜\"、太\"度假\"、太\"商业化\"。瓶装的椰浆糖浆和罐装菠萝汁让它在许多鸡尾酒吧中变成了一杯糖水——而不是一杯正经的朗姆鸡尾酒。\n\n但近年\"被遗忘的鸡尾酒复兴\"运动——由纽约的Cienfuegos酒吧和其他加勒比风格酒吧引领——重新发掘了椰林飘香的潜力。这些新一代的提基文化复兴者坚持在酒吧中使用新鲜压榨的菠萝汁（用离心机处理以去除粗糙的果肉）、自制的椰子奶油（用全脂椰奶加糖加热搅拌制成——不必是工业罐装产品）和高质量的陈年朗姆酒（如Appleton Estate 12年或Diplomatico Reserva）。\n\n一杯真正好的椰林飘香——用新鲜菠萝汁、自制的椰子奶油和一杯好的陈年朗姆——是世界上最清爽的饮品之一。它不是一杯\"海滩糖水\"——它是加勒比海朗姆酒的复杂风味在椰子和菠萝的陪伴下的热带变奏。最好的椰林飘香用碎冰而不是冰块——碎冰让饮料保持低温的同时更缓慢地融化——让整杯酒的浓度保持更久。\n\n椰林飘香是波多黎各送给世界的最好礼物之一。一杯好的椰林飘香——在波多黎各圣胡安的海边酒吧里——吹着加勒比海风——就是对这座岛屿最好的致敬。","title":"延伸：被遗忘的鸡尾酒复兴运动与一杯真正好的椰林飘香"},"origin":{"body":"椰林飘香（Pina Colada）的故事是一个岛屿的故事——波多黎各。1954年，圣胡安的Caribe Hilton酒店的调酒师Ramon \"Monchito\" Marrero被赋予了一项任务：创造一款能代表波多黎各——这个加勒比海岛屿的所有阳光、椰子和朗姆酒——的标志性饮品。Marrero花了三个月的时间试验不同的比例。他的最终配方完美平衡了三种波多黎各的象征物：白朗姆酒（波多黎各是加勒比海最大的朗姆酒生产地之一，Bacardi的总部就在圣胡安）、椰浆（岛上无处不在的椰子——新鲜椰子的乳白色浆汁）和菠萝汁（岛上的热带水果代表着阳光和甜蜜）。他将三者加冰用搅拌机打成冰冻雪泥状——椰林飘香诞生了。\n\n另一个版本来自同一城市的Barrachina餐厅。这家餐厅声称他们的调酒师Ramon Portas Mingot在1963年独立发明了椰林飘香。Barrachina的版本与Caribe Hilton的版本几乎完全相同——但Mingot声称他是第一个将配方写下来并用搅拌机处理的人。\n\n1978年，波多黎各政府正式宣布椰林飘香为\"波多黎各的官方饮品\"——整个岛屿在庆祝一杯朗姆酒、椰子和菠萝的胜利。无论它最早诞生在Caribe Hilton还是Barrachina——这是波多黎各送给世界的最著名的液体礼物。\n\n椰林飘香的名字来自西班牙语：\"Pina\"意为\"菠萝\"（英文pineapple的西班牙语词根）——\"Colada\"意为\"过滤/滤过的\"——\"Pina Colada\"可直译为\"滤过的菠萝\"。名字不好听但好喝——这是波多黎各的幽默。","title":"诞生：1950年代的波多黎各——一座岛屿的官方饮品"},"funFact":{"body":"椰林飘香的存在要感谢一罐工业产品——Coco Lopez椰子奶油。没有它，椰林飘香不可能被商业化——因为没有一个酒吧能在每天几十杯的节奏下用新鲜椰子来压榨奶油：一个椰子的汁液不到100毫升，而一杯椰林飘香需要30毫升的椰浆。一家中等繁忙的酒吧每天可能要消耗数十个椰子的浆汁——这是不可持续的。\n\nCoco Lopez的发明者是波多黎各大学的农学教授Ramon Lopez Irizarry。他在1940年代研发了一种将椰子浆汁与糖混合的工艺，使得混合物在罐子中可以稳定保存数月而不变质。这款产品在1954年——正是椰林飘香被发明的那一年——进入了商业化生产。两者之间的关系不是巧合：Marrero或Mingot之所以能够使用椰浆作为主要配料——正是因为Lopez的Coco Lopez让椰子奶油变得唾手可得。\n\n椰林飘香是提基文化（Tiki Culture）最重要的鸡尾酒之一——尽管它具有明显的加勒比海特色而不是波利尼西亚特色。提基文化是20世纪中叶美国的调酒现象——以热带装饰、异国情调的音乐和甜美的朗姆鸡尾酒为特征。椰林飘香和Mai-Tai（波利尼西亚风格的朗姆鸡尾酒）是整个提基文化中朗姆酒鸡尾酒的两位女王。\n\n环保问题是椰林飘香的一个复杂的阴影。椰浆的工业化生产依赖于大量种植的椰子——加勒比海岛屿上的椰子种植园往往是单一作物农业，影响了当地的生态多样性。新鲜菠萝汁的生产也面临类似的工业化农业问题。但对于今天的波多黎各来说，椰林飘香仍然是旅游业的支柱饮品——每年无数游客来到波多黎各\"为了喝一杯正宗的Pina Colada\"。它的经济影响远超环保争议。","title":"趣味事实：Coco Lopez的发明和提基文化的兴起"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Pisco Sour','皮斯科酸（摇和）','当代经典',ARRAY['60毫升 皮斯科酒','30毫升 新鲜柠檬汁','20毫升 单糖浆','蛋清'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。皮斯科酸诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在皮斯科酸的基础上创造新的变奏：用不同的基酒代替60毫升 皮斯科酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n皮斯科酸的持久遗产在于：它证明了一个简单的配方——60毫升 皮斯科酒、30毫升 新鲜柠檬汁、20毫升 单糖浆、蛋清——可以被永恒地重新演绎而不失去其经典地位。一杯好的皮斯科酸——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对皮斯科酸有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"皮斯科酸的传承——经典配方的现代演绎"},"origin":{"body":"皮斯科酸是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n皮斯科酸的核心配料包括60毫升 皮斯科酒、30毫升 新鲜柠檬汁、20毫升 单糖浆、蛋清。每一种配料都有其特定的角色：60毫升 皮斯科酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕60毫升 皮斯科酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于皮斯科酸的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，皮斯科酸通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解皮斯科酸的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于皮斯科酸——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"皮斯科酸的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n皮斯科酸的主要烈酒是60毫升 皮斯科酒。选择优质品牌的60毫升 皮斯科酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，60毫升 皮斯科酒的个性无法被其他成分完全遮盖或稀释。一瓶好的60毫升 皮斯科酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的皮斯科酸通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制皮斯科酸——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于皮斯科酸的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Sea Breeze','海风（直调）','当代经典',ARRAY['40毫升 伏特加','120毫升 蔓越莓汁','30毫升 葡萄柚汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。海风诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在海风的基础上创造新的变奏：用不同的基酒代替40毫升 伏特加来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n海风的持久遗产在于：它证明了一个简单的配方——40毫升 伏特加、120毫升 蔓越莓汁、30毫升 葡萄柚汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的海风——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对海风有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"海风的传承——经典配方的现代演绎"},"origin":{"body":"海风是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n海风的核心配料包括40毫升 伏特加、120毫升 蔓越莓汁、30毫升 葡萄柚汁。每一种配料都有其特定的角色：40毫升 伏特加是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕40毫升 伏特加展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于海风的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，海风通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解海风的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于海风——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"海风的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n海风的主要烈酒是40毫升 伏特加。选择优质品牌的40毫升 伏特加对最终的结果至关重要——因为在这款鸡尾酒的配方中，40毫升 伏特加的个性无法被其他成分完全遮盖或稀释。一瓶好的40毫升 伏特加会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的海风通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制海风——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于海风的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Sex on the Beach','性感沙滩（直调）','当代经典',ARRAY['40毫升 伏特加','20毫升 桃子利口酒','40毫升 新鲜橙汁','40毫升 蔓越莓汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。性感沙滩诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在性感沙滩的基础上创造新的变奏：用不同的基酒代替40毫升 伏特加来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n性感沙滩的持久遗产在于：它证明了一个简单的配方——40毫升 伏特加、20毫升 桃子利口酒、40毫升 新鲜橙汁、40毫升 蔓越莓汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的性感沙滩——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对性感沙滩有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"性感沙滩的传承——经典配方的现代演绎"},"origin":{"body":"性感沙滩是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n性感沙滩的核心配料包括40毫升 伏特加、20毫升 桃子利口酒、40毫升 新鲜橙汁、40毫升 蔓越莓汁。每一种配料都有其特定的角色：40毫升 伏特加是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕40毫升 伏特加展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于性感沙滩的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，性感沙滩通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解性感沙滩的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于性感沙滩——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"性感沙滩的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n性感沙滩的主要烈酒是40毫升 伏特加。选择优质品牌的40毫升 伏特加对最终的结果至关重要——因为在这款鸡尾酒的配方中，40毫升 伏特加的个性无法被其他成分完全遮盖或稀释。一瓶好的40毫升 伏特加会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的性感沙滩通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制性感沙滩——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于性感沙滩的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Singapore Sling','新加坡司令（摇和）','当代经典',ARRAY['30毫升 杜松子酒','15毫升 樱桃利口酒','7.5毫升 君度','7.5毫升 法国廊酒','120毫升 新鲜菠萝汁','15毫升 新鲜青柠汁','10毫升石榴糖浆','2滴 安哥斯图拉苦酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。新加坡司令诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在新加坡司令的基础上创造新的变奏：用不同的基酒代替30毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n新加坡司令的持久遗产在于：它证明了一个简单的配方——30毫升 杜松子酒、15毫升 樱桃利口酒、7.5毫升 君度、7.5毫升 法国廊酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的新加坡司令——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对新加坡司令有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"新加坡司令的传承——经典配方的现代演绎"},"origin":{"body":"新加坡司令是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n新加坡司令的核心配料包括30毫升 杜松子酒、15毫升 樱桃利口酒、7.5毫升 君度、7.5毫升 法国廊酒。每一种配料都有其特定的角色：30毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于新加坡司令的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，新加坡司令通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解新加坡司令的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于新加坡司令——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"新加坡司令的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n新加坡司令的主要烈酒是30毫升 杜松子酒。选择优质品牌的30毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的新加坡司令通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制新加坡司令——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于新加坡司令的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Tequila Sunrise','龙舌兰日出（直调）','当代经典',ARRAY['45毫升龙舌兰酒','90毫升 新鲜橙汁','15毫升 石榴糖浆（沉底）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。龙舌兰日出诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在龙舌兰日出的基础上创造新的变奏：用不同的基酒代替45毫升龙舌兰酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n龙舌兰日出的持久遗产在于：它证明了一个简单的配方——45毫升龙舌兰酒、90毫升 新鲜橙汁、15毫升 石榴糖浆（沉底）——可以被永恒地重新演绎而不失去其经典地位。一杯好的龙舌兰日出——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对龙舌兰日出有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"龙舌兰日出的传承——经典配方的现代演绎"},"origin":{"body":"龙舌兰日出是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n龙舌兰日出的核心配料包括45毫升龙舌兰酒、90毫升 新鲜橙汁、15毫升 石榴糖浆（沉底）。每一种配料都有其特定的角色：45毫升龙舌兰酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升龙舌兰酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于龙舌兰日出的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，龙舌兰日出通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解龙舌兰日出的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于龙舌兰日出——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"龙舌兰日出的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n龙舌兰日出的主要烈酒是45毫升龙舌兰酒。选择优质品牌的45毫升龙舌兰酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升龙舌兰酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升龙舌兰酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的龙舌兰日出通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制龙舌兰日出——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于龙舌兰日出的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Vesper','薇斯朋（摇和）','当代经典',ARRAY['45毫升 杜松子酒','15毫升 伏特加','7.5毫升 利莱利口酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。薇斯朋诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在薇斯朋的基础上创造新的变奏：用不同的基酒代替45毫升 杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n薇斯朋的持久遗产在于：它证明了一个简单的配方——45毫升 杜松子酒、15毫升 伏特加、7.5毫升 利莱利口酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的薇斯朋——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对薇斯朋有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"薇斯朋的传承——经典配方的现代演绎"},"origin":{"body":"薇斯朋是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n薇斯朋的核心配料包括45毫升 杜松子酒、15毫升 伏特加、7.5毫升 利莱利口酒。每一种配料都有其特定的角色：45毫升 杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于薇斯朋的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，薇斯朋通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解薇斯朋的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于薇斯朋——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"薇斯朋的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n薇斯朋的主要烈酒是45毫升 杜松子酒。选择优质品牌的45毫升 杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的薇斯朋通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制薇斯朋——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于薇斯朋的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Trinidad Sour','特立尼达酸（摇和）','新时代',ARRAY['45毫升 安哥斯图拉苦精','30毫升 杏仁糖浆','22.5毫升 新鲜柠檬汁','15毫升 黑麦威士忌'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。特立尼达酸诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在特立尼达酸的基础上创造新的变奏：用不同的基酒代替45毫升 安哥斯图拉苦精来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n特立尼达酸的持久遗产在于：它证明了一个简单的配方——45毫升 安哥斯图拉苦精、30毫升 杏仁糖浆、22.5毫升 新鲜柠檬汁、15毫升 黑麦威士忌——可以被永恒地重新演绎而不失去其经典地位。一杯好的特立尼达酸——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对特立尼达酸有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"特立尼达酸的传承——经典配方的现代演绎"},"origin":{"body":"特立尼达酸是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n特立尼达酸的核心配料包括45毫升 安哥斯图拉苦精、30毫升 杏仁糖浆、22.5毫升 新鲜柠檬汁、15毫升 黑麦威士忌。每一种配料都有其特定的角色：45毫升 安哥斯图拉苦精是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 安哥斯图拉苦精展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于特立尼达酸的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，特立尼达酸通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解特立尼达酸的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于特立尼达酸——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"特立尼达酸的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n特立尼达酸的主要烈酒是45毫升 安哥斯图拉苦精。选择优质品牌的45毫升 安哥斯图拉苦精对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 安哥斯图拉苦精的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 安哥斯图拉苦精会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的特立尼达酸通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制特立尼达酸——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于特立尼达酸的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Barracuda','梭子鱼（摇和）','新时代',ARRAY['45毫升 金朗姆酒','15毫升 加利安奴香草利口酒','60毫升 新鲜菠萝汁','1滴 新鲜青柠汁','普罗赛克起泡酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。梭子鱼诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在梭子鱼的基础上创造新的变奏：用不同的基酒代替45毫升 金朗姆酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n梭子鱼的持久遗产在于：它证明了一个简单的配方——45毫升 金朗姆酒、15毫升 加利安奴香草利口酒、60毫升 新鲜菠萝汁、1滴 新鲜青柠汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的梭子鱼——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对梭子鱼有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"梭子鱼的传承——经典配方的现代演绎"},"origin":{"body":"梭子鱼是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n梭子鱼的核心配料包括45毫升 金朗姆酒、15毫升 加利安奴香草利口酒、60毫升 新鲜菠萝汁、1滴 新鲜青柠汁。每一种配料都有其特定的角色：45毫升 金朗姆酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 金朗姆酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于梭子鱼的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，梭子鱼通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解梭子鱼的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于梭子鱼——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"梭子鱼的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n梭子鱼的主要烈酒是45毫升 金朗姆酒。选择优质品牌的45毫升 金朗姆酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 金朗姆酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 金朗姆酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的梭子鱼通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制梭子鱼——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于梭子鱼的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Bees Knees','’蜜蜂的膝盖（摇和）','新时代',ARRAY['52.5毫升 干杜松子酒','2茶匙 蜂蜜糖浆','22.5毫升 新鲜柠檬汁','22.5毫升 新鲜橙汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。’蜜蜂的膝盖诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在’蜜蜂的膝盖的基础上创造新的变奏：用不同的基酒代替52.5毫升 干杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n’蜜蜂的膝盖的持久遗产在于：它证明了一个简单的配方——52.5毫升 干杜松子酒、2茶匙 蜂蜜糖浆、22.5毫升 新鲜柠檬汁、22.5毫升 新鲜橙汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的’蜜蜂的膝盖——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对’蜜蜂的膝盖有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"’蜜蜂的膝盖的传承——经典配方的现代演绎"},"origin":{"body":"’蜜蜂的膝盖是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n’蜜蜂的膝盖的核心配料包括52.5毫升 干杜松子酒、2茶匙 蜂蜜糖浆、22.5毫升 新鲜柠檬汁、22.5毫升 新鲜橙汁。每一种配料都有其特定的角色：52.5毫升 干杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕52.5毫升 干杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于’蜜蜂的膝盖的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，’蜜蜂的膝盖通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解’蜜蜂的膝盖的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于’蜜蜂的膝盖——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"’蜜蜂的膝盖的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n’蜜蜂的膝盖的主要烈酒是52.5毫升 干杜松子酒。选择优质品牌的52.5毫升 干杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，52.5毫升 干杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的52.5毫升 干杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的’蜜蜂的膝盖通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制’蜜蜂的膝盖——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于’蜜蜂的膝盖的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Bramble','树莓（摇和）','新时代',ARRAY['50毫升 干杜松子酒','25毫升 新鲜柠檬汁','12.5毫升 单糖浆','15毫升 黑加仑利口酒（漂浮）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。树莓诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在树莓的基础上创造新的变奏：用不同的基酒代替50毫升 干杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n树莓的持久遗产在于：它证明了一个简单的配方——50毫升 干杜松子酒、25毫升 新鲜柠檬汁、12.5毫升 单糖浆、15毫升 黑加仑利口酒（漂浮）——可以被永恒地重新演绎而不失去其经典地位。一杯好的树莓——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对树莓有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"树莓的传承——经典配方的现代演绎"},"origin":{"body":"树莓是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n树莓的核心配料包括50毫升 干杜松子酒、25毫升 新鲜柠檬汁、12.5毫升 单糖浆、15毫升 黑加仑利口酒（漂浮）。每一种配料都有其特定的角色：50毫升 干杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕50毫升 干杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于树莓的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，树莓通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解树莓的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于树莓——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"树莓的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n树莓的主要烈酒是50毫升 干杜松子酒。选择优质品牌的50毫升 干杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，50毫升 干杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的50毫升 干杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的树莓通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制树莓——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于树莓的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Canchanchara','坎查查拉（直调）','新时代',ARRAY['60毫升 古巴阿瓜迪安特酒','15毫升 新鲜青柠汁','15 毫升 生蜂蜜','50毫升 水'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。坎查查拉诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在坎查查拉的基础上创造新的变奏：用不同的基酒代替60毫升 古巴阿瓜迪安特酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n坎查查拉的持久遗产在于：它证明了一个简单的配方——60毫升 古巴阿瓜迪安特酒、15毫升 新鲜青柠汁、15 毫升 生蜂蜜、50毫升 水——可以被永恒地重新演绎而不失去其经典地位。一杯好的坎查查拉——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对坎查查拉有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"坎查查拉的传承——经典配方的现代演绎"},"origin":{"body":"坎查查拉是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n坎查查拉的核心配料包括60毫升 古巴阿瓜迪安特酒、15毫升 新鲜青柠汁、15 毫升 生蜂蜜、50毫升 水。每一种配料都有其特定的角色：60毫升 古巴阿瓜迪安特酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕60毫升 古巴阿瓜迪安特酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于坎查查拉的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，坎查查拉通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解坎查查拉的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于坎查查拉——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"坎查查拉的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n坎查查拉的主要烈酒是60毫升 古巴阿瓜迪安特酒。选择优质品牌的60毫升 古巴阿瓜迪安特酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，60毫升 古巴阿瓜迪安特酒的个性无法被其他成分完全遮盖或稀释。一瓶好的60毫升 古巴阿瓜迪安特酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的坎查查拉通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制坎查查拉——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于坎查查拉的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Dark n stormy','‘’月黑风高（直调）','新时代',ARRAY['60毫升 高斯林朗姆酒（漂浮）','100毫升 姜汁啤酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。‘’月黑风高诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在‘’月黑风高的基础上创造新的变奏：用不同的基酒代替60毫升 高斯林朗姆酒（漂浮）来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n‘’月黑风高的持久遗产在于：它证明了一个简单的配方——60毫升 高斯林朗姆酒（漂浮）、100毫升 姜汁啤酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的‘’月黑风高——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对‘’月黑风高有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"‘’月黑风高的传承——经典配方的现代演绎"},"origin":{"body":"‘’月黑风高是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n‘’月黑风高的核心配料包括60毫升 高斯林朗姆酒（漂浮）、100毫升 姜汁啤酒。每一种配料都有其特定的角色：60毫升 高斯林朗姆酒（漂浮）是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕60毫升 高斯林朗姆酒（漂浮）展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于‘’月黑风高的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，‘’月黑风高通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解‘’月黑风高的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于‘’月黑风高——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"‘’月黑风高的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n‘’月黑风高的主要烈酒是60毫升 高斯林朗姆酒（漂浮）。选择优质品牌的60毫升 高斯林朗姆酒（漂浮）对最终的结果至关重要——因为在这款鸡尾酒的配方中，60毫升 高斯林朗姆酒（漂浮）的个性无法被其他成分完全遮盖或稀释。一瓶好的60毫升 高斯林朗姆酒（漂浮）会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的‘’月黑风高通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制‘’月黑风高——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于‘’月黑风高的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Fernandito','菲奈特可乐（直调）','新时代',ARRAY['50毫升 非奈特布兰卡苦酒','可乐'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。菲奈特可乐诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在菲奈特可乐的基础上创造新的变奏：用不同的基酒代替50毫升 非奈特布兰卡苦酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n菲奈特可乐的持久遗产在于：它证明了一个简单的配方——50毫升 非奈特布兰卡苦酒、可乐——可以被永恒地重新演绎而不失去其经典地位。一杯好的菲奈特可乐——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对菲奈特可乐有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"菲奈特可乐的传承——经典配方的现代演绎"},"origin":{"body":"菲奈特可乐是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n菲奈特可乐的核心配料包括50毫升 非奈特布兰卡苦酒、可乐。每一种配料都有其特定的角色：50毫升 非奈特布兰卡苦酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕50毫升 非奈特布兰卡苦酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于菲奈特可乐的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，菲奈特可乐通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解菲奈特可乐的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于菲奈特可乐——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"菲奈特可乐的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n菲奈特可乐的主要烈酒是50毫升 非奈特布兰卡苦酒。选择优质品牌的50毫升 非奈特布兰卡苦酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，50毫升 非奈特布兰卡苦酒的个性无法被其他成分完全遮盖或稀释。一瓶好的50毫升 非奈特布兰卡苦酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的菲奈特可乐通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制菲奈特可乐——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于菲奈特可乐的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('French Martini','法式马天尼（摇和）','新时代',ARRAY['45毫升 伏特加','15毫升 覆盆子利口酒','15毫升 新鲜菠萝汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。法式马天尼诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在法式马天尼的基础上创造新的变奏：用不同的基酒代替45毫升 伏特加来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n法式马天尼的持久遗产在于：它证明了一个简单的配方——45毫升 伏特加、15毫升 覆盆子利口酒、15毫升 新鲜菠萝汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的法式马天尼——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对法式马天尼有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"法式马天尼的传承——经典配方的现代演绎"},"origin":{"body":"法式马天尼是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n法式马天尼的核心配料包括45毫升 伏特加、15毫升 覆盆子利口酒、15毫升 新鲜菠萝汁。每一种配料都有其特定的角色：45毫升 伏特加是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 伏特加展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于法式马天尼的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，法式马天尼通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解法式马天尼的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于法式马天尼——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"法式马天尼的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n法式马天尼的主要烈酒是45毫升 伏特加。选择优质品牌的45毫升 伏特加对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 伏特加的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 伏特加会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的法式马天尼通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制法式马天尼——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于法式马天尼的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Illegal','非法者（摇和）','新时代',ARRAY['30毫升 梅斯卡尔酒','15毫升 牙买加高强度利口酒','15毫升 法勒纳姆利口酒','1茶匙 黑樱桃利口酒','22.5毫升 新鲜青柠汁','15毫升 单糖浆','蛋清（可选）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。非法者诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在非法者的基础上创造新的变奏：用不同的基酒代替30毫升 梅斯卡尔酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n非法者的持久遗产在于：它证明了一个简单的配方——30毫升 梅斯卡尔酒、15毫升 牙买加高强度利口酒、15毫升 法勒纳姆利口酒、1茶匙 黑樱桃利口酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的非法者——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对非法者有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"非法者的传承——经典配方的现代演绎"},"origin":{"body":"非法者是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n非法者的核心配料包括30毫升 梅斯卡尔酒、15毫升 牙买加高强度利口酒、15毫升 法勒纳姆利口酒、1茶匙 黑樱桃利口酒。每一种配料都有其特定的角色：30毫升 梅斯卡尔酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 梅斯卡尔酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于非法者的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，非法者通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解非法者的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于非法者——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"非法者的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n非法者的主要烈酒是30毫升 梅斯卡尔酒。选择优质品牌的30毫升 梅斯卡尔酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 梅斯卡尔酒的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 梅斯卡尔酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的非法者通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制非法者——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于非法者的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Lemon drop Martini','柠檬滴马提尼（摇和）','新时代',ARRAY['30毫升 柑橘伏特加','20毫升 橙皮利口酒','15毫升 新鲜柠檬汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。柠檬滴马提尼诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在柠檬滴马提尼的基础上创造新的变奏：用不同的基酒代替30毫升 柑橘伏特加来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n柠檬滴马提尼的持久遗产在于：它证明了一个简单的配方——30毫升 柑橘伏特加、20毫升 橙皮利口酒、15毫升 新鲜柠檬汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的柠檬滴马提尼——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对柠檬滴马提尼有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"柠檬滴马提尼的传承——经典配方的现代演绎"},"origin":{"body":"柠檬滴马提尼是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n柠檬滴马提尼的核心配料包括30毫升 柑橘伏特加、20毫升 橙皮利口酒、15毫升 新鲜柠檬汁。每一种配料都有其特定的角色：30毫升 柑橘伏特加是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 柑橘伏特加展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于柠檬滴马提尼的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，柠檬滴马提尼通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解柠檬滴马提尼的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于柠檬滴马提尼——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"柠檬滴马提尼的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n柠檬滴马提尼的主要烈酒是30毫升 柑橘伏特加。选择优质品牌的30毫升 柑橘伏特加对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 柑橘伏特加的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 柑橘伏特加会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的柠檬滴马提尼通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制柠檬滴马提尼——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于柠檬滴马提尼的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('New York Sour','纽约酸（摇和）','新时代',ARRAY['60毫升 黑麦威士忌或波旁威士忌','22.5毫升 单糖浆','30毫升 新鲜柠檬汁','蛋清','15毫升 红葡萄酒（漂浮）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。纽约酸诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在纽约酸的基础上创造新的变奏：用不同的基酒代替60毫升 黑麦威士忌或波旁威士忌来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n纽约酸的持久遗产在于：它证明了一个简单的配方——60毫升 黑麦威士忌或波旁威士忌、22.5毫升 单糖浆、30毫升 新鲜柠檬汁、蛋清——可以被永恒地重新演绎而不失去其经典地位。一杯好的纽约酸——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对纽约酸有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"纽约酸的传承——经典配方的现代演绎"},"origin":{"body":"纽约酸是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n纽约酸的核心配料包括60毫升 黑麦威士忌或波旁威士忌、22.5毫升 单糖浆、30毫升 新鲜柠檬汁、蛋清。每一种配料都有其特定的角色：60毫升 黑麦威士忌或波旁威士忌是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕60毫升 黑麦威士忌或波旁威士忌展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于纽约酸的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，纽约酸通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解纽约酸的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于纽约酸——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"纽约酸的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n纽约酸的主要烈酒是60毫升 黑麦威士忌或波旁威士忌。选择优质品牌的60毫升 黑麦威士忌或波旁威士忌对最终的结果至关重要——因为在这款鸡尾酒的配方中，60毫升 黑麦威士忌或波旁威士忌的个性无法被其他成分完全遮盖或稀释。一瓶好的60毫升 黑麦威士忌或波旁威士忌会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的纽约酸通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制纽约酸——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于纽约酸的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Old Cuban','老古巴人（摇和）','新时代',ARRAY['45毫升 陈年朗姆酒','22.5毫升 新鲜青柠汁','30毫升 单糖浆','2滴 安哥斯图拉苦精','60毫升 冰镇香槟或普罗赛克起泡酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。老古巴人诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在老古巴人的基础上创造新的变奏：用不同的基酒代替45毫升 陈年朗姆酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n老古巴人的持久遗产在于：它证明了一个简单的配方——45毫升 陈年朗姆酒、22.5毫升 新鲜青柠汁、30毫升 单糖浆、2滴 安哥斯图拉苦精——可以被永恒地重新演绎而不失去其经典地位。一杯好的老古巴人——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对老古巴人有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"老古巴人的传承——经典配方的现代演绎"},"origin":{"body":"老古巴人是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n老古巴人的核心配料包括45毫升 陈年朗姆酒、22.5毫升 新鲜青柠汁、30毫升 单糖浆、2滴 安哥斯图拉苦精。每一种配料都有其特定的角色：45毫升 陈年朗姆酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 陈年朗姆酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于老古巴人的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，老古巴人通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解老古巴人的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于老古巴人——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"老古巴人的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n老古巴人的主要烈酒是45毫升 陈年朗姆酒。选择优质品牌的45毫升 陈年朗姆酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 陈年朗姆酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 陈年朗姆酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的老古巴人通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制老古巴人——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于老古巴人的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Paloma','帕洛玛（直调）','新时代',ARRAY['50毫升 100%龙舌兰酒','5毫升 新鲜青柠汁','一撮 盐','100毫升 粉红葡萄柚苏打水'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。帕洛玛诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在帕洛玛的基础上创造新的变奏：用不同的基酒代替50毫升 100%龙舌兰酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n帕洛玛的持久遗产在于：它证明了一个简单的配方——50毫升 100%龙舌兰酒、5毫升 新鲜青柠汁、一撮 盐、100毫升 粉红葡萄柚苏打水——可以被永恒地重新演绎而不失去其经典地位。一杯好的帕洛玛——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对帕洛玛有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"帕洛玛的传承——经典配方的现代演绎"},"origin":{"body":"帕洛玛是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n帕洛玛的核心配料包括50毫升 100%龙舌兰酒、5毫升 新鲜青柠汁、一撮 盐、100毫升 粉红葡萄柚苏打水。每一种配料都有其特定的角色：50毫升 100%龙舌兰酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕50毫升 100%龙舌兰酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于帕洛玛的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，帕洛玛通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解帕洛玛的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于帕洛玛——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"帕洛玛的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n帕洛玛的主要烈酒是50毫升 100%龙舌兰酒。选择优质品牌的50毫升 100%龙舌兰酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，50毫升 100%龙舌兰酒的个性无法被其他成分完全遮盖或稀释。一瓶好的50毫升 100%龙舌兰酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的帕洛玛通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制帕洛玛——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于帕洛玛的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Paper Plane','纸飞机（摇和）','新时代',ARRAY['30毫升 波本威士忌','30毫升 诺尼诺苦酒','30毫升 阿佩罗苦酒','30毫升 新鲜柠檬汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。纸飞机诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在纸飞机的基础上创造新的变奏：用不同的基酒代替30毫升 波本威士忌来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n纸飞机的持久遗产在于：它证明了一个简单的配方——30毫升 波本威士忌、30毫升 诺尼诺苦酒、30毫升 阿佩罗苦酒、30毫升 新鲜柠檬汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的纸飞机——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对纸飞机有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"纸飞机的传承——经典配方的现代演绎"},"origin":{"body":"纸飞机是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n纸飞机的核心配料包括30毫升 波本威士忌、30毫升 诺尼诺苦酒、30毫升 阿佩罗苦酒、30毫升 新鲜柠檬汁。每一种配料都有其特定的角色：30毫升 波本威士忌是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 波本威士忌展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于纸飞机的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，纸飞机通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解纸飞机的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于纸飞机——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"纸飞机的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n纸飞机的主要烈酒是30毫升 波本威士忌。选择优质品牌的30毫升 波本威士忌对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 波本威士忌的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 波本威士忌会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的纸飞机通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制纸飞机——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于纸飞机的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Penicillin','盘尼西林（摇和）','新时代',ARRAY['60毫升苏格兰调和型威士忌','22.5毫升 新鲜柠檬汁','22.5 毫升 蜂蜜糖浆','2、3块 四分之一大小新鲜姜片','7.5毫升 乐加维林16年威士忌（漂浮）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。盘尼西林诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在盘尼西林的基础上创造新的变奏：用不同的基酒代替60毫升苏格兰调和型威士忌来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n盘尼西林的持久遗产在于：它证明了一个简单的配方——60毫升苏格兰调和型威士忌、22.5毫升 新鲜柠檬汁、22.5 毫升 蜂蜜糖浆、2、3块 四分之一大小新鲜姜片——可以被永恒地重新演绎而不失去其经典地位。一杯好的盘尼西林——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对盘尼西林有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"盘尼西林的传承——经典配方的现代演绎"},"origin":{"body":"盘尼西林是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n盘尼西林的核心配料包括60毫升苏格兰调和型威士忌、22.5毫升 新鲜柠檬汁、22.5 毫升 蜂蜜糖浆、2、3块 四分之一大小新鲜姜片。每一种配料都有其特定的角色：60毫升苏格兰调和型威士忌是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕60毫升苏格兰调和型威士忌展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于盘尼西林的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，盘尼西林通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解盘尼西林的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于盘尼西林——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"盘尼西林的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n盘尼西林的主要烈酒是60毫升苏格兰调和型威士忌。选择优质品牌的60毫升苏格兰调和型威士忌对最终的结果至关重要——因为在这款鸡尾酒的配方中，60毫升苏格兰调和型威士忌的个性无法被其他成分完全遮盖或稀释。一瓶好的60毫升苏格兰调和型威士忌会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的盘尼西林通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制盘尼西林——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于盘尼西林的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Southside','南方（摇和）','新时代',ARRAY['60毫升 伦敦干杜松子酒','30毫升 新鲜柠檬汁','15毫升 单糖浆','5 6片 薄荷叶','蛋清（可选）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。南方诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在南方的基础上创造新的变奏：用不同的基酒代替60毫升 伦敦干杜松子酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n南方的持久遗产在于：它证明了一个简单的配方——60毫升 伦敦干杜松子酒、30毫升 新鲜柠檬汁、15毫升 单糖浆、5 6片 薄荷叶——可以被永恒地重新演绎而不失去其经典地位。一杯好的南方——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对南方有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"南方的传承——经典配方的现代演绎"},"origin":{"body":"南方是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n南方的核心配料包括60毫升 伦敦干杜松子酒、30毫升 新鲜柠檬汁、15毫升 单糖浆、5 6片 薄荷叶。每一种配料都有其特定的角色：60毫升 伦敦干杜松子酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕60毫升 伦敦干杜松子酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于南方的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，南方通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解南方的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于南方——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"南方的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n南方的主要烈酒是60毫升 伦敦干杜松子酒。选择优质品牌的60毫升 伦敦干杜松子酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，60毫升 伦敦干杜松子酒的个性无法被其他成分完全遮盖或稀释。一瓶好的60毫升 伦敦干杜松子酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的南方通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制南方——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于南方的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Spicy Fifty','辣度五十（摇和）','新时代',ARRAY['50毫升 香草伏特加','15毫升 接骨木花利口酒','15毫升 新鲜青柠汁','10毫升 莫林蜂蜜糖浆','2片 红辣椒薄片'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。辣度五十诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在辣度五十的基础上创造新的变奏：用不同的基酒代替50毫升 香草伏特加来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n辣度五十的持久遗产在于：它证明了一个简单的配方——50毫升 香草伏特加、15毫升 接骨木花利口酒、15毫升 新鲜青柠汁、10毫升 莫林蜂蜜糖浆——可以被永恒地重新演绎而不失去其经典地位。一杯好的辣度五十——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对辣度五十有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"辣度五十的传承——经典配方的现代演绎"},"origin":{"body":"辣度五十是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n辣度五十的核心配料包括50毫升 香草伏特加、15毫升 接骨木花利口酒、15毫升 新鲜青柠汁、10毫升 莫林蜂蜜糖浆。每一种配料都有其特定的角色：50毫升 香草伏特加是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕50毫升 香草伏特加展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于辣度五十的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，辣度五十通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解辣度五十的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于辣度五十——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"辣度五十的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n辣度五十的主要烈酒是50毫升 香草伏特加。选择优质品牌的50毫升 香草伏特加对最终的结果至关重要——因为在这款鸡尾酒的配方中，50毫升 香草伏特加的个性无法被其他成分完全遮盖或稀释。一瓶好的50毫升 香草伏特加会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的辣度五十通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制辣度五十——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于辣度五十的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Spritz','阿佩罗橙光（直调）','新时代',ARRAY['60毫升 阿佩罗','90毫升 普罗赛克起泡酒','苏打水'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。阿佩罗橙光诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在阿佩罗橙光的基础上创造新的变奏：用不同的基酒代替60毫升 阿佩罗来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n阿佩罗橙光的持久遗产在于：它证明了一个简单的配方——60毫升 阿佩罗、90毫升 普罗赛克起泡酒、苏打水——可以被永恒地重新演绎而不失去其经典地位。一杯好的阿佩罗橙光——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对阿佩罗橙光有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"阿佩罗橙光的传承——经典配方的现代演绎"},"origin":{"body":"阿佩罗橙光是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n阿佩罗橙光的核心配料包括60毫升 阿佩罗、90毫升 普罗赛克起泡酒、苏打水。每一种配料都有其特定的角色：60毫升 阿佩罗是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕60毫升 阿佩罗展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于阿佩罗橙光的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，阿佩罗橙光通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解阿佩罗橙光的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于阿佩罗橙光——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"阿佩罗橙光的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n阿佩罗橙光的主要烈酒是60毫升 阿佩罗。选择优质品牌的60毫升 阿佩罗对最终的结果至关重要——因为在这款鸡尾酒的配方中，60毫升 阿佩罗的个性无法被其他成分完全遮盖或稀释。一瓶好的60毫升 阿佩罗会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的阿佩罗橙光通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制阿佩罗橙光——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于阿佩罗橙光的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Suffering Bastard','受苦混蛋（摇和）','新时代',ARRAY['30毫升 干邑白兰地或白兰地','30毫升 杜松子酒','15毫升 新鲜青柠汁','2滴 安哥斯图拉苦精','姜汁啤酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。受苦混蛋诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在受苦混蛋的基础上创造新的变奏：用不同的基酒代替30毫升 干邑白兰地或白兰地来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n受苦混蛋的持久遗产在于：它证明了一个简单的配方——30毫升 干邑白兰地或白兰地、30毫升 杜松子酒、15毫升 新鲜青柠汁、2滴 安哥斯图拉苦精——可以被永恒地重新演绎而不失去其经典地位。一杯好的受苦混蛋——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对受苦混蛋有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"受苦混蛋的传承——经典配方的现代演绎"},"origin":{"body":"受苦混蛋是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n受苦混蛋的核心配料包括30毫升 干邑白兰地或白兰地、30毫升 杜松子酒、15毫升 新鲜青柠汁、2滴 安哥斯图拉苦精。每一种配料都有其特定的角色：30毫升 干邑白兰地或白兰地是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 干邑白兰地或白兰地展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于受苦混蛋的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，受苦混蛋通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解受苦混蛋的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于受苦混蛋——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"受苦混蛋的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n受苦混蛋的主要烈酒是30毫升 干邑白兰地或白兰地。选择优质品牌的30毫升 干邑白兰地或白兰地对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 干邑白兰地或白兰地的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 干邑白兰地或白兰地会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的受苦混蛋通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制受苦混蛋——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于受苦混蛋的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Tipperary','蒂珀雷里（搅拌）','新时代',ARRAY['50毫升 爱尔兰威士忌','25毫升 甜味美思','15毫升 绿查特利口酒','2滴 安哥斯图拉苦精'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。蒂珀雷里诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在蒂珀雷里的基础上创造新的变奏：用不同的基酒代替50毫升 爱尔兰威士忌来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n蒂珀雷里的持久遗产在于：它证明了一个简单的配方——50毫升 爱尔兰威士忌、25毫升 甜味美思、15毫升 绿查特利口酒、2滴 安哥斯图拉苦精——可以被永恒地重新演绎而不失去其经典地位。一杯好的蒂珀雷里——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对蒂珀雷里有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"蒂珀雷里的传承——经典配方的现代演绎"},"origin":{"body":"蒂珀雷里是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n蒂珀雷里的核心配料包括50毫升 爱尔兰威士忌、25毫升 甜味美思、15毫升 绿查特利口酒、2滴 安哥斯图拉苦精。每一种配料都有其特定的角色：50毫升 爱尔兰威士忌是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕50毫升 爱尔兰威士忌展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于蒂珀雷里的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，蒂珀雷里通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解蒂珀雷里的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于蒂珀雷里——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"蒂珀雷里的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n蒂珀雷里的主要烈酒是50毫升 爱尔兰威士忌。选择优质品牌的50毫升 爱尔兰威士忌对最终的结果至关重要——因为在这款鸡尾酒的配方中，50毫升 爱尔兰威士忌的个性无法被其他成分完全遮盖或稀释。一瓶好的50毫升 爱尔兰威士忌会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的蒂珀雷里通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制蒂珀雷里——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于蒂珀雷里的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Daiquiri','黛绮丽（摇和）','难忘经典',ARRAY['60毫升古巴白朗姆酒','20毫升 新鲜青柠汁','2勺 超细糖'],'{"legacy":{"body":"大吉利是鸡尾酒中最简洁的公式之一——烈酒+柑橘+甜。这个三角结构启发了无数变奏。草莓大吉利（加新鲜草莓和果汁）、芒果大吉利、百香果大吉利——都从这个经典公式演变而来。\n\n但冷冻大吉利（冰沙机打的糖水版本）在20世纪后期损害了大吉利的声誉。许多人认知中的大吉利是一杯甜腻的冰冻糖水——这杯\"海滩饮料\"已经和詹宁斯·考克斯在1898年调的那杯锐利清爽的朗姆酒酸完全没有关系了。\n\n今日的手工鸡尾酒吧正在恢复大吉利的尊严。一杯真正好的大吉利，需要鲜榨青柠汁和一杯体面的白朗姆——不该需要超过三样东西。大吉利的纯粹在于它无可隐藏——朗姆酒的品质、青柠的新鲜度、糖的精确量——在这个最简洁的三角结构中全部暴露无遗。","title":"延伸：朗姆酒最纯粹的表达，一个世纪的变奏"},"origin":{"body":"大吉利诞生于1898年的古巴圣地亚哥附近。一位名叫詹宁斯·考克斯（Jennings Cox）的美国矿业工程师在Daiquiri村附近管理一座铁矿。在一个炎热的下午，他的金酒喝完了——这在古巴偏远地区是很常见的窘境。他手边只有当地的朗姆酒、青柠和糖。他将这三样东西混合在一起——朗姆酒、鲜榨青柠汁、细砂糖——用摇酒壶加冰摇和。他用村子名字命名了它。\n\n这个配方后来被介绍到哈瓦那的El Floridita酒吧——这家酒吧后来成为古巴最著名的鸡尾酒吧之一。El Floridita的调酒师Constantino Ribalaigua将这个简单的配方精细化：他用白朗姆代替深色朗姆、精确控制青柠汁和糖的比例、用摇酒壶而不是搅拌杯——因为青柠汁需要被充分混合。\n\n大吉利是世界上最具影响力的三成分鸡尾酒——烈酒+柑橘+甜——它建立了一个模板，后来的威士忌酸、玛格丽特、边车都遵循同一个黄金比例。","title":"诞生：1898年的古巴，一位矿业工程师与朗姆酒的邂逅"},"funFact":{"body":"1930年代，欧内斯特·海明威住在哈瓦那。他每天都会走进El Floridita酒吧——这是他从住所步行可达的距离内最好的酒吧。海明威不喜欢甜味，所以Constantino为他特制了一个无糖版本——双份朗姆、青柠汁、葡萄柚汁、樱桃利口酒——没有糖。这杯酒被称为Papa Doble（海明威老爹双份）或Hemingway Daiquiri。海明威据说一次性可以喝掉16杯。今天El Floridita酒吧的角落里还立着一尊海明威的真人大小铜像——他永远坐在他最喜欢的吧台角落。\n\n大吉利的另一个秘密是青柠的榨法。青柠汁必须鲜榨——瓶装青柠汁在大吉利中无所遁形。青柠应该在榨之前先用手掌在桌面上滚动——这个动作破坏了青柠内部的果肉细胞结构，让出汁更容易。一杯大吉利需要大约半个青柠——取决于青柠的大小和季节。最好的大吉利是酸中带甜——糖不是为了盖住酸，而是为了平衡酸。","title":"趣味事实：海明威与双份大吉利、El Floridita的雕像和青柠的正确榨法"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Espresso Martini','意式浓缩马天尼（摇和）','新时代',ARRAY['50毫升 伏特加','30毫升 咖啡甘露利口酒','10毫升 单糖浆','1份 浓缩咖啡'],'{"legacy":{"body":"咖啡马天尼是少有的同时含有兴奋剂（咖啡因）和抑制剂（酒精）的鸡尾酒。这种对立的平衡正是它的魅力所在——让你在微醺的边缘保持足够的警觉，以至于你不会在晚餐桌上睡着。它也因此成为了全球最流行的餐后鸡尾酒之一。\n\n在21世纪，咖啡马天尼经历了二次复兴——精品咖啡文化渗透进了调酒界。现在的咖啡马天尼可以用单一产地浓缩咖啡（巴西、埃塞俄比亚、哥伦比亚不同产地的咖啡赋予不同的风味基底）、冷萃咖啡（更低的酸度、更丝滑的口感）、甚至加入了榛子利口酒、白巧克力利口酒或椰子奶油作为风味变奏。\n\n但它始终保持着那个矛盾的魅力：一杯让你同时感到清醒和微醺的鸡尾酒。","title":"延伸：提神与微醺的双重奏，21世纪餐后酒的标杆"},"origin":{"body":"咖啡马天尼是1980年代伦敦传奇调酒师Dick Bradsell的发明。Bradsell是伦敦手工鸡尾酒运动之父——他培训了一代伦敦调酒师。一个夜晚，一位著名的模特走进Fred''s Club——Bradsell当时的酒吧——对他说了那句传奇的话：\"给我一杯东西，能让我醒过来，然后把我砸晕。\"（Wake me up, then f**k me up。）\n\nBradsell将伏特加（砸晕）、浓缩咖啡（醒过来）、咖啡利口酒（加深咖啡味和甜度）和糖浆（平衡咖啡的苦味）摇在一起。这杯鸡尾酒没有名字——Bradsell只是把他手边的东西按照那位模特的需求组合起来。后来它被称为\"Espresso Martini\"——虽然它不含金酒也不含味美思。它叫\"马天尼\"只是因为装在马天尼杯里。\n\n咖啡马天尼在1990年代成为了伦敦豪饮文化的标志性饮品——它是新一代调酒师用新原料（浓缩咖啡当时在酒吧里并不常见）创造新经典的典范。","title":"诞生：1980年代的伦敦，一位模特和一杯需求"},"funFact":{"body":"咖啡马天尼的灵魂是浓缩咖啡——但浓缩咖啡在接触空气后会迅速氧化变苦。所以调酒师必须在浓缩咖啡萃取后的30秒内将它倒入摇酒壶——否则咖啡的风味会从\"深度烘焙\"变成\"焦苦的灰烬\"。这意味着你不能提前准备好浓缩咖啡——你必须在调制这杯酒的同时现磨现萃。\n\n摇和是咖啡马天尼的关键——剧烈摇和10-12秒会让咖啡的天然油脂和空气混合，产生一层浓郁的、棕色的crema泡沫。这层泡沫是咖啡马天尼的视觉标志——让它在马天尼杯中看起来像一杯迷你拿铁。如果摇和时间不够——没有泡沫；如果摇得太久——泡沫太密太厚失去了丝滑感。\n\n今天的精品咖啡版本使用单一产地浓缩咖啡、冷萃咖啡浓缩液甚至咖啡花蜂蜜——调酒师和咖啡师的协作让这杯酒的咖啡维度越来越深。","title":"趣味事实：浓缩咖啡的正确用法、摇和的时间窗口和泡沫的秘密"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Sidecar','边车','难忘经典',ARRAY['50毫升 干邑白兰地','20毫升 橙皮利口酒','20毫升 新鲜柠檬汁'],'{"legacy":{"body":"边车是白兰地调酒的标杆——它确立了三重奏（烈酒+橙皮利口酒+柠檬汁）作为白兰地调酒的黄金比例。后来的Between the Sheets（加了朗姆）、法国连接（白兰地+杏仁利口酒，材料更简单）都从这个公式变奏而来。\n\n一杯好的边车需要好的白兰地——VSOP或以上——因为这款酒对基酒的品质毫无遮掩。糖边是可选的——它增加了甜味和触感，但有些纯化论者认为糖边会干扰白兰地的复杂香气。\n\n边车也是你朋友在烈酒认证课程中会学到的重点酒款之一——它是理解白兰地调酒的关键。","title":"延伸：白兰地调酒的标杆，三重奏的发明者"},"origin":{"body":"边车据称诞生于巴黎丽兹酒店（Hotel Ritz Paris）的酒吧，由传奇调酒师弗兰克·梅耶（Frank Meier）创作。梅耶在1921-1947年间任丽兹酒店的调酒师——他的调酒师生涯几乎贯穿了整个爵士时代和二战。\n\n名字来源很有趣：一位美国军官每天骑着一辆带边车的摩托车来到丽兹酒店——边车在巴黎的寒冬中冷得像冰箱。他要求梅耶创制一款能在寒冷的冬夜\"预热\"他的鸡尾酒。梅耶将白兰地、橙皮利口酒和柠檬汁以2:1:1的比例摇和，加上糖边——边车从此诞生。\n\n另一位军官后来说这款酒像边车一样\"撞\"醒了他——酸和烈酒的组合确实像一次温和的碰撞。白兰地的温暖在口腔中扩散，柠檬汁的锋利穿透寒冷，橙皮利口酒的芳香将所有东西粘合在一起。","title":"诞生：1920年代的巴黎，丽兹酒店的边车与一位军官的早晨"},"funFact":{"body":"1940年纳粹占领巴黎后，丽兹酒店的酒吧继续营业——赫尔曼·戈林把丽兹当作他的巴黎总部。梅耶是一位立陶宛犹太人——这可能是最讽刺的事情：一个犹太调酒师在二战期间为纳粹高层调酒。\n\n梅耶在1940年代出版的调酒书中没有提及自己的犹太身份——他低调地活了下来，战后继续在丽兹工作直到去世。他的调酒书《The Artistry of Mixing Drinks》是调酒史上的重要文献——收录了数百款经典配方和梅耶自己的创作。\n\n丽兹酒店至今仍然供应边车——按照Frank Meier的原始配方。吧台后面的墙上挂着他的照片。每一位新来的调酒师都要学习按照梅耶的配方调一杯边车——这是丽兹酒店的传统，也是对一位在黑暗中调出光明的人的致敬。","title":"趣味事实：犹太调酒师与纳粹、丽兹酒店的灰色岁月和一位幸存者的故事"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Zombie','僵尸（摇和）','当代经典',ARRAY['45毫升 牙买加黑朗姆酒','45毫升 波多黎各金朗姆酒','30毫升 德梅拉拉朗姆酒','20毫升 新鲜青柠汁','15毫升 法勒纳姆利口酒','15毫升 唐混合液（葡萄柚汁：肉桂糖浆 2：1）','1茶匙 石榴糖浆','1滴 安哥斯图拉苦精','6滴 潘诺茴香酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。僵尸诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在僵尸的基础上创造新的变奏：用不同的基酒代替45毫升 牙买加黑朗姆酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n僵尸的持久遗产在于：它证明了一个简单的配方——45毫升 牙买加黑朗姆酒、45毫升 波多黎各金朗姆酒、30毫升 德梅拉拉朗姆酒、20毫升 新鲜青柠汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的僵尸——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对僵尸有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"僵尸的传承——经典配方的现代演绎"},"origin":{"body":"僵尸是一款当代经典鸡尾酒。IBA 官方将其列为「当代经典」（Contemporary Classics）——这些配方诞生于20世纪后期，但已经在全球范围内被广泛接受和演绎。它们代表了鸡尾酒从\"旧时代\"进入\"全球化\"时期的关键作品。\n\n僵尸的核心配料包括45毫升 牙买加黑朗姆酒、45毫升 波多黎各金朗姆酒、30毫升 德梅拉拉朗姆酒、20毫升 新鲜青柠汁。每一种配料都有其特定的角色：45毫升 牙买加黑朗姆酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 牙买加黑朗姆酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于僵尸的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，僵尸通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解僵尸的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于僵尸——一杯当代经典鸡尾酒的诞生"},"funFact":{"body":"僵尸的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n僵尸的主要烈酒是45毫升 牙买加黑朗姆酒。选择优质品牌的45毫升 牙买加黑朗姆酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 牙买加黑朗姆酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 牙买加黑朗姆酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的僵尸通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制僵尸——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于僵尸的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Naked and Famous','一脱成名（搅拌）','新时代',ARRAY['22.5毫升 梅斯卡尔','22.5毫升 黄查特利口酒','22.5毫升 阿佩罗','22.5毫升 新鲜青柠汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。一脱成名诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在一脱成名的基础上创造新的变奏：用不同的基酒代替22.5毫升 梅斯卡尔来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n一脱成名的持久遗产在于：它证明了一个简单的配方——22.5毫升 梅斯卡尔、22.5毫升 黄查特利口酒、22.5毫升 阿佩罗、22.5毫升 新鲜青柠汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的一脱成名——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对一脱成名有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"一脱成名的传承——经典配方的现代演绎"},"origin":{"body":"一脱成名是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n一脱成名的核心配料包括22.5毫升 梅斯卡尔、22.5毫升 黄查特利口酒、22.5毫升 阿佩罗、22.5毫升 新鲜青柠汁。每一种配料都有其特定的角色：22.5毫升 梅斯卡尔是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕22.5毫升 梅斯卡尔展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于一脱成名的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，一脱成名通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解一脱成名的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于一脱成名——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"一脱成名的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n一脱成名的主要烈酒是22.5毫升 梅斯卡尔。选择优质品牌的22.5毫升 梅斯卡尔对最终的结果至关重要——因为在这款鸡尾酒的配方中，22.5毫升 梅斯卡尔的个性无法被其他成分完全遮盖或稀释。一瓶好的22.5毫升 梅斯卡尔会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的一脱成名通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制一脱成名——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于一脱成名的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Russian Spring Punch','俄罗斯春季宾治（摇和）','新时代',ARRAY['25毫升 伏特加','25毫升 新鲜柠檬汁','15毫升 黑加仑利口酒','10毫升 单糖浆','起泡酒'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。俄罗斯春季宾治诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在俄罗斯春季宾治的基础上创造新的变奏：用不同的基酒代替25毫升 伏特加来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n俄罗斯春季宾治的持久遗产在于：它证明了一个简单的配方——25毫升 伏特加、25毫升 新鲜柠檬汁、15毫升 黑加仑利口酒、10毫升 单糖浆——可以被永恒地重新演绎而不失去其经典地位。一杯好的俄罗斯春季宾治——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对俄罗斯春季宾治有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"俄罗斯春季宾治的传承——经典配方的现代演绎"},"origin":{"body":"俄罗斯春季宾治是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n俄罗斯春季宾治的核心配料包括25毫升 伏特加、25毫升 新鲜柠檬汁、15毫升 黑加仑利口酒、10毫升 单糖浆。每一种配料都有其特定的角色：25毫升 伏特加是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕25毫升 伏特加展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于俄罗斯春季宾治的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，俄罗斯春季宾治通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解俄罗斯春季宾治的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于俄罗斯春季宾治——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"俄罗斯春季宾治的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n俄罗斯春季宾治的主要烈酒是25毫升 伏特加。选择优质品牌的25毫升 伏特加对最终的结果至关重要——因为在这款鸡尾酒的配方中，25毫升 伏特加的个性无法被其他成分完全遮盖或稀释。一瓶好的25毫升 伏特加会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的俄罗斯春季宾治通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制俄罗斯春季宾治——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于俄罗斯春季宾治的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Tommys Margarita','’汤米的玛格丽特（摇和）','新时代',ARRAY['60毫升 100%龙舌兰酒','30毫升 新鲜青柠汁','30毫升龙舌兰糖浆'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。’汤米的玛格丽特诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在’汤米的玛格丽特的基础上创造新的变奏：用不同的基酒代替60毫升 100%龙舌兰酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n’汤米的玛格丽特的持久遗产在于：它证明了一个简单的配方——60毫升 100%龙舌兰酒、30毫升 新鲜青柠汁、30毫升龙舌兰糖浆——可以被永恒地重新演绎而不失去其经典地位。一杯好的’汤米的玛格丽特——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对’汤米的玛格丽特有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"’汤米的玛格丽特的传承——经典配方的现代演绎"},"origin":{"body":"’汤米的玛格丽特是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n’汤米的玛格丽特的核心配料包括60毫升 100%龙舌兰酒、30毫升 新鲜青柠汁、30毫升龙舌兰糖浆。每一种配料都有其特定的角色：60毫升 100%龙舌兰酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕60毫升 100%龙舌兰酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于’汤米的玛格丽特的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，’汤米的玛格丽特通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解’汤米的玛格丽特的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于’汤米的玛格丽特——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"’汤米的玛格丽特的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n’汤米的玛格丽特的主要烈酒是60毫升 100%龙舌兰酒。选择优质品牌的60毫升 100%龙舌兰酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，60毫升 100%龙舌兰酒的个性无法被其他成分完全遮盖或稀释。一瓶好的60毫升 100%龙舌兰酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的’汤米的玛格丽特通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制’汤米的玛格丽特——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于’汤米的玛格丽特的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Yellow Bird','黄鸟（摇和）','新时代',ARRAY['30毫升 白朗姆酒','15毫升 加利安奴香草利口酒','15毫升 橙皮利口酒','15毫升 新鲜青柠汁'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。黄鸟诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在黄鸟的基础上创造新的变奏：用不同的基酒代替30毫升 白朗姆酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\n黄鸟的持久遗产在于：它证明了一个简单的配方——30毫升 白朗姆酒、15毫升 加利安奴香草利口酒、15毫升 橙皮利口酒、15毫升 新鲜青柠汁——可以被永恒地重新演绎而不失去其经典地位。一杯好的黄鸟——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对黄鸟有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"黄鸟的传承——经典配方的现代演绎"},"origin":{"body":"黄鸟是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\n黄鸟的核心配料包括30毫升 白朗姆酒、15毫升 加利安奴香草利口酒、15毫升 橙皮利口酒、15毫升 新鲜青柠汁。每一种配料都有其特定的角色：30毫升 白朗姆酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕30毫升 白朗姆酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于黄鸟的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，黄鸟通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解黄鸟的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于黄鸟——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"黄鸟的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\n黄鸟的主要烈酒是30毫升 白朗姆酒。选择优质品牌的30毫升 白朗姆酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，30毫升 白朗姆酒的个性无法被其他成分完全遮盖或稀释。一瓶好的30毫升 白朗姆酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的黄鸟通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制黄鸟——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于黄鸟的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Ve.n.to','温托（摇和）','新时代',ARRAY['45毫升 格拉巴酒','22.5毫升新鲜柠檬汁','15毫升 蜂蜜混合物（用洋甘菊代替水）','15毫升 洋甘菊利口酒','10毫升 蛋清（可选）'],'{"legacy":{"body":"每一杯经典鸡尾酒都是一个时代的切片。VE.N.TO VE.N.TO诞生于它的时代——但它超越了它的时代。今天，世界各地的调酒师们在VE.N.TO VE.N.TO的基础上创造新的变奏：用不同的基酒代替45毫升 格拉巴酒来探索完全不同的风味方向；加入手工利口酒和新鲜水果来增加新的维度；甚至用分子调酒技术（如油脂洗、浸渍、烟熏）来创造出全新的版本。\n\nVE.N.TO VE.N.TO的持久遗产在于：它证明了一个简单的配方——45毫升 格拉巴酒、22.5毫升新鲜柠檬汁、15毫升 蜂蜜混合物（用洋甘菊代替水）、15毫升 洋甘菊利口酒——可以被永恒地重新演绎而不失去其经典地位。一杯好的VE.N.TO VE.N.TO——无论它的变奏多么大胆——仍然会向你展示那个原始配方的骨架和灵魂。\n\n如果你对VE.N.TO VE.N.TO有更多的问题——关于它的历史、关于它的最佳调制技巧、或者关于它的现代变体——请继续浏览调酒百科的其他内容。我们的社区中有经验丰富的调酒师和鸡尾酒历史爱好者，他们定期贡献新的文章和配方解读。","title":"VE.N.TO VE.N.TO的传承——经典配方的现代演绎"},"origin":{"body":"VE.N.TO VE.N.TO是一款新时代鸡尾酒。IBA 官方将其列为「新时代」（New Era Drinks）——这些是21世纪前后在手工鸡尾酒运动中崛起的新经典。它们代表了调酒师在全球化、精品化和实验化时代的最新创作。\n\nVE.N.TO VE.N.TO的核心配料包括45毫升 格拉巴酒、22.5毫升新鲜柠檬汁、15毫升 蜂蜜混合物（用洋甘菊代替水）、15毫升 洋甘菊利口酒。每一种配料都有其特定的角色：45毫升 格拉巴酒是这杯酒的骨架和灵魂——它定义了酒的基本性格和力量方向；其他配料则围绕45毫升 格拉巴酒展开——提供酸度、甜度、苦味或芳香——共同构成一个平衡的风味体系。\n\n关于VE.N.TO VE.N.TO的详细起源故事，不同的调酒历史学家有不同的说法。一些经典鸡尾酒的配方因为年代久远——早期的酒吧没有系统地记录配方的习惯——所以不同版本之间存在差异。但无论如何，VE.N.TO VE.N.TO通过了一百多年的筛选——每一代调酒师都在制作它、改良它、在某些细节上争论不休——这本身就是一款经典鸡尾酒的最高荣誉。\n\n如果你想深入了解VE.N.TO VE.N.TO的完整故事——从它的诞生地到全球酒吧中的每一次变奏——我们正在编写一份详尽的专题文章。与此同时，你可以在配料和调制方法部分查看它的官方IBA配方。","title":"关于VE.N.TO VE.N.TO——一杯新时代鸡尾酒的诞生"},"funFact":{"body":"VE.N.TO VE.N.TO的调制方法有特定的技术要求。不同的调酒师对比例、摇和时间和装饰的选择有不同的见解——这些细节上的差异往往就是一杯\"好\"鸡尾酒和一杯\"伟大\"鸡尾酒之间的区别。\n\nVE.N.TO VE.N.TO的主要烈酒是45毫升 格拉巴酒。选择优质品牌的45毫升 格拉巴酒对最终的结果至关重要——因为在这款鸡尾酒的配方中，45毫升 格拉巴酒的个性无法被其他成分完全遮盖或稀释。一瓶好的45毫升 格拉巴酒会在这杯酒中留下它独特的风味印记：例如不同产区的同一类烈酒在口感、香气和尾味上都有微妙但决定性的差异。\n\n装饰也是不可忽视的细节。经典版本的VE.N.TO VE.N.TO通常使用柑橘皮（柠檬皮或橙皮）或樱桃作为装饰——但不同的调酒师选择不同的装饰品种来匹配他们使用的具体烈酒品牌。装饰不是可有可无的——它是附加的嗅觉维度：柑橘皮中的油脂在拧转时释放的挥发性芳香物会浮在酒液表面，在你端起杯子之前就进入你的鼻腔。\n\n如果你在自己家里尝试调制VE.N.TO VE.N.TO——注意三件事：使用鲜榨的柑橘汁（不要用瓶装替代品）、使用足够大的冰块（不要用小冰块——它们融化太快会过度稀释）、控制好摇和或搅拌的时间（过度稀释会毁掉这杯酒）。","title":"关于VE.N.TO VE.N.TO的趣闻与调制细节"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Remember the Maine','缅因回忆（搅拌）','难忘经典',ARRAY['60ml 黑麦威士忌','22.5ml 甜味美思','2茶匙 樱桃利口酒','1茶匙 苦艾酒'],'{"legacy":{"body":"缅因回忆常被形容为\"曼哈顿的加勒比表亲\"。它与曼哈顿共享黑麦威士忌+甜味美思+苦精的骨架，但用樱桃利口酒和苦艾酒替代了传统的安格斯特拉苦精——赋予了这杯酒更明亮的果香和更复杂的茴香尾味。今天，缅因回忆在全球的经典鸡尾酒吧中被重新发现——它是\"被遗忘的经典\"（forgotten classic）之一。","title":"延伸：曼哈顿的加勒比变奏"},"origin":{"body":"缅因回忆（Remember the Maine）诞生于1930年代的古巴哈瓦那，由传奇调酒师Constantino Ribalaigua在El Floridita酒吧创作。Constantino是哈瓦那最著名的调酒师之一——他也是海明威的双份大吉利（Papa Doble）的发明者。这款酒的名字来自1898年在哈瓦那港爆炸的美国军舰缅因号（USS Maine）——这起事件直接引发了美西战争。Constantino用黑麦威士忌（美国本土烈酒）、甜味美思（意大利开胃酒）、樱桃利口酒和苦艾酒创作了这杯鸡尾酒——\"记住缅因号\"——一杯在古巴纪念美国事件的鸡尾酒。","title":"诞生：1930年代的古巴哈瓦那"},"funFact":{"body":"海明威在哈瓦那的El Floridita酒吧不止喝大吉利。缅因回忆是他在这间酒吧的第二杯最常点的鸡尾酒。与海明威的大吉利（Hemingway Daiquiri——无糖版本）不同，缅因回忆是一杯搅拌而非摇和的深色烈酒鸡尾酒——更接近曼哈顿而不是大吉利。黑麦威士忌的辛辣、甜味美思的饱满、樱桃利口酒的甜香和苦艾酒的茴香尾味——构成了一个深色烈酒的复杂四重奏。","title":"趣味事实：海明威的另一杯"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Cardinale','红衣主教（直调）','当代经典',ARRAY['60ml 金巴利','90ml 普罗塞克起泡酒','苏打水'],'{"legacy":{"body":"在意大利的咖啡馆中，红衣主教（Cardinale）是下午开胃酒时间（aperitivo hour）的常见选择。它的低酒精度（约8%ABV——大部分体积是普罗塞克和苏打水）让它可以被一饮而尽而不会让人醉倒。金巴利的深红色和微泡在杯中形成了一种独特的视觉效果——一杯红色的\"意大利午后\"。","title":"延伸：意大利开胃酒的红色代表"},"origin":{"body":"红衣主教（Cardinale）是意大利斯普里茨（Spritz）家族的成员之一——与阿佩罗橙光（Aperol Spritz）和威尼斯斯普里茨（Spritz Veneziano）同属一个开胃酒家族。它用金巴利代替阿佩罗——金巴利的深红色和更强烈的苦味赋予这杯酒\"红衣主教\"之名（金巴利的颜色与天主教红衣主教的法衣颜色相似）。","title":"诞生：意大利——斯普里茨的变奏"},"funFact":{"body":"斯普里茨（Spritz）不是一款酒——它是一种调酒类型：利口酒+起泡酒+苏打水。金巴利斯普里茨（红衣主教）、阿佩罗斯普里茨（阿佩罗橙光）和阿马罗斯普里茨是意大利斯普里茨家族的三大支柱。红衣主教是最\"苦\"的版本——金巴利的60种药草和水果的复杂苦甜味在普罗塞克的起泡中层层展开。","title":"趣味事实：斯普里茨家族"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Garibaldi','加里波第（直调）','当代经典',ARRAY['60ml 金巴利','120ml 鲜榨橙汁'],'{"legacy":{"body":"加里波第是意大利开胃酒文化的精华——两种配料、不加冰块、不加装饰。它代表了意大利人对\"简单中的完美\"的追求。在米兰的咖啡馆中，加里波第是早餐和早午餐的热门选择——它据说有\"提神和开胃\"的双重功效（金巴利的药草刺激消化，橙汁提供维生素）。","title":"延伸：最简洁的意大利开胃酒"},"origin":{"body":"加里波第（Garibaldi）的名字来自意大利民族英雄朱塞佩·加里波第（Giuseppe Garibaldi）——19世纪意大利统一运动的核心领导人之一。这款酒用金巴利（意大利苦味利口酒的标志）和鲜榨橙汁——两种意大利最著名的产品——来纪念意大利的民族英雄。加里波第将军以他的红衫军闻名——而金巴利的红色恰好与红衫军的颜色呼应。","title":"诞生：意大利——以民族英雄命名"},"funFact":{"body":"加里波第可能是所有IBA鸡尾酒中最简单的配方之一——只有两种配料：金巴利和鲜榨橙汁。但它的成功完全取决于橙汁的正确处理。橙汁必须在榨取后立即使用——榨后超过30分钟的橙汁开始氧化并失去明亮的果香。加里波第不加冰块——两种配料直接在杯中混合——所以橙汁的新鲜度在这杯酒中完全暴露。一杯好的加里波第是酸苦平衡的——金巴利的60种药草的复杂苦味在鲜榨橙汁的鲜活甜酸中浮动。","title":"趣味事实：橙汁的正确处理"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Godfather','教父（直调）','当代经典',ARRAY['45ml 苏格兰威士忌','45ml 杏仁利口酒（Amaretto）'],'{"legacy":{"body":"教父有一个直接的变奏——\"教母\"（Godmother）：用伏特加代替苏格兰威士忌，同样与杏仁利口酒等比例混合。伏特加的中性不干扰Amaretto的甜杏仁风味——教母比教父更\"温柔\"——没有苏格兰威士忌的烟熏和辛辣。教父和教母是调酒界最简单的1:1等比例之一。","title":"延伸：教母鸡尾酒"},"origin":{"body":"教父（Godfather）鸡尾酒的名字直接来自1972年弗朗西斯·福特·科波拉导演的电影《教父》。这款酒诞生于1970年代——苏格兰威士忌（意大利裔黑手党成员偏爱的烈酒，象征权力和传统）混合意大利杏仁利口酒（Amaretto——意大利甜品利口酒的标志，象征家族和甜味）。两者等量——1:1——威士忌的烟熏辛辣与杏仁的甜香形成一个出人意料的和谐组合。","title":"诞生：1970年代——电影的影子"},"funFact":{"body":"教父鸡尾酒是最早以电影命名的鸡尾酒之一——在《教父》三部曲的1970年代风靡美国。据说马龙·白兰度在拍摄《教父》期间最喜欢喝的是一杯苏格兰威士忌加一点Amaretto——调酒师们后来简化了这个配方为等比例。教父是电影文化对调酒界影响的早期例子——后来的大都会（《欲望都市》）和Old Fashioned复兴（《广告狂人》）都受其启发。","title":"趣味事实：电影鸡尾酒的先驱"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Godmother','教母（直调）','当代经典',ARRAY['45ml 伏特加','45ml 杏仁利口酒（Amaretto）'],'{"legacy":{"body":"教父和教母是极简主义调酒的典范——两种配料、直调、加冰。它们证明了鸡尾酒不需要复杂才能好喝。在手工鸡尾酒复兴的时代——调酒师们追求复杂和创意——教父和教母的极简反而成为一种反潮流：有时候，一杯简单的酒就是最好的酒。","title":"延伸：调酒的极简主义"},"origin":{"body":"教母（Godmother）是教父（Godfather）的直接变奏——用伏特加代替苏格兰威士忌。伏特加的中性让杏仁利口酒的甜香成为唯一的主角——没有苏格兰威士忌的烟熏和辛辣来竞争。它比教父更\"柔和\"——一杯纯甜的、杏仁味的伏特加饮品。","title":"诞生：教父的伏特加变奏"},"funFact":{"body":"教父和教母代表了调酒界最简洁的配方类型：烈酒+利口酒等比例。不需要调酒师的专业技巧——只需要倒入杯中加入冰块搅拌即可。这种简洁让它们在任何酒吧——从高级酒店到家庭厨房——都可以被调制。批评者认为它们\"太简单\"不能成为鸡尾酒——支持者认为正是这种简洁让它们成为了真正的\"经典\"。","title":"趣味事实：1:1等比例的简洁"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Harvey Wallbanger','哈维撞墙（直调）','当代经典',ARRAY['45ml 伏特加','120ml 橙汁','15ml 加利亚诺利口酒（Galliano）'],'{"legacy":{"body":"哈维撞墙是1970年代美国鸡尾酒文化的象征——那个时代喜欢伏特加、甜味和简单的高球鸡尾酒。它在1980年代后逐渐失宠——被更复杂的鸡尾酒取代——但在意大利和某些冲浪文化海滩酒吧中仍然保持着忠实粉丝群。加利亚诺的香草-茴香风味——高于橙汁之上——是这杯酒独一无二的味觉标志。","title":"延伸：1970年代的代名词"},"origin":{"body":"哈维撞墙（Harvey Wallbanger）诞生于1960年代的加州——冲浪文化、阳光和海滩的十年。据说一位名叫Harvey的冲浪手在加州曼哈顿海滩的一家酒吧中发明了这款酒——他用伏特加和橙汁（螺丝刀Screwdriver——美国最简单的高球鸡尾酒）加上一层漂浮的加利亚诺利口酒（Galliano——一种意大利香草利口酒）。加利亚诺的香草和茴香风味漂浮在橙汁和伏特加之上——形成了一种分层的视觉效果。","title":"诞生：1960年代的加州冲浪海岸"},"funFact":{"body":"哈维撞墙在1970年代早期风靡美国——部分是因为加利亚诺利口酒的进口商George Bednar进行了一场大规模的营销活动。他创造了一个卡通角色——\"Harvey Wallbanger\"——一个戴着冲浪帽、拿着加利亚诺瓶子的小人。这个卡通出现在T恤、海报和酒吧菜单上。1972年，哈维撞墙是美国最受欢迎的鸡尾酒之一——仅次于马天尼和曼哈顿。","title":"趣味事实：营销史上的成功案例"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('B-52','B52轰炸机（分层）','新时代',ARRAY['20ml 咖啡利口酒（Kahlua）','20ml 爱尔兰奶油利口酒（Baileys）','20ml 橙皮利口酒（Grand Marnier或Cointreau）'],'{"legacy":{"body":"B-52轰炸机是分层鸡尾酒的终极表达。它代表了对调酒精确控制的追求——通过利口酒密度的精确差异来维持分层的完整性。B-52有无数变奏：B-53（用Absinthe代替橙皮利口酒），B-54（用Amaretto代替橙皮利口酒），和\"燃烧的B-52\"（点燃最上层的橙皮利口酒——酒吧常见的视觉效果）。","title":"延伸：分属于调酒的极限"},"origin":{"body":"B-52轰炸机（B-52）诞生于1970年代——分层鸡尾酒（layered shooter）时代的标志性作品。它的名字来自美国空军的B-52同温层堡垒轰炸机——这款酒用三种不同密度的利口酒分层倒入小杯中：咖啡利口酒（最重，底层）、爱尔兰奶油利口酒（中间密度，中层）、橙皮利口酒（最轻，顶层）。三层颜色分明的视觉效果让它成为了世界上最出名的\"一口闷\"鸡尾酒（shooter）之一。","title":"诞生：1970年代的分层鸡尾酒"},"funFact":{"body":"B-52轰炸机的分层不是魔法——它是密度差。咖啡利口酒含糖量最高密度最大（约1.15 g/mL），爱尔兰奶油利口酒其次（约1.05 g/mL），橙皮利口酒最轻（约0.95 g/mL）。用勺子背轻轻倒入——每种利口酒沿勺子背面缓缓流下——可以保持层次分明不混合。如果倒酒精过快或勺子角度错误——三层会混合成一团不清晰的灰色液体。","title":"趣味事实：分层的科学"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Dirty Martini','脏马天尼（搅拌）','新时代',ARRAY['60ml 金酒（或伏特加）','10ml 干味美思','15ml 橄榄盐水'],'{"legacy":{"body":"脏马天尼代表了马天尼在现代的进化方向——从禁酒令时期的精致透明变成了今天的咸味、复杂和个性化饮品。不同的酒吧使用不同的橄榄盐水：一些用标准的绿橄榄盐水（Pimento-stuffed olive brine），一些用高级的Luxardo黑樱桃橄榄盐水，还有一些用自制的辣椒浸泡橄榄盐水。一杯脏马天尼的好坏取决于橄榄盐水的质量——一瓶好的橄榄盐水胜过一瓶差的味美思。","title":"延伸：马天尼的现代面孔"},"origin":{"body":"脏马天尼（Dirty Martini）是马天尼最著名的变奏之一——向传统的干马天尼中加入橄榄盐水（olive brine）。这个简单的添加从根本上改变了马天尼的口感：盐水中的盐抑制了舌头上的苦味感受器，让金酒的杜松子变得更圆润、更柔和。它不像干马天尼那样尖锐透明——脏马天尼是朦胧的、云状的、咸的——一杯完全不同的马天尼。","title":"诞生：马天尼的咸味革命"},"funFact":{"body":"橄榄盐水中含有的氯化钠是脏马天尼的味觉中心。盐通过抑制舌头上的TAS2R苦味感受器来减少苦味的感知——同时增强甜味和鲜味的感知。这意味着：脏马天尼中的金酒比干马天尼中的金酒尝起来更柔和、更甜美（即使没有加糖）。这是一个简单的化学技巧——用盐来\"甜化\"一杯苦味饮品。","title":"趣味事实：盐的化学"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Kamikaze','神风敢死队（摇和）','新时代',ARRAY['30ml 伏特加','30ml 橙皮利口酒','30ml 青柠汁'],'{"legacy":{"body":"神风敢死队代表了伏特加鸡尾酒最纯粹的三角公式：伏特加+橙皮利口酒+青柠汁——没有其他配料。这杯酒的成败完全取决于橙皮利口酒的品质——一瓶好的Cointreau或Grand Marnier让神风敢死队从\"伏特加果汁\"变成了一款正经的鸡尾酒；一瓶廉价的橙皮利口酒则让这杯酒成为一杯甜腻的糖浆。","title":"延伸：伏特加鸡尾酒的极简表达"},"origin":{"body":"神风敢死队（Kamikaze）诞生于1970年代美国——日本文化影响美国流行时期的产物。它用伏特加、橙皮利口酒和青柠汁等比例摇和——1:1:1——这是一个与玛格丽特（龙舌兰+橙皮利口酒+青柠汁）几乎相同的配方，只是用伏特加替代了龙舌兰。\"Kamikaze\"是二战期间日本海军的神风特攻队——这款酒的名字可能暗示了它的\"冲击力\"——等比例的伏特加让这杯看起来像果汁的饮品实际上相当有力。","title":"诞生：1970年代的日本主题酒吧"},"funFact":{"body":"神风敢死队、大都会和柠檬滴马天尼——这三款\"伏特加+橙皮利口酒+柑橘汁\"的经典鸡尾酒共享同一个DNA。神风敢死队是最简洁的版本（1:1:1），大都会加了蔓越莓汁染色，柠檬滴马天尼用柠檬汁代替青柠汁并加了糖边。这三款酒是1980-1990年代美国伏特加鸡尾酒爆炸的三大支柱。","title":"趣味事实：伏特加的三角"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Rabo de Galo','公鸡尾巴（搅拌）','新时代',ARRAY['60ml 卡莎萨（Cachaca）','30ml 甜味美思','15ml 金巴利'],'{"legacy":{"body":"公鸡尾巴常被描述为\"巴西的内格罗尼\"。它共享了内格罗尼的骨架（烈酒+甜味美思+金巴利），但卡莎萨的鲜活甘蔗风味让它走向了完全不同的方向——更甜、更热带、更\"绿\"。这是巴西送给鸡尾酒世界的最重要礼物。在巴西的街头酒吧中，公鸡尾巴是日常最常点的鸡尾酒之一。","title":"延伸：巴西的内格罗尼"},"origin":{"body":"公鸡尾巴（Rabo de Galo）是巴西的国饮之一——用巴西的本土烈酒卡莎萨（Cachaca——甘蔗汁烈酒，不同于朗姆酒使用糖蜜）为基酒。\"Rabo de Galo\"在葡萄牙语中意为\"公鸡尾巴\"——据说因为这款酒的颜色像公鸡尾巴一样是深琥珀色的。这款酒的配方类似于内格罗尼（烈酒+甜味美思+金巴利），但用卡莎萨替代了金酒——卡莎萨的甘蔗鲜甜让这杯酒比内格罗尼更\"热带\"。","title":"诞生：巴西——卡莎萨的鸡尾酒"},"funFact":{"body":"卡莎萨与朗姆的最大区别在于原料：卡莎萨使用新鲜的甘蔗汁直接发酵蒸馏（保留更鲜活的甘蔗植物风味），而朗姆使用制糖的副产品——糖蜜（molasses）。因此卡莎萨带有更鲜活的甘蔗、青草和草本植物的风味——在公鸡尾巴中，卡莎萨的这些特征与金巴利的苦和甜味美思的甜形成了独特的巴西式三角平衡。巴西是全球卡莎萨消费量最高的国家——每年消费超过15亿升卡莎萨。","title":"趣味事实：卡莎萨 vs 朗姆"}}');
INSERT INTO cocktails (eng,chn,cat,ingredients,story) VALUES ('Vampiro','吸血鬼（摇和）','新时代',ARRAY['50ml 龙舌兰','30ml 番茄汁','20ml 橙汁','15ml 青柠汁','15ml 蜂蜜糖浆','辣酱','盐'],'{"legacy":{"body":"在墨西哥的周日早午餐中，吸血鬼是少不了的一杯。它的颜色——深血红色——和名字在万圣节和亡灵节（Dia de los Muertos）期间特别流行。像血腥玛丽一样，吸血鬼也成为了装饰竞赛的受害者——一些酒吧在杯口插上虾、培根、甚至整只迷你墨西哥卷饼。但一杯好的吸血鬼——新鲜果汁、好龙舌兰和正确的辣度——是世界上最复杂的番茄汁鸡尾酒之一。","title":"延伸：墨西哥早午餐的官方饮品"},"origin":{"body":"吸血鬼（Vampiro）是血腥玛丽（Bloody Mary）的墨西哥表亲——用龙舌兰代替伏特加，在番茄汁、青柠汁和辣酱的基础上加入了橙汁和蜂蜜。\"Vampiro\"在西班牙语中意为\"吸血鬼\"——这个名字可能来自这杯酒的深红色以及它据说有\"复活宿醉者\"的能力（像吸血鬼吸食血液一样）。这款酒在墨西哥的街头酒吧中无处不在——尤其是在龙舌兰产区哈利斯科州。","title":"诞生：墨西哥——血腥玛丽的龙舌兰表亲"},"funFact":{"body":"番茄汁在鸡尾酒中的使用始于1920年代——血腥玛丽是最早使用番茄汁的经典鸡尾酒之一。番茄汁中的鲜味氨基酸（特别是谷氨酸——与味精相同的化合物）提供了第五种味觉\"鲜味\"（umami）——这种味道与龙舌兰的辛辣和橙汁的甜酸形成了一种极其复杂的味觉结构。吸血鬼的鲜味维度是血腥玛丽的进化——辣酱和蜂蜜的加入让它比血腥玛丽更\"墨西哥\"。","title":"趣味事实：番茄汁的起源"}}');
INSERT INTO spirits (slug,name,eng,emoji,description,hero,details) VALUES ('vodka','伏特加','Vodka','🍶','纯粹到极致——水与乙醇的二重奏。俄罗斯的黑麦、波兰的马铃薯、瑞典的冬小麦。','水与乙醇的终极净化。伏特加不争不抢——它把自己的性格降到最低，成为其他风味最忠实的载体。','{"sections":[{"items":[{"body":"俄罗斯是伏特加的精神家园——\"Vodka\"这个词源自俄语\"voda\"（水）的爱称\"vodka\"——\"小水\"。俄罗斯伏特加的传统原料是黑麦和小麦——两种在俄罗斯严寒的气候中能够稳定生长的谷物。\n\n俄罗斯伏特加的酿造哲学可以概括为：\"越纯净越好\"。传统上使用多次蒸馏（3-5次）和桦木炭或其他活性炭过滤来去除杂质——直到只剩下水和乙醇的最纯粹混合物。俄罗斯人声称最好的伏特加应该\"闻起来什么都没有，尝起来像水，但让你温暖。\"\n\n代表品牌：Russian Standard（圣彼得堡——用列宁格勒州的冬小麦和拉多加湖的冰川融水）、Stolichnaya（莫斯科——黑麦和小麦的经典混合，全球最畅销的俄罗斯伏特加之一）、Beluga（西伯利亚——高端俄罗斯伏特加，使用西伯利亚的深井水）。","label":"俄罗斯伏特加 Russian Vodka"},{"body":"波兰与俄罗斯争议谁是伏特加的起源地——两个国家都有数百年的伏特加蒸馏历史。波兰伏特加的传统原料是马铃薯——这是与俄罗斯最大的区别。马铃薯伏特加比谷物伏特加更奶油、更饱满、口感更厚重——一种独特的丝滑感。\n\n波兰伏特加的分类中有几个独特的子类型：\"Wyborowa\"（精选——马铃薯伏特加）、\"Zytnia\"（黑麦伏特加——更辛辣、更干燥）、\"Ziemniaczana\"（马铃薯伏特加——法定必须使用100%马铃薯原料）。波兰法律规定波兰伏特加必须在波兰本土蒸馏并使用波兰本土原料。\n\n代表品牌：Chopin（以波兰作曲家肖邦命名——全世界最高端的马铃薯伏特加之一——使用波兰本土种植的马铃薯）、Belvedere（波兰——黑麦伏特加——全球最畅销的波兰伏特加）、Zubrowka（野牛草伏特加——每一瓶都有一片野牛草叶片——来自波兰比亚沃维耶扎原始森林——是世界上最后一片欧洲野牛栖息地）。","label":"波兰伏特加 Polish Vodka"},{"body":"北欧国家——瑞典、芬兰、挪威、丹麦——在20世纪后期崛起为全球重要的伏特加产地。北欧伏特加的原料以冬小麦为主——在寒冷漫长的北欧冬季中缓慢生长的冬小麦积累了更多的天然糖分和风味前体——蒸馏后比温暖气候的小麦伏特加更\"甜\"和更\"饱满\"。\n\n北欧伏特加的水源常常是其卖点——冰川融水、深井水和湖泊水在营销中被强调为\"北欧纯净度\"的象征。北欧品牌在伏特加全球营销中创造了\"生活态度\"的市场定位——将伏特加与北欧设计、自然和现代生活联系在一起。\n\n代表品牌：Absolut（瑞典——全球最畅销的北欧伏特加——1980年代的艺术广告营销史上最著名的烈酒品牌广告之一）、Finlandia（芬兰——六棱柱瓶身设计——从芬兰的冰川湖取水）、Reyka（冰岛——使用冰岛的火山岩过滤——世界上最\"手工\"的伏特加之一——每批只用一个小蒸馏器生产几百瓶）。","label":"北欧伏特加 Nordic Vodka"},{"body":"法国伏特加的出现似乎是一个矛盾——法国的酿酒传统以葡萄酒和白兰地为主，伏特加（高纯度的谷物烈酒）似乎在法国没有文化根基。但正是因为法国拥有世界上最先进的蒸馏技术（来自干邑和雅文邑产业），法国能够生产出具有独特风味的葡萄基伏特加。\n\n法国伏特加的主要原料是葡萄——不同于使用谷物或马铃薯的传统伏特加产区。葡萄伏特加带有微妙的果香和天然甜味——这是传统谷物伏特加无法复制的特征。蒸馏过程中使用干邑的铜制壶式蒸馏器——让伏特加比使用柱式蒸馏器的传统伏特加有更圆润的口感。\n\n代表品牌：Ciroc（法国——全球最著名的葡萄伏特加——用法国西南部的Mauzac和Ugni Blanc葡萄酿造）、Grey Goose（法国——用皮卡第地区的冬小麦和干邑地区的地下泉水蒸馏——代表了法国奢侈伏特加的市场定位）。","label":"法国伏特加 French Vodka"},{"body":"21世纪的精酿蒸馏运动也改变了伏特加。传统上伏特加被定义为\"无色无味\"——但精酿蒸馏厂开始挑战这个定义：使用单一原料（单一农场的黑麦、特定产区的玉米、有机认证的马铃薯）、保持微量的\"基酒香气\"（不进行极端的过滤以保留原料的天然风味）、甚至使用\"桶陈伏特加\"（在橡木桶中短暂陈年赋予伏特加浅金色和微甜的香草风味）。\n\n精酿伏特加的理念是：\"伏特加不应该是无味的——它应该带有它所使用原料的微妙特征。\"这个理念与传统伏特加定义——\"纯乙醇和水\"——形成了根本性的分歧。但在美国——根据TTB（酒精和烟草税务和贸易局）的规定——伏特加必须\"无色无味\"——精酿伏特加的微妙风味在法律上是违规的——但这个规定在精酿蒸馏者的持续施压下正在被重新评估。\n\n代表品牌：Tito''s（德克萨斯——玉米伏特加——美国最畅销的精酿伏特加——价格实惠品质可靠）、Hangar 1（加州——使用葡萄酒桶陈年伏特加——水果伏特加的先驱）、Chase（英国——使用英国本土种植的马铃薯——从农场到瓶子的垂直整合生产）。","label":"精酿伏特加 Craft Vodka"}],"title":"伏特加的流派"},{"items":[{"body":"伏特加+橙皮利口酒+青柠汁+蔓越莓汁。欲望都市的粉红色签名——伏特加的中性让蔓越莓和青柠的风味主导这杯酒。Absolut Citron（柠檬味伏特加）是大都会的传统基酒——柠檬味的添加与青柠汁叠加了一层额外的柑橘维度。","label":"大都会 Cosmopolitan"},{"body":"伏特加+番茄汁+柠檬汁+伍斯特酱+辣酱。早午餐之王——伏特加的中性让它成为这台复杂的鲜味机器最好的基础烈酒——不与番茄汁的鲜味和其他调味品的香料产生竞争。","label":"血腥玛丽 Bloody Mary"},{"body":"伏特加+姜汁啤酒+青柠汁。铜杯是标配——伏特加的中性让姜汁啤酒成为这杯酒中唯一的\"风味主角\"。辛辣姜汁和青柠汁在伏特加的醇厚基底上碰撞——铜杯让这杯酒的温度降到几乎所有其他鸡尾酒都无法达到的冰冷。","label":"莫斯科骡子 Moscow Mule"}],"title":"伏特加的经典配方"}]}');
INSERT INTO spirits (slug,name,eng,emoji,description,hero,details) VALUES ('tequila','龙舌兰','Tequila','🌵','墨西哥烈日下，一株蓝色龙舌兰需要七年才能成熟。从 blanco 的青涩到 anejo 的深邃，每一口都是沙漠与时间的对话。','龙舌兰是墨西哥的灵魂。蓝色龙舌兰需要7至10年才能成熟，而真正的龙舌兰酒只能在哈利斯科州和其他四个指定区域生产。它不是派对上的速醉工具——它是烈日、火山土和时间的三重奏。','{"sections":[{"items":[{"body":"银色龙舌兰是龙舌兰最纯粹的形式——蒸馏后不陈年或仅短时间\"休息\"（放置在不锈钢罐中软化——不超过60天）。它保留了蓝色龙舌兰最原始的辛辣、青草、柑橘和辛辣胡椒的风味——没有橡木桶的香草和焦糖来\"驯服\"它的野性。\n\n银色龙舌兰的所有风味都来自蓝色龙舌兰本身——以及它生长的土壤（火山土富含铁和其他矿物质——给予龙舌兰一种独特的\"土质感\"）、气候（哈利斯科州的高海拔——龙舌兰田夜间温度低——延长了龙舌兰的生长周期——让糖分积累更丰富）和蒸馏工艺（好的龙舌兰使用铜制壶式蒸馏器——劣质龙舌兰使用柱式蒸馏器连续蒸馏——两者风味差异巨大）。\n\n银色龙舌兰是制作玛格丽特最传统的基酒选择——它的辛辣和植物的鲜绿是玛格丽特不可妥协的风味基石。代表品牌：Patron Silver（最著名的高端银色龙舌兰）、Don Julio Blanco（手工蒸馏——哈利斯科州高地龙舌兰）、Fortaleza Blanco（小批量——传统石磨压榨龙舌兰芯——火山岩坑烤）。","label":"银色/白色龙舌兰 Blanco / Plata"},{"body":"\"Reposado\"在西班牙语中意为\"休息过的\"——在橡木桶中陈年2个月至1年。这是龙舌兰的\"甜点时刻\"——橡木桶的香兰素（香草）和内酯（椰子）开始与龙舌兰的辛辣植物风味结合——产生一种独特的\"龙舌兰香草\"风味。\n\n微陈龙舌兰在橡木桶中的陈年时间从60天到一年不等。橡木桶的类型各不相同：美国波本桶（最常用——赋予香草和焦糖）、法国橡木桶（更高单宁——赋予结构和辛辣感）、甚至部分使用雪莉桶或干邑桶（赋予干果和坚果风味）。\n\nReposado是许多龙舌兰爱好者的\"入口点\"——它比Blanco更柔和——但比Anejo更保留了龙舌兰的原始特征——是平衡的完美点。代表品牌：Clase Azul Reposado（手工制作的陶瓷瓶——风味极其圆润）、Casamigos Reposado（好莱坞背景——制作了非常顺滑的风格）、Herradura Reposado（以马掌形蒸馏所命名——桶陈年的先驱之一）。","label":"微陈龙舌兰 Reposado"},{"body":"\"Anejo\"在西班牙语中意为\"陈年的\"——在橡木桶中陈年1至3年。这个级别是龙舌兰的\"威士忌化\"：长时间的桶接触将龙舌兰转化成一款与陈年威士忌和干邑可比拟的深色烈酒。深琥珀色、香草、焦糖和辛香料的甜感——龙舌兰的原始植物风味现在成为了背景而非前景——为橡木桶风味提供了一个独特的\"墨西哥\"基底。\n\nAnejo龙舌兰的饮用方式通常不混合——纯饮或加冰——因为它本身的复杂度已经不需要果汁或利口酒的辅助。它也是高端玛格丽特的升级选择——用Anejo代替Blanco制作玛格丽特——这杯酒从\"清爽的酸\"变成\"深沉的复杂的酸\"——橡木桶的风味为酸和盐提供了一个全新的维度。\n\n代表品牌：Don Julio 1942（全球最著名的Anejo——深琥珀色——香草和烘烤龙舌兰芯的奇妙混合）、Jose Cuervo Reserva de la Familia（每年限量——墨西哥最古老的龙舌兰品牌的特藏）、Herradura Seleccion Suprema（超高端Anejo——桶陈年超过4年）。","label":"陈年龙舌兰 Anejo"},{"body":"Extra Anejo（超陈年）在橡木桶中陈年3年以上——这个级别是2006年才被墨西哥法定标准新增的。在Anejo（1-3年）和Extra Anejo（3年+）之间的差距是巨大的——3年以上的桶陈年开始让龙舌兰接近超陈年威士忌或干邑XO的复杂度：干果（无花果、枣子）、焦糖坚果（核桃、杏仁）、皮革和黑巧克力的深沉感——龙舌兰的原始青草和植物风味现在几乎完全转化为这些深色的桶陈年风味。\n\nExtra Anejo的品质取决于桶的选择和蒸馏所的基础工艺。一些超陈龙舌兰使用单一美国波本桶——保持一致的风味谱；其他则在陈年中从波本桶转移到雪莉桶或干邑桶进行\"二次陈年\"（double aging）——增加了风味的复杂度和层次。\n\n代表品牌：Gran Patron Burdeos（在波尔多红酒桶中陈年——世界上最昂贵的龙舌兰之一）、Tequila Ocho Extra Anejo（单一庄园——单一年份——龙舌兰界的\"年份酒\"理念——每年在不同的单一庄园收获龙舌兰分别独立酿造）、Avion Reserva 44（44个月陈年——篮球明星投资的品牌）。","label":"超陈龙舌兰 Extra Anejo"},{"body":"梅斯卡尔（Mezcal）是龙舌兰的野生远亲——\"Mezcal\"是一个总称——包括任何使用龙舌兰属植物（maguey——龙舌兰的近亲）蒸馏的烈酒。Tequila是Mezcal的一种——但并非所有Mezcal都是Tequila——就像香槟是起泡酒的一种但并非所有起泡酒都是香槟。\n\n梅斯卡尔与龙舌兰的工艺差异在于：梅斯卡尔使用的龙舌兰芯（pina）是在地下坑中用火山岩和木炭烘烤数日——烟雾渗透进龙舌兰芯——赋予梅斯卡尔独特的烟熏风味（\"烤龙舌兰\"）。龙舌兰则使用地上蒸汽烘烤——避免了烟熏风味让龙舌兰的原始植物风味保持干净。\n\n梅斯卡尔的风味比龙舌兰更野——它是一种难以驯服的烈酒——烟熏、泥土、辣椒、热带水果和矿物质的复杂交织。高端梅斯卡尔使用野生龙舌兰品种——有些需要长达30年才能成熟——每年只能蒸馏有限的数量。\n\n代表品牌：Del Maguey（单一村庄梅斯卡尔——每个村庄用不同的野生龙舌兰品种和本地工艺）、Montelobos（有机梅斯卡尔——平衡的风格——入门级选择）、Mezcal Vago（小批量——直接从墨西哥的微型蒸馏者（palenqueros）采购）。","label":"梅斯卡尔 Mezcal"}],"title":"龙舌兰的分类"},{"items":[{"desc":"龙舌兰 + 橙皮利口酒 + 青柠汁。盐边可选。世界最畅销的鸡尾酒之一。","label":"玛格丽特 Margarita"},{"desc":"龙舌兰 + 橙汁 + 石榴糖浆。滚石乐队在1972年巡演中用这杯酒取代了威士忌和可乐。","label":"龙舌兰日出 Tequila Sunrise"},{"desc":"龙舌兰 + 西柚苏打 + 青柠汁。墨西哥本土比玛格丽特更受欢迎的日常饮品。","label":"帕洛玛 Paloma"},{"desc":"龙舌兰 + 黑加仑利口酒 + 青柠汁 + 姜汁啤酒。甜中带辛辣。","label":"恶魔 El Diablo"},{"desc":"梅斯卡尔 + 黄查特酒 + 阿佩罗 + 青柠汁。等比例四重奏，现代经典。","label":"一柱成名 Naked and Famous"}],"title":"龙舌兰的经典配方"}]}');
INSERT INTO spirits (slug,name,eng,emoji,description,hero,details) VALUES ('whisky','威士忌','Whisky','🥃','橡木桶里的时间艺术。苏格兰的泥煤烟熏、爱尔兰的顺滑、波本的甜美——同一个名字，大西洋两岸各自成王国。','威士忌是时间的液体形态。麦芽经过发芽、烘干、糖化、发酵、蒸馏，然后进入橡木桶——在那里它可能沉睡三年，也可能沉睡三十年。每一瓶都是酒厂的签名和桶匠的手艺。','{"sections":[{"items":[{"body":"苏格兰威士忌是威士忌世界的\"黄金标准\"——世界上所有其他威士忌产区都以苏格兰为参照。苏格兰威士忌必须使用水和发芽大麦（或其他谷物）在苏格兰的蒸馏所内蒸馏、并在橡木桶中陈年至少三年。\n\n苏格兰威士忌的核心分类是：单一麦芽（Single Malt——同一蒸馏所生产的100%发芽大麦威士忌，用铜制壶式蒸馏器批量蒸馏）、调和威士忌（Blended——将多个蒸馏所的单一麦芽威士忌与谷物威士忌混合——占苏格兰威士忌全球出口的90%以上）、调和麦芽（Blended Malt——将多个蒸馏所的单一麦芽威士忌混合——不含谷物威士忌）、单桶（Single Cask——不与其他橡木桶的酒液调和，从一个橡木桶取出直接装瓶——每一桶都是独一无二的）。\n\n苏格兰威士忌的风味差异来自五个维度：产区的风土（斯佩塞的花果香、高地的蜂蜜和石南、艾雷岛的泥煤和海洋、岛屿的盐和烟雾）、泥煤的使用（用泥煤烘干麦芽——泥煤是苏格兰特有的古代植物沉积物，燃烧时释放出酚类化合物——这些酚被麦芽吸收——在威士忌中表现为烟熏、焦油和碘的风味）、水的品质（软水和硬水影响发酵和蒸馏）、蒸馏器的形状（壶式蒸馏器的高度和\"天鹅颈\"的角度——这决定了酒精蒸汽在冷凝前的回流率——更高的蒸馏器产生更轻、更细腻的烈酒）、以及橡木桶的类型和陈年时间。\n\n代表品牌：Macallan（斯佩塞雪莉桶）、Lagavulin（艾雷岛泥煤）、Glenfiddich和Glenlivet（斯佩塞经典）、Highland Park（岛屿——轻泥煤和石南蜂蜜）、Johnnie Walker（调和威士忌的全球标杆）。","label":"苏格兰威士忌 Scotch Whisky"},{"body":"爱尔兰威士忌是历史上最古老的威士忌种类之一——早在苏格兰威士忌产业诞生之前，爱尔兰就开始了威士忌的蒸馏。与苏格兰威士忌最大的区别在于：爱尔兰威士忌通常经过三次蒸馏（苏格兰通常为两次），并且大部分不使用泥煤——让它的口感更顺滑、更轻盈、更少烟熏。\n\n爱尔兰威士忌的历史跌宕起伏。19世纪中后期——爱尔兰威士忌占全球威士忌出口的60%以上——超过了苏格兰威士忌。但一系列毁灭性的事件——爱尔兰独立战争、美国的禁酒令（爱尔兰威士忌最大的出口市场突然消失）、以及苏格兰的调和威士忌和连续蒸馏器（Coffey still）的规模化生产——让爱尔兰威士忌产业在20世纪初几乎崩溃。1960年代，爱尔兰只剩下两家威士忌蒸馏所在运营。\n\n21世纪的爱尔兰威士忌正经历着有史以来最大的复兴。新蒸馏所从1987年的2家增加到今天的40家以上。\n\n代表品牌：Jameson（全球最畅销的爱尔兰威士忌——三次蒸馏——绿色苹果和香草）、Redbreast（单一壶式蒸馏爱尔兰威士忌——浓郁、油质、辛香料）、Bushmills（北爱尔兰——世界上最古老的持牌蒸馏所，1608年获得蒸馏许可证）、Middleton Very Rare（每年限量发布——爱尔兰最昂贵的威士忌之一）。","label":"爱尔兰威士忌 Irish Whiskey"},{"body":"美国波本威士忌是美国最大的威士忌类型——占全球威士忌消费的约20%。波本的法律定义为：至少51%的玉米（玉米是美国的本土谷物——这也是为什么波本产自美国）、蒸馏后酒精度不超过80% ABV、在全新的经过重度炭化处理的美国白橡木桶中陈年。最重要的是——橡木桶必须是全新的且必须只使用一次。\n\n\"全新桶\"的规定是波本风味的核心——因为新桶的萃取速度更快、单宁和木质化合物释放更浓——波本在2-6年的陈年时间内可以获得比其他威士忌类型在同期内更深厚的风味（这也是为什么波本通常比苏格兰威士忌陈年时间短——桶的\"力量\"更强）。\n\n用过一次的波本桶（used bourbon barrels）不能再次用于波本陈年——所以它们被大量出口到苏格兰、爱尔兰、日本和其他威士忌产区——用于陈年单一麦芽和其他类型的威士忌。全球威士忌产业对\"二手桶\"的巨大需求——是波本产业的一个意想不到的\"副产品\"——波本桶的经济价值几乎与波本威士忌本身一样重要。\n\n代表品牌：Maker''s Mark（手工蜡封——软红冬小麦代替黑麦——更柔和）、Woodford Reserve（铜制壶式蒸馏器手工蒸馏）、Buffalo Trace（肯塔基最古老的持续运营蒸馏所）、Jim Beam和Jack Daniel''s（全球最畅销的波本——但JD按田纳西威士忌分类——在波本的基础上加了一道枫木炭过滤工序）。","label":"美国波本 Bourbon"},{"body":"黑麦威士忌是美国最古老的威士忌类型——18世纪末宾夕法尼亚和马里兰州的黑麦田是北美最早的威士忌产业的基础。黑麦的法律定义为：至少51%的黑麦——带来辛辣、干燥和胡椒的骨架——这是黑麦威士忌的标志性风味。\n\n黑麦威士忌在19世纪是美国最主要的威士忌类型——但在禁酒令时期，几乎所有黑麦蒸馏所被关闭，战后未能恢复。20世纪后期——随着波本威士忌的崛起——黑麦几乎从美国威士忌地图上消失。2000年代早期——美国只剩下两三家黑麦蒸馏所在勉强运营。\n\n21世纪的手工鸡尾酒运动——以对经典鸡尾酒（曼哈顿、Old Fashioned、Sazerac——全部使用黑麦威士忌的历史配方）的重新关注——引爆了黑麦威士忌的复兴。2010年代——数百家新蒸馏所开始生产黑麦威士忌——今天黑麦威士忌是美国增长最快的烈酒品类之一。\n\n代表品牌：Rittenhouse（瓶装50% ABV——调酒师最喜欢的曼哈顿基酒）、WhistlePig（佛蒙特州——高端黑麦）、Michter''s（肯塔基——小批量手工黑麦）、Bulleit Rye（95%黑麦——辛辣到极致）。","label":"美国黑麦 Rye Whiskey"},{"body":"日本威士忌的历史始于1918年——竹鹤政孝独自乘船前往苏格兰学习威士忌酿造。1924年山崎蒸馏所建成——日本第一座真正的威士忌蒸馏所。1934年竹鹤在北海道创立Nikka——两家公司的对决定义了日本威士忌的版图。\n\n日本威士忌在2000年代开始获得全球认可。2003年Hibiki 30年在世界威士忌大奖中获得\"世界最佳调和威士忌\"。此后日本威士忌的国际声誉和价格飙升——稀有年份的价格在数年内翻了十倍。\n\n日本威士忌的独特之处在于水楢木桶（Mizunara Oak）——需要200年以上树龄的日本稀有橡木，释放出檀香、线香和椰子露的独特香气——世界上任何其他橡木都无法复制。另外日本蒸馏所间的协作比苏格兰更加紧密——Suntory和Nikka的蒸馏所不交换股权但交换桶——让调酒师能够使用更多样的桶资源来进行和谐配比。\n\n代表品牌：Hibiki、Yamazaki和Hakushu（Suntory）、Nikka Yoichi和Miyagikyo（Nikka）、Karuizawa（已经关闭——成为日本最昂贵的威士忌收藏品）。","label":"日本威士忌 Japanese Whisky"}],"title":"威士忌的全球版图"},{"items":[{"desc":"波本 + 方糖 + 苦精。鸡尾酒的鼻祖，最纯粹的威士忌表达。","label":"古典鸡尾酒 Old Fashioned"},{"desc":"黑麦威士忌 + 甜味美思 + 苦精。鸡尾酒的王后。","label":"曼哈顿 Manhattan"},{"desc":"波本 + 柠檬汁 + 糖浆 + 蛋清。酸甜的完美平衡。","label":"威士忌酸 Whiskey Sour"},{"desc":"波本 + 金巴利 + 甜味美思。内格罗尼的威士忌变奏。","label":"花花公子 Boulevardier"},{"desc":"苏格兰威士忌 + 柠檬汁 + 蜂蜜姜糖浆 + 泥煤威士忌漂浮。现代经典中的传奇。","label":"盘尼西林 Penicillin"}],"title":"威士忌的经典配方"}]}');
INSERT INTO spirits (slug,name,eng,emoji,description,hero,details) VALUES ('rum','朗姆','Rum','🥃','甘蔗的灵魂在加勒比海的橡木桶里跳舞。白朗姆清爽、金朗姆醇厚、黑朗姆深沉。','哥伦布在1493年把甘蔗带到加勒比海，从此这片热带群岛与朗姆酒结下了不解之缘。从海盗船到提基酒吧，朗姆是自由的液体化身。','{"sections":[{"items":[{"body":"白朗姆是朗姆世界中最清爽、最干净的类型。蒸馏后不陈年或只经过短时间的\"休息\"（resting——让烈酒在不锈钢罐中放置数周以软化，但不在橡木桶中陈年）。如果使用了橡木桶陈年——也会通过活性炭过滤去除颜色——让朗姆保持无色透明。\n\n白朗姆的风味以甘蔗的鲜甜和轻微的草本植物为主——没有橡木桶带来的香草、焦糖或烟熏味。它是调酒中最常使用的朗姆——莫吉托、大吉利和椰林飘香的传统基酒都是白朗姆。白朗姆中甘蔗的特征最鲜明——因为它没有被桶味遮盖——你喝到的是甘蔗蒸馏后最纯粹的风味。\n\n代表品牌：Bacardi Carta Blanca（波多黎各——全球最畅销的白朗姆）、Havana Club 3年（古巴——微陈年后过滤）、Diplomatico Planas（委内瑞拉——高品质白朗姆）。","label":"白朗姆 White Rum"},{"body":"金朗姆在橡木桶中陈年1至3年——桶中的单宁、香兰素和木质素释放到朗姆中，赋予它金黄色、香草和焦糖的甜感——同时仍保留了甘蔗的核心风味。金朗姆的风格介于白朗姆的清爽和黑朗姆的浓郁之间——是调酒中最\"通用\"的朗姆。\n\n金朗姆的陈年速度在热带（加勒比海和中美洲）远快于温带。加勒比海的仓库——全年温度在25-35°C——橡木桶中的化学反应在高温下加速。在热带仓储中陈年3年的朗姆——萃取的风味相当于苏格兰陈年10-12年的威士忌。这是朗姆酒陈年的独特优势。\n\n代表品牌：Mount Gay Eclipse（巴巴多斯——世界上最古老的朗姆酒厂，1703年创立）、Appleton Estate Signature（牙买加——丰富的水果和干果风味）、Bacardi Gold（波多黎各——1-2年陈年）。","label":"金朗姆 Gold Rum"},{"body":"黑朗姆通过长时间陈年（3-15年甚至更久）或在陈年后添加焦糖色来获得深色。它是最浓郁、最醇厚的朗姆类型——带有糖蜜（molasses——甘蔗糖浆的浓缩副产物）、咖啡、黑巧克力和烟熏风味。黑朗姆是所有朗姆鸡尾酒中\"力量\"最强的——在提基鸡尾酒和热带饮品中作为\"骨架朗姆\"使用。\n\nDark ''n'' Stormy（黑朗姆+姜汁啤酒+青柠汁）是黑朗姆最著名的经典鸡尾酒——用Goslings Black Seal黑朗姆制作。黑朗姆在提基文化中是必不可少的——它的浓郁风味可以在甜味利口酒、果汁和香料的围攻下保持存在感。\n\n代表品牌：Goslings Black Seal（百慕大——Dark ''n'' Stormy的传统基酒）、Myers''s（牙买加——纯黑糖蜜朗姆——浓郁甜美）、Captain Morgan Dark（全球最畅销的黑朗姆之一——加勒比海的香料和朗姆混合）。","label":"黑朗姆 Dark Rum"},{"body":"农业朗姆（Rhum Agricole）是朗姆世界中的\"另类\"——它不使用糖蜜（molasses）而是使用新鲜甘蔗汁（vesou）直接发酵和蒸馏。这种方法的产地仅限于法属加勒比岛屿——主要是马提尼克岛（Martinique）——它受法国的AOC（原产地控制）法定保护。\n\n农业朗姆的风味比糖蜜朗姆更鲜活、更草本、更植物化——它带着新鲜甘蔗的青草和蔬菜的鲜甜——没有糖蜜朗姆那种深沉的焦糖化糖浆风味。在马提尼克岛上——白农业朗姆（blanc）被用于制作\"Ti'' Punch\"（小潘趣酒——马提尼克的国民饮品：农业朗姆+蔗糖+青柠片——不加冰或只用一块小冰）。\n\n代表品牌：Clement（马提尼克——蓝甘蔗）、Rhum J.M（马提尼克——火山土种植的甘蔗）、Neisson（马提尼克——家族蒸馏所——有机农业朗姆）。","label":"农业朗姆 Rhum Agricole"}],"title":"朗姆的分类"},{"items":[{"desc":"白朗姆 + 青柠汁 + 薄荷 + 砂糖 + 苏打水。哈瓦那的清风，海明威的最爱之一。","label":"莫吉托 Mojito"},{"desc":"白朗姆 + 青柠汁 + 细砂糖。朗姆最纯粹的三角结构，海明威在哈瓦那的日常伴侣。","label":"大吉利 Daiquiri"},{"desc":"陈年朗姆 + 农业朗姆 + 橙皮利口酒 + 杏仁糖浆 + 青柠汁。波利尼西亚的魅惑。","label":"迈泰 Mai-Tai"},{"desc":"朗姆 + 椰浆 + 菠萝汁。波多黎各的官方饮品，一杯就是一场热带假期。","label":"椰林飘香 Pina Colada"},{"desc":"朗姆 + 可乐 + 青柠汁。古巴独立运动的庆祝饮品，简单到你在任何地方都能做。","label":"自由古巴 Cuba Libre"},{"desc":"三种朗姆的混合体 + 果汁 + 糖浆。Don the Beachcomber 的发明，一杯就能让复活的人都躺下。","label":"僵尸 Zombie"}],"title":"朗姆的经典配方"}]}');
INSERT INTO spirits (slug,name,eng,emoji,description,hero,details) VALUES ('gin','金酒','Gin','🍸','杜松子的清香，药草的层次。从伦敦干金到日本精酿，植物学家们用几百种药草编织风味迷宫。','杜松子、药草与酒精的三重奏。从伦敦的蒸馏厂到西班牙的海岸酒吧，金酒是鸡尾酒世界最活跃的分子——它几乎能和任何风味对话。','{"sections":[{"items":[{"body":"伦敦干金（London Dry Gin）是金酒世界中最经典、最广泛认知的风格。它不一定是\"在伦敦生产的\"——\"London Dry\"是一种法定风格标准而非地理标志：金酒必须在高度中性烈酒中加入杜松子和其他天然植物药材进行再蒸馏，蒸馏后不得添加任何人工香料、色素或额外的糖分。所有的风味必须来自蒸馏过程中与植物药材的接触。\n\n伦敦干金的风味以杜松子为主导——这是法律的要求——杜松子的松木、柑橘和微甜的芳香是伦敦干金的\"脊梁\"。在杜松子之上，每一家酒厂添加自己的秘密植物配方：芫荽籽（柑橘和辛辣）、当归根（泥土感和苦味）、鸢尾根（定香剂——帮助保留其他香气）、柠檬皮和橙皮（明亮的柑橘顶层）、甘草根（微甜的回味）。\n\n伦敦干金是最常见的调酒金酒——它的干净、明亮和杜松子主导的风味让它成为马天尼、金菲士和内格罗尼的首选金酒。代表品牌：Beefeater（伦敦——经典的杜松子主导风格）、Tanqueray（苏格兰——更饱满的杜松子和柑橘）、Bombay Sapphire（英国——10种植物药材的平衡配方）。\n\n伦敦干金的关键数字：酒精度通常在40-47% ABV之间；植物药材的浸泡时间通常在24-48小时；蒸馏后的金酒不需要陈年——\"白色\"（无色透明）是伦敦干金的标准颜色。","label":"伦敦干金 London Dry Gin"},{"body":"老汤姆金（Old Tom Gin）是金酒历史上的\"缺失环节\"——介于18世纪粗糙的甜金酒和19世纪干爽的伦敦干金之间。老汤姆金的风格是微甜的——比伦敦干金甜，但比18世纪的早期金酒干。\"Old Tom\"这个名字据说来自18世纪伦敦街头的\"老汤姆\"金酒自动售卖机——在街角放置一个黑猫形状的木制售卖机，投入一便士，机器就会从隐藏在猫脚后的管子里流出金酒。\n\n老汤姆金的甜味不是来自添加糖——而是来自使用更丰富的植物药材和稍低浓度的蒸馏（保留了更多谷物的天然甜味）。这种微甜的风格让它成为马天尼前身——马丁内斯（Martinez）的必备金酒。在马天尼演变中——当调酒师从甜金酒（老汤姆金）转向干金酒（伦敦干金）时——干马天尼诞生了。\n\n老汤姆金在21世纪手工鸡尾酒运动中经历了复兴——纽约、伦敦和旧金山的新一代蒸馏厂开始重新生产这种历史风格。代表品牌：Hayman''s Old Tom（英国——浓郁甜润）、Ransom Old Tom（美国——在葡萄酒桶中陈年）、Jensen''s Old Tom（英国——经典配方的现代重现）。","label":"老汤姆金 Old Tom Gin"},{"body":"普利茅斯金（Plymouth Gin）是金酒世界中唯一受到地理标志保护的金酒风格——只能在英格兰西南部城市普利茅斯（Plymouth）的Black Friars Distillery生产。这家蒸馏所建于1793年，曾是英国皇家海军最大的金酒供应商之一。\n\n普利茅斯金的风味比伦敦干金更柔和、更土质、更饱满。它的植物药材配方中杜松子仍然占主导——但相比伦敦干金，普利茅斯金使用了更多的柑橘皮和更少的辛辣香料——让它更\"圆润\"而非\"锐利\"。\n\n历史上，普利茅斯金是英国皇家海军的官方金酒——海军军官们在航行中将普利茅斯金与青柠汁混合（早期的Gimlet配方？）。Navy Strength（海军强度）版本的普利茅斯金——酒精度57% ABV——的历史标准是：如果将火药浸入金酒中，酒精度必须高到火药仍能点燃。如果火药点不着——说明金酒掺水了。\n\n代表品牌：Plymouth Gin（唯一的生产商——Black Friars Distillery）、Plymouth Navy Strength（57% ABV——历史的再现）。","label":"普利茅斯金 Plymouth Gin"},{"body":"新西部金（New Western Gin / New American Gin）是1990年代至2000年代美国手工蒸馏运动中最具革命性的金酒风格。它的核心理念：杜松子不再是不可动摇的\"主角\"——它是众多植物药材中的一员，可以退居次要地位，让花香、黄瓜、玫瑰、柑橘或其他植物药材走到前台。\n\n这场革命由Hendrick''s Gin（1999年推出——黄瓜和玫瑰花瓣的清香，杜松子被压制到几乎难以察觉）打响第一枪。随后的20年里，美国的小型蒸馏厂——从波特兰到布鲁克林——用当地采集的植物药材和本地风味重新定义了金酒的可能性。\n\n新西部金的争议在于：很多传统主义者认为\"不是杜松子主导的金酒不能叫金酒\"。但IBA和大多数鸡尾酒调酒师接受了这种新风格——它在鸡尾酒中的可能性太丰富了，不能被拒绝。\n\n代表品牌：Hendrick''s（苏格兰——黄瓜+玫瑰）、Monkey 47（德国黑森林——47种植物药材——世界上植物药材种类最多的金酒之一）、Aviation（美国——薰衣草和萨摩亚胡椒的柔和风格）、The Botanist（苏格兰艾雷岛——22种当地采集的植物药材）。","label":"新西部金 New Western Gin"},{"body":"荷兰金酒（Genever / Jenever）是金酒最古老的祖先——比英国金酒早了至少一百年。\"Genever\"（荷兰语）和\"Juniper\"（英语——杜松子）共享同一个词根——这暗示了荷兰是金酒的起源地。\n\n16世纪的荷兰已经使用谷物酒（麦芽酒）为基酒、加入杜松子和其他药草进行蒸馏——最初是作为利尿和肠胃疾病的药物（杜松子被认为可以净化肾脏）。荷兰独立战争（1568-1648）期间，英国士兵在荷兰战场上见到了荷兰士兵在战斗前喝\"荷兰烈酒\"（Dutch Courage——荷兰勇气）来提高士气——他们带着这种酒和配方回到了英国。\n\n荷兰金酒与英国金酒的最大区别在于基酒：荷兰金酒使用麦芽酒（malt wine）为基酒——类似于未陈年的威士忌——再加入植物药材进行再蒸馏。这个\"麦芽基底\"赋予了荷兰金酒独特的谷物饱满感——它在口感上更接近威士忌而非干爽的英国金酒。\n\n代表品牌：Bols Genever（荷兰——最大的金酒生产商，1575年创立）、Zuidam（荷兰——手工小批量）、Diep9（比利时——有机版本）。","label":"荷兰金酒 Genever"},{"body":"海军强度金酒（Navy Strength Gin）的历史可以追溯到英国皇家海军的18世纪。水手们在长期航行中依赖金酒——不仅作为饮料，也用作防腐剂（用高酒精度浸泡药草来保存医疗用品）。海军强度的法定标准是57% ABV——这恰好是火药与金酒混合后仍能被点燃的最低酒精度。英国海军用这个\"火药测试\"来确保金酒没有被水手或供应商掺水——掺水的金酒点不着火药。\n\n海军强度金酒在鸡尾酒中的使用体现了\"力度的平衡\"。更高的酒精度意味着它可以在鸡尾酒中保持更强的存在感——即使与其他强调味品（如金巴利或甜味美思）混合也不会被淹没。在内格罗尼中使用海军强度金酒——金酒的杜松子和药草不会被金巴利的苦味美思的甜味压倒——三者在一个更高的强度平面上形成新的平衡。\n\n代表品牌：Plymouth Navy Strength（57% ABV——最经典的海军强度金酒）、Hayman''s Royal Dock（57% ABV——致敬英国皇家海军）、Perry''s Tot（57% ABV——纽约手工蒸馏厂）。","label":"海军强度金酒 Navy Strength"}],"title":"金酒的分类"},{"items":[{"body":"金酒+干味美思。鸡尾酒之王。搅拌、冰镇、橄榄。越干越好是有极限的——邱吉尔的理想比例是\"看一眼味美思瓶子就够了\"。马天尼是测试任何一瓶金酒的最佳方式——不加果汁、不加糖浆——金酒的全部分子都在你的味蕾上暴露无遗。一杯好的马天尼需要一瓶好的金酒。","label":"干马天尼 Dry Martini"},{"body":"金酒+金巴利+甜味美思，1:1:1。佛罗伦萨的骄傲。苦、甜、药草在冰球上缓慢融合。内格罗尼中使用的金酒需要有一定的力度——如果金酒太柔和，它会被金巴利和味美思淹没。海军强度金酒或伦敦干金是内格罗尼的首选。","label":"内格罗尼 Negroni"},{"body":"金酒+柠檬汁+糖浆+苏打水。清爽长饮的标杆。金菲士是所有\"菲士\"（Fizz）鸡尾酒的始祖——金酒是菲士家族中最早的基酒选择。柠檬汁的酸、糖浆的甜和苏打水的起泡——在金酒的杜松子基底上形成一杯完美的夏日高球鸡尾酒。","label":"金菲士 Gin Fizz"}],"title":"金酒的经典配方"}]}');
INSERT INTO spirits (slug,name,eng,emoji,description,hero,details) VALUES ('brandy','白兰地','Brandy','🍇','葡萄酒的灵魂升华。干邑的优雅、雅文邑的粗犷、卡尔瓦多斯的苹果香、皮斯科的南美风情。','白兰地是水果的涅槃——葡萄、苹果、樱桃经过发酵和蒸馏，成为比原酒更浓烈、更复杂的烈酒。干邑和雅文邑是其中最著名的两种，但全球各地都有自己的白兰地传统。','{"sections":[{"items":[{"body":"干邑（Cognac）是白兰地世界中最受尊崇的名字——只在法国西南部干邑地区生产的白葡萄基白兰地。干邑的法定标准极为严格：必须使用特定品种的白葡萄（主要是白玉霓Ugni Blanc——高酸低糖的葡萄——做出的基酒清淡尖锐——正是这种\"不好的基酒\"在经过长时间橡木桶陈年后转化为世界上最具复杂度的白兰地）、必须在铜制壶式蒸馏器中进行两次蒸馏（与苏格兰单一麦芽威士忌相同的蒸馏原理——两次蒸馏让酒液的\"心脏\"（coeur——中间段——最干净的酒精蒸汽）被精确截取）、必须在法国橡木桶（来自利摩日或特朗赛森林）中陈年至少两年。\n\n干邑的陈年分级是白兰地界最广为使用的标准：VS（Very Special——最年轻的基酒至少陈年2年）、VSOP（Very Superior Old Pale——最年轻的基酒至少陈年4年）、XO（Extra Old——最年轻的基酒至少陈年10年——从2018年起改为最少10年）、以及超陈年级别的XXO和Hors d''Age（超龄——不限年数——通常数十年的陈酿组成）。\n\n代表品牌：Hennessy（全球最大的干邑品牌——占全球干邑出口量约40%）、Remy Martin（只使用大香槟区和小香槟区的葡萄——\"优质香槟区\"——干邑的最高法定产区）、Martell（300多年历史——比大多数欧洲国家更长寿的企业）。","label":"干邑 Cognac"},{"body":"雅文邑（Armagnac）是法国最古老的白兰地——最早的文字记录出现在1310年（比干邑早了至少300年）。它产自法国西南部的加斯科涅地区——横跨三个子产区。雅文邑与干邑最大的不同在于蒸馏方式：雅文邑通常使用柱式连续蒸馏器（Armagnac still——一种特殊的混合柱式蒸馏器——可以一次蒸馏到55-60%而不是两次）进行一次连续蒸馏——保留更多的风味前体和脂肪性物质——让雅文邑比干邑更粗犷、更饱满、更\"土质\"。\n\n雅文邑的另一个独特之处在于它的年份制度。与干邑的\"分级\"（VS/VSOP/XO——将不同年份混合以达到一致的口味）不同，雅文邑经常以\"单一年份\"（vintage）装瓶——标示葡萄采摘的年份和装瓶年份——不做调和。这让每一瓶年份雅文邑都是该年份天气、葡萄和桶陈年的时间胶囊。\n\n代表品牌：Darroze（收藏着数百个单一年份的雅文邑——横跨数十年）、Chateau de Laubade（有机葡萄——所有葡萄来自自有庄园）、Janneau（使用两种蒸馏器——壶式和柱式——进行独特的三次蒸馏工艺）。","label":"雅文邑 Armagnac"},{"body":"卡尔瓦多斯（Calvados）是法国诺曼底地区产的苹果白兰地——用发酵的苹果汁（cidre——苹果酒）蒸馏后在橡木桶中陈年。与干邑和雅文邑不同的是——卡尔瓦多斯使用的是苹果（以及一定比例的梨——有些人认为可以加10-20%的梨来增加香气的复杂度）而不是葡萄。\n\n卡尔瓦多斯的苹果不是随便的苹果——诺曼底地区有超过200个指定的苹果品种（苦涩、酸甜、甜味不同的苹果以特定的比例混合以达到最佳的香气和平衡）。苹果被压碎、榨汁、发酵制成苹果酒——然后被蒸馏成高浓度的苹果白兰地在橡木桶中陈年。陈年时间从2年到几十年不等——陈年越久——苹果的果香逐渐转化为更深层的焦糖苹果、烤坚果和干燥香料的复杂层次。\n\n代表品牌：Boulard（诺曼底最大的卡尔瓦多斯生产商）、Dupont（以年份卡尔瓦多斯闻名——从1970年代的苹果收成年份开始陈年至今）、Lemorton（家族蒸馏所——古老品种的苹果和有机种植）。","label":"卡尔瓦多斯 Calvados"},{"body":"皮斯科（Pisco）是秘鲁和智利之间的争议性白兰地——两国都声称皮斯科是\"本国\"的国饮。皮斯科使用葡萄为原料——八个（秘鲁）或十三个（智利）指定的芳香葡萄品种——在铜制壶式蒸馏器中一次蒸馏——不经过橡木桶陈年（\"不加水、不陈年\"是皮斯科的核心哲学——让葡萄最原始的花果香直接出现在烈酒中不加任何桶味的\"污染\"）。\n\n皮斯科的独特之处在于它保留了葡萄的\"活着\"的香气——不稀释不陈年意味着这些葡萄的花香和果香分子在蒸馏后立即被装在瓶子里——你是直接闻到了该葡萄品种蒸馏后的\"本质\"。品尝皮斯科像品尝一瓶\"蒸馏的液体葡萄\"——所有品种特征都在——但被浓缩了五倍。\n\n皮斯科酸（Pisco Sour——皮斯科+青柠汁+糖浆+蛋清+苦精）是皮斯科在鸡尾酒界最著名的表达——这杯酒代表了南美洲鸡尾酒的顶峰。\n\n代表品牌：Barsol（秘鲁——八种法定葡萄品种各一瓶——品鉴套装）、Alto del Carmen（智利——手工蒸馏）、Campo de Encanto（秘鲁——单一庄园皮斯科——旧金山手工鸡尾酒圈的挚爱）。","label":"皮斯科 Pisco"}],"title":"白兰地的流派"},{"items":[{"desc":"白兰地 + 橙皮利口酒 + 柠檬汁。巴黎丽兹酒店诞生的经典，糖边可选。","label":"边车 Sidecar"},{"desc":"白兰地 + 可可利口酒 + 鲜奶油。丝滑如甜点，二十世纪初的社交名饮。","label":"亚历山大 Alexander"},{"desc":"白兰地 + 方糖 + 苦精 + 苦艾酒洗杯。新奥尔良的官方饮料。","label":"萨泽拉克 Sazerac"},{"desc":"皮斯科 + 柠檬汁 + 糖浆 + 蛋清 + 苦精。秘鲁和智利的国饮。","label":"皮斯科酸 Pisco Sour"},{"desc":"白兰地 + 杏仁利口酒。简单到极致。","label":"法国连接 French Connection"}],"title":"白兰地的经典配方"}]}');
INSERT INTO articles (title,cat,author,read_time,summary,body) VALUES ('橡木桶里的炼金术：威士忌陈年全解','酿造工艺','陈默','15 分钟','一片橡木如何改变一桶无色透明的新酒？从美国白橡到欧洲橡木，从波本桶到雪莉桶——这里没有魔法，只有时间、木材和酒精的化学反应。','几乎每一间酒吧的吧台上都有一瓶安格斯特拉苦精。那个带着过大标签的小瓶子——白色标签包裹着整个瓶身，只露出一点点玻璃——是调酒师不可缺失的最后一道调味。Old Fashioned需要两滴，曼哈顿也需要两滴，香槟鸡尾酒需要一滴浸透方糖。苦精不是主角——它从来不是主角——但它是一杯好鸡尾酒和一杯伟大的鸡尾酒之间的区别。
INSERT INTO articles (title,cat,author,read_time,summary,body) VALUES ('雪莉酒的秘密：被低估的鸡尾酒灵魂','品鉴笔记','陈默','9 分钟','Fino的清瘦、Oloroso的坚果、PX的蜜糖——雪莉酒不是一种酒，而是一整个风味宇宙。','雪莉酒（Sherry）是西班牙南部安达卢西亚地区赫雷斯（Jerez de la Frontera）产的一种加强葡萄酒。它不像葡萄酒那样被广泛认知——在普通餐厅的酒单上，你很少会看到专门为雪莉酒开设的栏目。但在鸡尾酒的配方中，雪莉酒是调酒师秘密收藏的魔法盒子——Fino、Oloroso、Amontillado、Palo Cortado、PX——每一种都有完全不同的风味特征，每一种都在鸡尾酒中扮演不同的角色。
INSERT INTO articles (title,cat,author,read_time,summary,body) VALUES ('鸡尾酒的诞生：从药房到酒吧的三百年旅程','鸡尾酒历史','调酒百科编辑部','12 分钟','1806年5月13日，纽约《平衡与哥伦比亚知识库》周报首次在印刷品中定义了鸡尾酒这个词。这是一段关于药、苦味、甜味和酒精如何走到一起的故事。','1806年5月13日，纽约《平衡与哥伦比亚知识库》周报刊登了一封读者来信。读者问："什么是鸡尾酒？"编辑在回复中下了历史上第一个书面定义：鸡尾酒是一种由任意烈酒、糖、水和苦精组成的刺激性饮品。这个定义简洁到令人惊讶：烈酒、糖、水、苦精。四样东西，两百年来鸡尾酒的所有演变都建立在这个基本公式之上。
INSERT INTO articles (title,cat,author,read_time,summary,body) VALUES ('禁酒令与美国鸡尾酒的黄金时代','鸡尾酒历史','林一','10 分钟','1920年到1933年，禁酒令催生了地下酒吧文化。调酒师不得不用果汁和糖浆来掩盖劣质酒的味道——无意中创造了现代鸡尾酒的黄金时代。','1920年1月17日凌晨，美国宪法第十八修正案正式生效。生产、运输和销售酒精饮料在全国范围内成为非法行为。合法的酒吧一夜之间全部关门。数千名调酒师失业——一些人在纽约的街角卖掉他们的吧台设备，另一些人登上了去欧洲和古巴的船。
INSERT INTO articles (title,cat,author,read_time,summary,body) VALUES ('安格斯特拉苦精：从军医的药箱到每一间酒吧的吧台','基酒知识','周言','7 分钟','那张过大的标签是印刷错误的结果——兄弟俩一个设计标签、一个订购瓶子，没有沟通尺寸。错误变成了标志，一用就是两百年。','威士忌陈年的本质是橡木桶与酒液的缓慢对话。无色透明的新酒——刚从蒸馏器中流出时，它像医用酒精一样刺鼻——进入橡木桶，经过数年甚至数十年的熟成，被赋予了颜色、香气和复杂度的全新维度。这个过程被称为"成熟"（maturation），但它更准确的名字应该是"转化"——不是变老了，是被改变了。
INSERT INTO articles (title,cat,author,read_time,summary,body) VALUES ('威士忌的"天使分享"：每年蒸发2%的魔法','酿造工艺','陈默','8 分钟','每年有2%的威士忌从橡木桶中蒸发消失。苏格兰人诗意地称之为"天使分享"。但这2%去哪了，又带走了什么？','苏格兰威士忌在橡木桶中陈年时，每年平均有约2%的酒液从橡木桶中蒸发消失——进入空气中，永远不再返回。苏格兰人用他们特有的诗意称之为"天使分享"（Angel''s Share）——仿佛天使每年从每一个酒桶中取走属于他们的那一份。但这不是童话——这是冷冰冰的物理和化学：水分和酒精以不同的速率透过橡木的微小孔隙（直径约为人类头发丝的十分之一）进入周围空气。每一年、每一桶酒都在变少——这是威士忌陈年的真相，也是威士忌价值的真相。
INSERT INTO articles (title,cat,author,read_time,summary,body) VALUES ('味美思：古罗马的药方，现代吧台的秘密武器','基酒知识','周言','9 分钟','味美思是加了药草和香料的加强葡萄酒。古罗马人用它入药，18世纪意大利人把它当开胃酒。没有它就没有马天尼，也没有曼哈顿。','味美思（Vermouth）的名字来自德语的"苦艾"（Wermut）——这是味美思的核心药草之一。但味美思的实质远比名字复杂：它是用白葡萄酒为基酒，加入数十种药草、树皮、根、花和香料进行浸渍，然后用白兰地或中性烈酒加强到15-18%的酒精度，最后加糖或焦糖来平衡苦味的加强葡萄酒。简而言之——它是调酒师最复杂的调味工具。
INSERT INTO articles (title,cat,author,read_time,summary,body) VALUES ('日本威士忌：一个世纪的追赶与超越','酿造工艺','林一','11 分钟','从竹鹤政孝远赴苏格兰学艺，到山崎55年在拍卖会上创下纪录，日本用一百年走完了苏格兰五百年的路。','日本威士忌的故事始于两个年轻人的苏格兰朝圣之旅。1918年，24岁的竹鹤政孝（Masataka Taketsuru）独自乘船前往苏格兰。他的使命：学习真正的威士忌酿造工艺。他是日本清酒酿酒家族的后代——竹鹤家在日本广岛附近酿清酒已经超过了三百年。但政孝对清酒不感兴趣——他在大学里学的是化学，然后被一篇关于苏格兰威士忌的文章迷住了。他决定亲自去那里学习。
INSERT INTO articles (title,cat,author,read_time,summary,body) VALUES ('吧台背后的物理学家：摇和法 vs 搅拌法的科学','调酒师故事','林一','6 分钟','一位麻省理工毕业的调酒师用实验室设备测量了摇和的物理原理——不仅是混合，更是在给鸡尾酒注入空气、水分和温度。','Dave Arnold不是那种你会在吧台后面看到的人物。他是麻省理工学院的物理学毕业生、国际烹饪中心的食品科学教授、纽约传奇酒吧Existing Conditions的联合创始人——也是调酒史上用实验室设备做过最多定量研究的人。
INSERT INTO articles (title,cat,author,read_time,summary,body) VALUES ('马天尼杯：一个世纪的形状之争','酒具百科','周言','5 分钟','V形、圆底、带脚还是不带脚？马天尼杯的形状在百年间经历了多次演变。有人说V形是为了不让橄榄滑出来。','马天尼杯可能是全世界最容易被认出的杯型——没有其他玻璃器皿拥有如此标志性的轮廓。它的V形——优雅、锋利、像倾倒的冰锥的纵剖面——是鸡尾酒本身的视觉符号。把一杯清澈的干马天尼倒入一只马天尼杯中，金酒在V形杯壁上捕捉的光线——像液体钻石一样折射——这个画面不需要文字说明：这是一杯马天尼，这是一个懂得喝酒的人。
